/* Deutsch Trainer — C1/C2 advanced grammar + drills.
   Explanations in the chosen support language (en/fa); German stays German.
   lv: 6=C1 7=C2 · sk = skill for the "Practise this" button.
   GRAM_C1 = lessons · DRILL_C1 = gap drills keyed by lesson id (gid).
   At this level the learner rarely makes errors but still sounds foreign:
   every lesson is about choice, precision and register, not correctness.  */
window.GRAM_C1=[

/* ================= C1 ================= */

{id:'nominalstil-c1',ic:'🏛️',lv:6,sk:'Style',
 title:{en:'Nominal style, both directions',fa:'سبک اسمی، در هر دو جهت'},
 sub:{en:'Pack a clause into a noun — and unpack it again',fa:'یک جمله‌واره را در اسم بپیچ — و دوباره بازش کن'},
 blocks:[
  {type:'text',md:{en:'German formal writing compresses whole clauses into noun phrases. A subordinate clause has a conjunction, a subject and a finite verb; the nominal version has a preposition and a noun, and it is shorter, flatter and more impersonal. At C1 you are expected to move in <b>both</b> directions on demand: a report, a Gutachten or a Bewerbung wants the nominal version, while your key sentence — the one the reader must remember — usually wants the verb back.',
        fa:'نوشتار رسمی آلمانی جمله‌واره‌های کامل را در گروه‌های اسمی فشرده می‌کند. نسخهٔ اسمی کوتاه‌تر، یکدست‌تر و بی‌شخص‌تر است. در C1 باید بتوانی در <b>هر دو</b> جهت حرکت کنی: گزارش و نامهٔ رسمی نسخهٔ اسمی را می‌خواهد، اما جملهٔ کلیدی‌ات معمولاً فعل را می‌خواهد.'}},
  {type:'table',head:['Verbal clause','→ Nominal phrase','Relation'],rows:[
   ['weil die Preise gestiegen sind','*aufgrund gestiegener Preise','cause'],
   ['nachdem man die Unterlagen geprüft hat','*nach Prüfung der Unterlagen','time / sequence'],
   ['bevor das Gesetz in Kraft trat','*vor Inkrafttreten des Gesetzes','time'],
   ['damit die Kosten sinken','*zur Senkung der Kosten','purpose'],
   ['obwohl die Frist verlängert wurde','*trotz der Verlängerung der Frist','concession'],
   ['wenn der Antrag rechtzeitig eingeht','*bei rechtzeitigem Eingang des Antrags','condition'],
   ['indem man die Abläufe standardisiert','*durch Standardisierung der Abläufe','means'],
   ['soweit die Mittel es zulassen','*im Rahmen der verfügbaren Mittel','limitation']],
   cap:{en:'the conjunction becomes a preposition, the verb becomes a noun',fa:'حرف ربط به حرف اضافه و فعل به اسم تبدیل می‌شود'}},
  {type:'steps',items:[
   {en:'Find the finite verb of the subordinate clause: <i>prüfen</i>, <i>steigen</i>, <i>senken</i>.',fa:'فعل صرف‌شدهٔ جمله‌وارهٔ پیرو را پیدا کن.'},
   {en:'Turn it into its noun: <b>Prüfung, Anstieg, Senkung</b>. Most take <i>-ung</i>; many have a shorter form (<i>Eingang, Abschluss, Beginn, Verzicht</i>) that is better style.',fa:'آن را به اسم تبدیل کن؛ بیشترشان <i>-ung</i> می‌گیرند، اما شکل کوتاه‌تر سبک بهتری دارد.'},
   {en:'The subject or object of the clause becomes a <b>genitive attribute</b>: <i>die Unterlagen prüfen</i> → <b>die Prüfung der Unterlagen</b>.',fa:'فاعل یا مفعول به <b>متمم اضافی</b> (گنیتیو) تبدیل می‌شود.'},
   {en:'Replace the conjunction with the matching preposition (see the table) and drop the finite verb entirely.',fa:'حرف ربط را با حرف اضافهٔ متناظر عوض کن و فعل صرف‌شده را کامل حذف کن.'},
   {en:'Adverbs become adjectives: <i>schnell handeln</i> → <b>schnelles Handeln</b>, <i>rechtzeitig eingehen</i> → <b>rechtzeitiger Eingang</b>.',fa:'قیدها به صفت تبدیل می‌شوند.'}]},
  {type:'rule',md:{en:'A noun carries <b>one</b> genitive layer comfortably. When you need a second relation, do not stack a second genitive — hang it on a preposition: „die Entscheidung <b>des Vorstands</b> <b>über die Verlagerung</b> der Produktion“. Here <i>des Vorstands</i> says who decided and <i>über + Akkusativ</i> says what about; only <i>der Produktion</i> remains a second genitive, and it belongs to <i>Verlagerung</i>, not to <i>Entscheidung</i>. Every noun in the chain has at most one genitive of its own — that is what keeps the sentence readable.',
        fa:'هر اسم به‌راحتی <b>یک</b> لایهٔ گنیتیو را تحمل می‌کند. برای رابطهٔ دوم، گنیتیو روی گنیتیو نگذار؛ آن را به یک حرف اضافه آویزان کن: «die Entscheidung des Vorstands über die Verlagerung der Produktion». در این زنجیره هر اسم حداکثر یک گنیتیو از خودش دارد.'}},
  {type:'examples',items:[
   {de:'Nach Prüfung der Unterlagen wurde dem Antrag entsprochen.',en:'After examining the documents, the application was granted.',say:'Nach Prüfung der Unterlagen wurde dem Antrag entsprochen.'},
   {de:'Aufgrund gestiegener Energiekosten mussten die Tarife angehoben werden.',en:'Because energy costs had risen, the rates had to be raised.',say:'Aufgrund gestiegener Energiekosten mussten die Tarife angehoben werden.'},
   {de:'Zur Senkung der Verwaltungskosten wurden mehrere Abläufe zusammengelegt.',en:'In order to reduce administrative costs, several processes were merged.',say:'Zur Senkung der Verwaltungskosten wurden mehrere Abläufe zusammengelegt.'},
   {de:'Die Entscheidung des Vorstands über die Verlagerung der Produktion steht noch aus.',en:'The board’s decision on relocating production is still pending.',say:'Die Entscheidung des Vorstands über die Verlagerung der Produktion steht noch aus.'},
   {de:'Bei rechtzeitigem Eingang der Widersprüche verlängert sich das Verfahren.',en:'If the objections arrive in time, the procedure is extended.',say:'Bei rechtzeitigem Eingang der Widersprüche verlängert sich das Verfahren.'}]},
  {type:'contrast',cols:[
   {t:'Go nominal',md:{en:'• Bericht, Protokoll, Gutachten, Antrag<br>• the agent is irrelevant or obvious<br>• you are listing conditions and steps<br>• you need density: four relations in one line<br><br>„Nach Abschluss der Prüfung und unter Berücksichtigung aller Einwände …“',
       fa:'در گزارش، صورت‌جلسه، نظر کارشناسی و درخواست؛ وقتی عامل بی‌اهمیت است و به تراکم نیاز داری.'}},
   {t:'Go back to verbs',md:{en:'• the sentence that carries your claim<br>• anything spoken aloud<br>• when the agent matters: who did it<br>• when the reader must follow a process in time<br><br>„Der Vorstand hat entschieden, die Produktion zu verlagern.“',
       fa:'در جملهٔ حامل ادعا، در گفتار، وقتی عامل مهم است و وقتی خواننده باید روند را در زمان دنبال کند.'}}]},
  {type:'warn',md:{en:'The C1 trap is not failing to nominalise — it is nominalising everything. Three <i>-ung</i> nouns and two genitives in one sentence produce Beamtendeutsch: „Die Durchführung der Überprüfung der Einhaltung der Vorgaben …“. Rules of thumb: at most <b>two</b> nominalisations per sentence, never three genitives in a row, and never nominalise the sentence that states your point. If you cannot read the sentence aloud in one breath, unpack one layer back into a verb.',
        fa:'تلهٔ C1 نه کم‌استفاده از سبک اسمی است، بلکه اسمی‌کردن همه‌چیز. سه اسم <i>-ung</i> و دو گنیتیو در یک جمله «آلمانی اداری» می‌سازد. قاعدهٔ سرانگشتی: حداکثر <b>دو</b> اسم‌شده در هر جمله، هرگز سه گنیتیو پشت سر هم، و هرگز جملهٔ حامل ادعایت را اسمی نکن.'}},
  {type:'tip',md:{en:'When you unpack, work from the preposition: <i>aufgrund</i> → <i>weil</i>, <i>nach</i> → <i>nachdem</i>, <i>bei</i> → <i>wenn</i>, <i>trotz</i> → <i>obwohl</i>, <i>zur</i>/<i>zwecks</i> → <i>damit</i> or <i>um … zu</i>, <i>durch</i>/<i>mittels</i> → <i>indem</i>. The genitive attribute becomes the subject if the noun is from an intransitive verb and the object if it is from a transitive one.',
        fa:'برای بازکردن، از حرف اضافه شروع کن: aufgrund→weil، nach→nachdem، bei→wenn، trotz→obwohl، zur→damit/um…zu، durch→indem.'}},
  {type:'quiz',q:{en:'Unpack: „Trotz mehrfacher Mahnung blieb die Zahlung aus.“',fa:'باز کن: «Trotz mehrfacher Mahnung blieb die Zahlung aus.»'},
   a:'Obwohl mehrfach gemahnt wurde, blieb die Zahlung aus.',
   o:['Weil mehrfach gemahnt wurde, blieb die Zahlung aus.','Nachdem mehrfach gemahnt wurde, blieb die Zahlung aus.','Damit mehrfach gemahnt wurde, blieb die Zahlung aus.'],
   ex:{en:'<i>trotz</i> marks concession, so the clause must be <b>obwohl</b>. The nominal phrase has no agent, so the verbal version keeps it agentless with a passive.',
       fa:'<i>trotz</i> نشانهٔ تضاد است، پس جمله‌واره باید با <b>obwohl</b> باشد. گروه اسمی عامل ندارد، پس نسخهٔ فعلی هم با مجهول بی‌عامل می‌ماند.'}}
 ]},

{id:'konnektoren-c1',ic:'🧷',lv:6,sk:'Connectors',
 title:{en:'The upper register of connectors',fa:'حروف ربط سطح بالا'},
 sub:{en:'ungeachtet · zumal · sofern · mithin · gleichwohl',fa:'نشانه‌های پیوند در نوشتار رسمی'},
 blocks:[
  {type:'text',md:{en:'Every learner reaches B2 with <i>weil, obwohl, deshalb, trotzdem</i>. The connectors below say the same logical things in the register of a leading article, a legal opinion or an academic paper. They are not decoration: each one also tells the reader <b>how formal the text is</b>, so one of them in a chat message sounds as odd as <i>halt</i> in a Gutachten.',
        fa:'هر زبان‌آموز با weil، obwohl، deshalb و trotzdem به B2 می‌رسد. حروف ربط زیر همان روابط منطقی را در سطح مقالهٔ سرمقاله، نظر حقوقی یا متن دانشگاهی بیان می‌کنند. هر یک همچنین <b>درجهٔ رسمیت متن</b> را به خواننده می‌گوید.'}},
  {type:'rule',md:{en:'Before the meaning, settle the <b>syntax</b>. German connectors come in three classes and they are not interchangeable:<br>• <b>Subjunktion</b> (verb to the end): zumal, sofern, insofern als, ungeachtet dessen dass, umso mehr als<br>• <b>Konjunktionaladverb</b> (fills the Vorfeld, so the verb is second): mithin, gleichwohl, indes, nichtsdestotrotz, folglich<br>• <b>Präposition</b> (takes a case, no clause): ungeachtet + Genitiv<br>Note that <i>ungeachtet</i> appears in two classes with the same meaning.',
        fa:'پیش از معنا، <b>نحو</b> را تعیین کن. سه گروه داریم: <b>حرف ربط پیرو</b> (فعل به آخر: zumal، sofern، insofern als)، <b>قید ربطی</b> (جایگاه اول را پر می‌کند، پس فعل دوم است: mithin، gleichwohl، indes، nichtsdestotrotz) و <b>حرف اضافه</b> (ungeachtet + گنیتیو).'}},
  {type:'table',head:['Connector','Class','Meaning','Register'],rows:[
   ['*ungeachtet (+Gen)','preposition','notwithstanding, despite','formal, legal'],
   ['*geschweige denn','coordinating, after negation','let alone','written & spoken, emphatic'],
   ['*zumal','subjunktion / adverb','especially since (added strong reason)','educated, common'],
   ['*sofern','subjunktion','provided that, as long as','formal'],
   ['*insofern als','subjunktion','in so far as (restricted validity)','academic'],
   ['*indes','adverb','however; meanwhile','literary, high'],
   ['*mithin','adverb','hence, therefore (logical consequence)','legal, academic'],
   ['*gleichwohl','adverb','nevertheless','formal written'],
   ['*nichtsdestotrotz','adverb','nonetheless','formal but overused'],
   ['*umso mehr, als','subjunktion','all the more so because','argumentative essay']],
   cap:{en:'class decides word order; register decides whether you may use it at all',fa:'گروه، ترتیب کلمات را تعیین می‌کند؛ سطح زبان تعیین می‌کند که اصلاً مجاز است یا نه'}},
  {type:'examples',items:[
   {de:'Ungeachtet aller Bedenken wurde der Entwurf verabschiedet.',en:'Notwithstanding all reservations, the draft was passed.',say:'Ungeachtet aller Bedenken wurde der Entwurf verabschiedet.'},
   {de:'Der Vorschlag überzeugt, zumal er kaum Kosten verursacht.',en:'The proposal is convincing, especially since it causes hardly any costs.',say:'Der Vorschlag überzeugt, zumal er kaum Kosten verursacht.'},
   {de:'Sofern keine Einwände bestehen, gilt der Beschluss als gefasst.',en:'Provided there are no objections, the resolution is deemed adopted.',say:'Sofern keine Einwände bestehen, gilt der Beschluss als gefasst.'},
   {de:'Die Kritik trifft zu, insofern als sie allein die Kosten betrifft.',en:'The criticism is valid in so far as it concerns the costs alone.',say:'Die Kritik trifft zu, insofern als sie allein die Kosten betrifft.'},
   {de:'Die Frist ist abgelaufen; der Anspruch ist mithin verjährt.',en:'The deadline has expired; the claim is therefore time-barred.',say:'Die Frist ist abgelaufen; der Anspruch ist mithin verjährt.'},
   {de:'Die Nachfrage brach ein; die Preise blieben indes stabil.',en:'Demand collapsed; prices, however, remained stable.',say:'Die Nachfrage brach ein; die Preise blieben indes stabil.'}]},
  {type:'contrast',cols:[
   {t:'zumal ≠ weil',md:{en:'<i>weil</i> gives <b>the</b> reason. <i>zumal</i> adds a <b>further, stronger</b> reason to one already given, and it often follows a comma at the end of the sentence.<br><br>„Der Termin ist unglücklich, <b>zumal</b> die Unterlagen noch fehlen.“<br><br>You cannot open an argument with <i>zumal</i>; there must be something for it to add to.',
       fa:'<i>weil</i> دلیل را می‌دهد؛ <i>zumal</i> دلیلی <b>افزوده و قوی‌تر</b> به دلیلی که پیش‌تر آمده اضافه می‌کند. با zumal نمی‌توان استدلال را آغاز کرد.'}},
   {t:'sofern ≠ wenn',md:{en:'<i>wenn</i> is any condition. <i>sofern</i> adds a <b>reservation</b>: it restricts the claim to the case named, and it is the word of contracts and minutes.<br><br>„<b>Sofern</b> die Mittel bereitstehen, beginnt der Bau im Frühjahr.“<br><br>Close relatives: <i>soweit</i> (to the extent that), <i>vorausgesetzt, dass</i>, <i>es sei denn</i> (unless).',
       fa:'<i>wenn</i> هر شرطی است؛ <i>sofern</i> یک <b>قید احتیاط</b> می‌افزاید و ادعا را به همان حالت محدود می‌کند — واژهٔ قرارداد و صورت‌جلسه.'}}]},
  {type:'rule',md:{en:'<b>geschweige denn</b> needs three things: a preceding <b>negation</b>, a second element of the <b>same kind</b>, and ellipsis — the verb is not repeated. „Er beherrscht kein Russisch, <b>geschweige denn</b> Japanisch.“ The second item must be the <i>harder</i> case; reversing it („kein Japanisch, geschweige denn Russisch“) destroys the sense.',
        fa:'<b>geschweige denn</b> سه چیز می‌خواهد: نفیِ پیشین، عنصر دومی از همان نوع، و حذف فعل. عنصر دوم باید حالت <i>دشوارتر</i> باشد؛ جابه‌جایی‌شان معنا را نابود می‌کند.'}},
  {type:'warn',md:{en:'Three traps. <b>1.</b> Word order: <i>gleichwohl, mithin, indes, nichtsdestotrotz</i> are adverbs, so the finite verb still comes second — „<b>Gleichwohl</b> <b>bleibt</b> die Frage offen“, never <s>„Gleichwohl die Frage bleibt offen“</s>. <b>2.</b> Overuse: <i>nichtsdestotrotz</i> is the single most over-used word in learner essays — it is heavy, and <i>dennoch</i> or <i>gleichwohl</i> is usually better. <b>3.</b> <i>mithin</i> means a <b>logical</b> consequence („it follows that“), not a temporal or causal one; for „and then“ use <i>daraufhin</i>, for a real-world effect <i>infolgedessen</i>.',
        fa:'سه تله: <b>۱.</b> gleichwohl، mithin، indes و nichtsdestotrotz قید هستند، پس فعل صرف‌شده همچنان دوم است. <b>۲.</b> nichtsdestotrotz پرکاربردترین واژهٔ بیش‌ازحداستفاده‌شده در مقاله‌های زبان‌آموزان است؛ dennoch یا gleichwohl بهتر است. <b>۳.</b> mithin نتیجهٔ <b>منطقی</b> است، نه زمانی یا علّی.'}},
  {type:'tip',md:{en:'Learn them in pairs with their plain equivalent, and you will never reach for the wrong register: ungeachtet = trotz · gleichwohl = trotzdem · mithin = also/deshalb · indes = aber · sofern = wenn · zumal = besonders weil · insofern als = soweit.',
        fa:'آن‌ها را جفت‌جفت با معادل ساده‌شان یاد بگیر: ungeachtet=trotz · gleichwohl=trotzdem · mithin=also · indes=aber · sofern=wenn · zumal=besonders weil.'}},
  {type:'quiz',q:{en:'Which continuation is grammatical?',fa:'کدام ادامه دستوری درست است؟'},
   a:'Gleichwohl bleibt der Einwand berechtigt.',
   o:['Gleichwohl der Einwand bleibt berechtigt.','Gleichwohl, der Einwand bleibt berechtigt.','Gleichwohl der Einwand berechtigt bleibt.'],
   ex:{en:'<i>gleichwohl</i> is a Konjunktionaladverb: it occupies the Vorfeld, so the finite verb <b>bleibt</b> must stand in second position. It is not a Subjunktion, so no verb-final clause.',
       fa:'<i>gleichwohl</i> قید ربطی است: جایگاه اول را می‌گیرد، پس فعل صرف‌شده <b>bleibt</b> باید در جایگاه دوم بایستد.'}}
 ]},

{id:'passiv-alternativen-c1',ic:'🔁',lv:6,sk:'Passive',
 title:{en:'Everything instead of the passive',fa:'همه‌چیز به جای مجهول'},
 sub:{en:'man · sich lassen · -bar · sein + zu · bekommen',fa:'جانشین‌های مجهول و انتخاب درست'},
 blocks:[
  {type:'text',md:{en:'Germans use the <i>werden</i>-passive far less than learners do. Written German has a whole substitute system, and each member carries an extra shade of meaning that the plain passive lacks: possibility, obligation, or a particular participant pushed into focus. Choosing well is a C1 skill; the forms themselves you already know.',
        fa:'آلمانی‌زبانان مجهولِ <i>werden</i> را بسیار کمتر از زبان‌آموزان به کار می‌برند. آلمانی نوشتاری یک نظام کامل از جانشین‌ها دارد و هر کدام سایه‌ای افزوده دارد: امکان، الزام، یا تمرکز بر یک مشارک خاص. انتخاب درست مهارت C1 است.'}},
  {type:'table',head:['Construction','Example','Extra meaning / where'],rows:[
   ['*man + Aktiv','Man erwartet eine Entscheidung.','neutral, agent unknown · journalism, speech'],
   ['*sich lassen','Das Problem lässt sich lösen.','possibility · all registers'],
   ['*-bar / -lich','Der Befund ist nachvollziehbar.','possibility as a property · academic'],
   ['*sein + zu + Inf','Die Unterlagen sind einzureichen.','obligation or possibility · law, notices'],
   ['*bekommen-Passiv','Er bekam den Vertrag zugeschickt.','the Dativ participant becomes subject'],
   ['*Reflexivkonstruktion','Die Tür öffnet sich. / Das liest sich gut.','process without an agent · narrative'],
   ['*Funktionsverbgefüge','Die Regelung findet Anwendung.','impersonal, nominal · administration'],
   ['*gehören + Partizip II','Das gehört verboten.','colloquial, southern · avoid in writing']],
   cap:{en:'all eight avoid „werden“ — they are not synonyms',fa:'هر هشت مورد از werden پرهیز می‌کنند — اما هم‌معنا نیستند'}},
  {type:'rule',md:{en:'<b>sein + zu + Infinitiv</b> is the workhorse of formal German and it is ambiguous by design: „Der Antrag ist bis Freitag <b>einzureichen</b>“ = must be submitted (obligation), „Der Text ist kaum zu <b>verstehen</b>“ = can hardly be understood (possibility). Adverbs resolve it: <i>unverzüglich, bis …, zwingend</i> point to obligation; <i>kaum, leicht, ohne weiteres, nur schwer</i> point to possibility.',
        fa:'<b>sein + zu + مصدر</b> اسب بارکش آلمانی رسمی است و از طراحی دوپهلو است: با <i>unverzüglich، bis…، zwingend</i> معنای الزام و با <i>kaum، leicht، ohne weiteres</i> معنای امکان می‌دهد.'}},
  {type:'steps',items:[
   {en:'Is the point that something <b>is possible</b>? → <i>sich lassen</i> in a sentence, <i>-bar/-lich</i> if you need an attribute: „eine <b>vermeidbare</b> Verzögerung“.',fa:'اگر نکته <b>امکان</b> است: sich lassen یا صفت -bar/-lich.'},
   {en:'Is it an <b>instruction or duty</b>? → <i>sein + zu + Inf</i> in notices and contracts, <i>müssen</i> + Passiv when you want it unmistakable.',fa:'اگر <b>دستور یا وظیفه</b> است: sein + zu + مصدر، یا müssen + مجهول برای صراحت.'},
   {en:'Does the <b>recipient</b> matter more than the object? → bekommen-Passiv: „Die Mieter <b>bekommen</b> die Nebenkosten <b>erstattet</b>.“',fa:'اگر <b>دریافت‌کننده</b> مهم‌تر است: مجهولِ bekommen.'},
   {en:'Is the agent simply unknown and the style neutral? → <b>man</b>. In speech this is what Germans actually say.',fa:'اگر عامل ناشناخته و سبک بی‌طرف است: <b>man</b>؛ در گفتار همین رایج است.'},
   {en:'Is the text an official one that must sound institutional? → Funktionsverbgefüge: <i>zur Anwendung kommen, Anwendung finden, in Kraft treten, zur Auszahlung gelangen</i>.',fa:'اگر متن اداری است: ترکیب‌های فعل‌ونامی رسمی.'}]},
  {type:'examples',items:[
   {de:'Die Frist lässt sich nicht verlängern.',en:'The deadline cannot be extended.',say:'Die Frist lässt sich nicht verlängern.'},
   {de:'Der Antrag ist bis zum 30. April schriftlich einzureichen.',en:'The application must be submitted in writing by 30 April.',say:'Der Antrag ist bis zum dreißigsten April schriftlich einzureichen.'},
   {de:'Die betroffenen Haushalte bekommen die Mehrkosten erstattet.',en:'The affected households get the extra costs reimbursed.',say:'Die betroffenen Haushalte bekommen die Mehrkosten erstattet.'},
   {de:'Man geht davon aus, dass die Zahlen revidiert werden müssen.',en:'It is assumed that the figures will have to be revised.',say:'Man geht davon aus, dass die Zahlen revidiert werden müssen.'},
   {de:'Die neue Regelung findet erst ab Januar Anwendung.',en:'The new rule only applies from January onwards.',say:'Die neue Regelung findet erst ab Januar Anwendung.'},
   {de:'Der Bericht liest sich wie eine Verteidigungsschrift.',en:'The report reads like a defence statement.',say:'Der Bericht liest sich wie eine Verteidigungsschrift.'}]},
  {type:'contrast',cols:[
   {t:'man',md:{en:'Needs <b>no</b> grammatical rebuilding, keeps the verb active, and is invisible — nobody notices it.<br><br>Limits: it implies a <b>human</b> agent, so „Man zerstörte die Brücke durch den Sturm“ is wrong; it cannot be a passive subject across clauses; and in a Gutachten it is slightly too light — there you prefer passive or <i>es ist … zu</i>.',
       fa:'man بازسازی دستوری نمی‌خواهد و نامرئی است، اما عاملِ <b>انسانی</b> را پیش‌فرض می‌گیرد و در نظر کارشناسی کمی سبک است.'}},
   {t:'sich lassen',md:{en:'Adds <b>possibility</b>, never obligation. „Das lässt sich machen“ = that can be done — it does not mean anyone will do it.<br><br>Needs a real agent potential: „Der Baum lässt sich nicht umpflanzen“ is fine, but with no conceivable agent the construction breaks down.',
       fa:'sich lassen معنای <b>امکان</b> می‌افزاید، هرگز الزام. «Das lässt sich machen» یعنی می‌شود انجامش داد، نه اینکه کسی انجام خواهد داد.'}}]},
  {type:'warn',md:{en:'Two opposite traps. The learner trap is <b>too much werden-passive</b>: „Es wurde von mir ein Bericht geschrieben“ is grammatical and nobody writes it — „Ich habe einen Bericht geschrieben“ or „Ein Bericht wurde geschrieben“. The advanced trap is the opposite: once you discover Funktionsverbgefüge, every sentence becomes „kommt zur Anwendung / findet Berücksichtigung / gelangt zur Auszahlung“, and the text turns into Behördendeutsch. One per paragraph is plenty. And never combine <i>sich lassen</i> with an obligation adverb: <s>„Der Antrag lässt sich unverzüglich einreichen“</s> says it is easy to submit, not that you must.',
        fa:'دو تلهٔ متضاد: تلهٔ زبان‌آموز <b>مجهول werden بیش‌ازحد</b> است؛ تلهٔ پیشرفته، پر کردن متن از ترکیب‌های اداری (kommt zur Anwendung، findet Berücksichtigung) که متن را به زبان اداری بدل می‌کند. یکی در هر بند کافی است.'}},
  {type:'quiz',q:{en:'A public notice: „Die Gebühr ___ bis zum Monatsende zu entrichten.“',fa:'در یک اطلاعیهٔ رسمی: «Die Gebühr ___ bis zum Monatsende zu entrichten.»'},
   a:'ist',o:['lässt sich','wird','hat'],
   ex:{en:'<b>sein + zu + Infinitiv</b> expresses the duty: the fee <i>is to be paid</i>. <i>lässt sich</i> would claim it is merely possible, and <i>wird … zu entrichten</i> is not a German pattern.',
       fa:'<b>sein + zu + مصدر</b> الزام را بیان می‌کند. <i>lässt sich</i> فقط امکان را می‌گفت و <i>wird … zu entrichten</i> الگویی آلمانی نیست.'}}
 ]},

{id:'modalitaet',ic:'🎲',lv:6,sk:'Verbs',
 title:{en:'The modality system',fa:'نظام وجهیت'},
 sub:{en:'From certainty to hearsay in one scale',fa:'از یقین تا نقل قول در یک مقیاس'},
 blocks:[
  {type:'text',md:{en:'Modality is the grammar of <b>stance</b>: how sure you are, where the information came from, and whether you are reporting or claiming. English does this mostly with adverbs and „seems to“. German does it with the modal verbs you learned at A2 — used in a second, <b>subjective</b> sense that has nothing to do with permission or obligation.',
        fa:'وجهیت، دستور <b>موضع‌گیری</b> است: چقدر مطمئنی، اطلاعات از کجا آمده، و آیا نقل می‌کنی یا ادعا. انگلیسی این کار را بیشتر با قید انجام می‌دهد؛ آلمانی با همان فعل‌های کمکی وجهی در معنای دوم و <b>ذهنی</b> آن‌ها.'}},
  {type:'contrast',cols:[
   {t:'Objective modal',md:{en:'Describes the <b>world</b>: an obligation, a permission, an ability that exists outside the speaker.<br><br>„Er <b>muss</b> jeden Morgen um sechs aufstehen.“ = his job forces him.<br>„Sie <b>kann</b> Chinesisch.“ = she has the ability.',
       fa:'وجهی عینی <b>جهان</b> را توصیف می‌کند: الزام، اجازه یا توانایی‌ای که بیرون از گوینده وجود دارد.'}},
   {t:'Subjective modal',md:{en:'Describes the <b>speaker</b>: a conclusion drawn from evidence.<br><br>„Er <b>muss</b> krank sein.“ = I conclude he is ill.<br>„Sie <b>kann</b> das nicht gewusst haben.“ = I conclude she did not know.<br><br>Signal: the modal takes an <b>Infinitiv Perfekt</b> („gewesen sein“, „gewusst haben“) or a stative infinitive — an obligation reading is then impossible.',
       fa:'وجهی ذهنی <b>گوینده</b> را توصیف می‌کند: نتیجه‌ای که از قرائن می‌گیرد. نشانه‌اش مصدر کامل است («gewesen sein»، «gewusst haben»).'}}]},
  {type:'table',head:['Form','Certainty','Example'],rows:[
   ['*muss','near-certain inference','Er muss den Brief erhalten haben.'],
   ['*dürfte','probable, politely hedged','Die Zahlen dürften zu optimistisch sein.'],
   ['*wird','assumption, confident','Sie wird noch im Büro sein.'],
   ['*kann / könnte','possible / conceivable','Das könnte ein Übertragungsfehler sein.'],
   ['*mag','conceded possibility','Das mag stimmen, ändert aber nichts.'],
   ['*soll','others claim it','Der Entwurf soll überarbeitet worden sein.'],
   ['*will','the subject claims it (speaker doubts)','Der Zeuge will nichts gesehen haben.'],
   ['*kann nicht','excluded','Das kann nicht beabsichtigt gewesen sein.']],
   cap:{en:'the scale from certainty to distance — dürfte is the most useful word on it',fa:'مقیاس از یقین تا فاصله‌گیری — dürfte کاربردی‌ترین واژهٔ آن است'}},
  {type:'rule',md:{en:'<b>soll</b> and <b>will</b> are German’s evidentials. <i>soll</i> = the <b>source is other people</b>: „Die Sitzung <b>soll</b> verschoben worden sein“ = it is said the meeting was postponed; the speaker takes no responsibility. <i>will</i> = the <b>subject itself</b> claims it, and the speaker signals doubt: „Der Angeklagte <b>will</b> die Mitteilung nie erhalten haben.“ Journalists and courts live on these two words.',
        fa:'<b>soll</b> و <b>will</b> نشانگرهای منبع خبر در آلمانی‌اند. soll = <b>دیگران می‌گویند</b>؛ will = <b>خودِ فاعل</b> چنین ادعا می‌کند و گوینده شک خود را نشان می‌دهد.'}},
  {type:'table',head:['Modal adverb','Degree','Note'],rows:[
   ['zweifellos','certain','stronger than „sicher“'],
   ['offenbar / offensichtlich','evident from the facts','offensichtlich = visibly so'],
   ['vermutlich','probable','the neutral written choice'],
   ['wahrscheinlich','probable','slightly more spoken'],
   ['womöglich','possible, with unease','formal, more doubtful than „vielleicht“'],
   ['angeblich','allegedly','marks a foreign claim, like „soll“'],
   ['schwerlich','hardly','elevated negation of possibility'],
   ['mutmaßlich','presumed','press language, before a verdict']],
   cap:{en:'adverbs and modals can be combined — but one hedge per clause',fa:'قید و فعل وجهی قابل ترکیب‌اند — اما هر جمله یک تعدیل‌کننده'}},
  {type:'examples',items:[
   {de:'Die Verzögerung dürfte auf einen Formfehler zurückzuführen sein.',en:'The delay is probably due to a procedural error.',say:'Die Verzögerung dürfte auf einen Formfehler zurückzuführen sein.'},
   {de:'Der Bericht soll bereits im Mai vorgelegen haben.',en:'The report is said to have been available as early as May.',say:'Der Bericht soll bereits im Mai vorgelegen haben.'},
   {de:'Der Antragsteller will davon nichts gewusst haben.',en:'The applicant claims to have known nothing about it.',say:'Der Antragsteller will davon nichts gewusst haben.'},
   {de:'Das mag auf den ersten Blick überzeugen, hält aber der Prüfung nicht stand.',en:'That may be convincing at first sight but does not stand up to scrutiny.',say:'Das mag auf den ersten Blick überzeugen, hält aber der Prüfung nicht stand.'},
   {de:'Offenbar wurde die Frist versäumt.',en:'The deadline was evidently missed.',say:'Offenbar wurde die Frist versäumt.'},
   {de:'Vermutlich wird sich die Entscheidung bis Herbst verzögern.',en:'The decision will presumably be delayed until autumn.',say:'Vermutlich wird sich die Entscheidung bis Herbst verzögern.'}]},
  {type:'text',md:{en:'The <b>Konjunktiv</b> belongs to this system too. Konjunktiv I in reported speech („Der Sprecher erklärte, die Zahlen <b>seien</b> korrekt“) says: these are his words, not my claim — exactly what <i>soll</i> does lexically. Konjunktiv II („Das <b>wäre</b> zu prüfen“, „Man <b>könnte</b> erwägen“) lowers your own commitment, which is why proposals in formal German are so often in Konjunktiv II.',
        fa:'<b>وجه التزامی</b> هم بخشی از همین نظام است. التزامی I در نقل قول می‌گوید «این‌ها حرف اوست، نه ادعای من» — همان کاری که soll می‌کند. التزامی II تعهد خودت را پایین می‌آورد و از این رو پیشنهادها در آلمانی رسمی اغلب التزامی II‌اند.'}},
  {type:'warn',md:{en:'Three errors survive to C1. <b>1.</b> „Er <b>muss nicht</b> kommen“ does <b>not</b> mean „he mustn’t come“ — it means he does not have to; prohibition is „er <b>darf nicht</b> kommen“. <b>2.</b> <i>dürfte</i> is not permission in this use: „Das dürfte reichen“ = that should be enough, not „that would be allowed“. <b>3.</b> Over-hedging: „Vermutlich dürfte es womöglich sinnvoll sein, …“ stacks three hedges and reads as evasive. Pick one.',
        fa:'سه خطا تا C1 زنده می‌مانند: <b>۱.</b> «muss nicht» یعنی «لازم نیست»، نه «نباید»؛ نهی با <i>darf nicht</i> است. <b>۲.</b> dürfte در این کاربرد اجازه نیست. <b>۳.</b> روی هم چیدن چند تعدیل‌کننده، متن را گریزان نشان می‌دهد؛ یکی را انتخاب کن.'}},
  {type:'quiz',q:{en:'„Der Zeuge ___ den Unfall nicht bemerkt haben“ — the speaker reports the witness’s own claim and doubts it.',fa:'«Der Zeuge ___ den Unfall nicht bemerkt haben» — گوینده ادعای خود شاهد را نقل می‌کند و به آن شک دارد.'},
   a:'will',o:['soll','dürfte','möchte'],
   ex:{en:'<b>will</b> + Infinitiv Perfekt = the subject claims it of himself, with audible doubt. <i>soll</i> would attribute the claim to third parties, <i>dürfte</i> would be the speaker’s own guess.',
       fa:'<b>will</b> + مصدر کامل = فاعل این را در مورد خودش ادعا می‌کند، با شکی شنیدنی. soll ادعا را به دیگران نسبت می‌داد.'}}
 ]},

{id:'partizipialsaetze',ic:'🪆',lv:6,sk:'Clauses',
 title:{en:'Participial clauses',fa:'جمله‌واره‌های وصفی'},
 sub:{en:'„In Berlin angekommen, rief er sofort an.“',fa:'«In Berlin angekommen, rief er sofort an.»'},
 blocks:[
  {type:'text',md:{en:'A participial clause is a subordinate clause with the conjunction, the subject and the finite verb removed — only the participle and its own complements remain. „<b>Nachdem er in Berlin angekommen war</b>, rief er sofort an“ becomes „<b>In Berlin angekommen</b>, rief er sofort an.“ Six words become three, and the register rises sharply: this is a device of written German, almost never of speech.',
        fa:'جمله‌وارهٔ وصفی، جمله‌واره‌ای است که حرف ربط، فاعل و فعل صرف‌شده از آن حذف شده و تنها صفت فعلی و متمم‌هایش مانده‌اند. شش کلمه سه کلمه می‌شود و سطح زبان به‌شدت بالا می‌رود: این ابزارِ نوشتار است، تقریباً هرگز گفتار.'}},
  {type:'rule',md:{en:'Two participles, two meanings.<br>• <b>Partizip II</b> („angekommen, kritisiert, gelesen“) = the action is <b>completed</b> or <b>passive</b> — it happened before, or to, the subject.<br>• <b>Partizip I</b> („hoffend, lächelnd, haltend“) = the action is <b>simultaneous</b> and <b>active</b>.<br>And the iron condition: the participle’s implied subject must be <b>the subject of the main clause</b>. Change the main subject and the sentence collapses.',
        fa:'دو صفت فعلی، دو معنا: <b>اسم مفعول</b> (angekommen) = کنشِ <b>پایان‌یافته</b> یا <b>مجهول</b>؛ <b>وجه وصفی فاعلی</b> (haltend) = کنشِ <b>هم‌زمان</b> و <b>معلوم</b>. و شرط آهنین: فاعلِ مستترِ صفت فعلی باید <b>فاعل جملهٔ اصلی</b> باشد.'}},
  {type:'table',head:['Full clause','Participial clause'],rows:[
   ['Nachdem er in Berlin angekommen war, rief er an.','*In Berlin angekommen, rief er an.'],
   ['Da er von allen Seiten kritisiert wurde, zog er den Entwurf zurück.','*Von allen Seiten kritisiert, zog er den Entwurf zurück.'],
   ['Als man ihn auf die Vorwürfe ansprach, schwieg er.','*Auf die Vorwürfe angesprochen, schwieg er.'],
   ['Weil sie tief in Gedanken versunken war, überhörte sie die Frage.','*Tief in Gedanken versunken, überhörte sie die Frage.'],
   ['Während er ein Glas Wasser in der Hand hielt, trat er ans Mikrofon.','*Ein Glas Wasser in der Hand haltend, trat er ans Mikrofon.'],
   ['Wenn man es mit dem Vorjahr vergleicht, fällt das Ergebnis schwach aus.','*Verglichen mit dem Vorjahr, fällt das Ergebnis schwach aus.']],
   cap:{en:'the subject disappears because it is identical to the main clause subject',fa:'فاعل حذف می‌شود چون با فاعل جملهٔ اصلی یکی است'}},
  {type:'examples',items:[
   {de:'Von allen Seiten kritisiert, zog der Minister den Entwurf zurück.',en:'Criticised from all sides, the minister withdrew the draft.',say:'Von allen Seiten kritisiert, zog der Minister den Entwurf zurück.'},
   {de:'Auf die Vorwürfe angesprochen, verwies der Sprecher auf das laufende Verfahren.',en:'Asked about the accusations, the spokesman referred to the ongoing proceedings.',say:'Auf die Vorwürfe angesprochen, verwies der Sprecher auf das laufende Verfahren.'},
   {de:'Gemessen an den Zielen des Programms, ist das Ergebnis enttäuschend.',en:'Measured against the aims of the programme, the result is disappointing.',say:'Gemessen an den Zielen des Programms, ist das Ergebnis enttäuschend.'},
   {de:'Ausgehend von den vorliegenden Zahlen, erscheint eine Korrektur unvermeidlich.',en:'Starting from the available figures, a correction seems unavoidable.',say:'Ausgehend von den vorliegenden Zahlen, erscheint eine Korrektur unvermeidlich.'},
   {de:'Mit einem Stapel Unterlagen in der Hand betrat sie den Sitzungssaal.',en:'With a pile of documents in her hand she entered the meeting room.',say:'Mit einem Stapel Unterlagen in der Hand betrat sie den Sitzungssaal.'},
   {de:'Streng genommen handelt es sich um zwei getrennte Verfahren.',en:'Strictly speaking, these are two separate proceedings.',say:'Streng genommen handelt es sich um zwei getrennte Verfahren.'}]},
  {type:'table',head:['Lexicalised participle','Means','Case it takes'],rows:[
   ['verglichen mit','compared with','+ Dativ'],
   ['gemessen an','measured against','+ Dativ'],
   ['bezogen auf','in relation to','+ Akkusativ'],
   ['ausgehend von','proceeding from','+ Dativ'],
   ['abgesehen von','apart from','+ Dativ'],
   ['vorausgesetzt, dass …','provided that','clause'],
   ['angenommen, dass …','assuming that','clause'],
   ['genau / streng genommen','strictly speaking','fixed'],
   ['grob gerechnet','roughly calculated','fixed']],
   cap:{en:'these are frozen: no subject rule applies to them any more',fa:'این‌ها منجمد شده‌اند و دیگر قاعدهٔ فاعل مشترک بر آن‌ها حاکم نیست'}},
  {type:'warn',md:{en:'The dangling participle is the error that gives you away. <s>„Am Bahnhof angekommen, begann es zu regnen.“</s> — the implied subject of <i>angekommen</i> is <i>es</i>, and rain does not arrive at stations. Write „Als wir am Bahnhof angekommen waren, begann es zu regnen.“ Test every participial clause by asking <b>who</b> did the participle and checking that the main clause subject is the same person. The second trap is Partizip I: English piles up „-ing“ clauses, German uses them sparingly and they sound translated if you write three in a paragraph.',
        fa:'صفت فعلی آویزان، خطایی است که لو می‌دهد: <s>«Am Bahnhof angekommen, begann es zu regnen.»</s> — فاعل مستترِ angekommen همان <i>es</i> است و باران به ایستگاه نمی‌رسد. هر جمله‌وارهٔ وصفی را با پرسیدن «چه کسی؟» بسنج. تلهٔ دوم، وجه وصفی فاعلی است: انگلیسی آن را انبار می‌کند، آلمانی کم به کار می‌برد.'}},
  {type:'tip',md:{en:'Comma: a participial clause of more than one word is normally separated by a comma, and with one word you may leave it out („Lachend verließ er den Raum“). Position: the slot before the main clause is the natural one, because the participle then works like a Vorfeld adverbial and keeps the finite verb in second position.',
        fa:'ویرگول: جمله‌وارهٔ وصفی بیش از یک کلمه معمولاً با ویرگول جدا می‌شود. جایگاه طبیعی‌اش پیش از جملهٔ اصلی است، چون آن‌گاه مانند قید آغازین عمل می‌کند و فعل در جایگاه دوم می‌ماند.'}},
  {type:'quiz',q:{en:'Which sentence is correct?',fa:'کدام جمله درست است؟'},
   a:'In der Sitzung mehrfach darauf hingewiesen, änderte der Ausschuss seine Haltung.',
   o:['In der Sitzung mehrfach darauf hingewiesen, wurde die Haltung des Ausschusses geändert.','In der Sitzung mehrfach darauf hinweisend, änderte sich die Haltung von selbst.','In der Sitzung mehrfach darauf hingewiesen, es änderte der Ausschuss seine Haltung.'],
   ex:{en:'The participle needs the main clause subject as its own: it was <b>the committee</b> that was pointed to the matter, and the committee is the subject of <i>änderte</i>. In the other versions the subject is <i>die Haltung</i> — a stance cannot be told anything — or the word order is broken.',
       fa:'صفت فعلی باید فاعل جملهٔ اصلی را از خود بداند: به <b>کمیسیون</b> تذکر داده شد و همان کمیسیون فاعل <i>änderte</i> است. در گزینه‌های دیگر فاعل <i>die Haltung</i> است یا ترتیب کلمات شکسته.'}}
 ]},

{id:'wortbildung',ic:'🧬',lv:6,sk:'Vocabulary',
 title:{en:'Word formation as a reading tool',fa:'واژه‌سازی به‌عنوان ابزار خواندن'},
 sub:{en:'Prefixes, suffixes, Fugen — decode, don’t look up',fa:'پیشوند، پسوند، واسط — رمزگشایی کن، نه جست‌وجو'},
 blocks:[
  {type:'text',md:{en:'German builds instead of borrowing. That is why a newspaper contains words no dictionary lists — and why a C1 reader is never stopped by them. If you know the <b>prefix inventory</b>, the <b>suffix inventory</b> and the three joining elements, a 24-letter noun is readable in under two seconds.',
        fa:'آلمانی می‌سازد، وام نمی‌گیرد. از همین رو روزنامه واژه‌هایی دارد که در هیچ فرهنگ لغتی نیستند — و از همین رو خوانندهٔ C1 پشت آن‌ها متوقف نمی‌شود. با دانستن فهرست پیشوندها، پسوندها و سه عنصر واسط، اسمی ۲۴ حرفی در کمتر از دو ثانیه خواندنی است.'}},
  {type:'table',head:['Prefix','Core meaning','Example'],rows:[
   ['*ver-','away, wrongly, to the end','verlegen, versprechen (sich), verbrauchen'],
   ['*ent-','removal, undoing','entlasten, entwerten, entkommen'],
   ['*zer-','into pieces','zerstreuen, zersplittern'],
   ['*er-','achieving a result; onset','erarbeiten, erzielen, erröten'],
   ['*be-','makes the verb transitive','ein Thema behandeln, einen Raum betreten'],
   ['*miss-','wrongly, failed','missverstehen, missbilligen'],
   ['*über-','excess; across','überschätzen, überweisen'],
   ['*unter-','below; suppressing','unterschätzen, unterlassen'],
   ['*um-','change, rearrangement','umstrukturieren, umformulieren'],
   ['*nach-','afterwards, in addition','nachbessern, nachweisen']],
   cap:{en:'inseparable prefixes carry meaning, not just grammar',fa:'پیشوندهای جدانشدنی معنا می‌سازند، نه فقط دستور'}},
  {type:'table',head:['Suffix','Makes','Meaning / gender'],rows:[
   ['*-ung','noun','process or result · die'],
   ['*-heit / -keit','noun','quality · die'],
   ['*-schaft','noun','collective, relation · die'],
   ['*-nis','noun','result, state · das (mostly)'],
   ['*-tum','noun','sphere, collective · das (der Irrtum, der Reichtum)'],
   ['*-ling','noun','person, often diminishing · der'],
   ['*-bar','adjective','can be done (from transitive verbs) · machbar'],
   ['*-lich','adjective','relating to; sometimes possible · unverzeihlich'],
   ['*-haft','adjective','having the character of · fehlerhaft'],
   ['*-los / -arm / -reich','adjective','without / low in / rich in · kostenlos, zinsarm'],
   ['*-fähig / -würdig / -pflichtig','adjective','able to / worth / subject to · zahlungsfähig, förderwürdig, steuerpflichtig']],
   cap:{en:'the suffix fixes both the meaning and the gender',fa:'پسوند هم معنا و هم جنس را تعیین می‌کند'}},
  {type:'rule',md:{en:'The <b>Fugenelement</b> is the little joint between the parts of a compound, and it is not random.<br>• <b>-s-</b> after the suffixes -ung, -heit, -keit, -schaft, -tum, -ling, -ion, -tät: Zahlung<b>s</b>frist, Sicherheit<b>s</b>risiko, Wirtschaft<b>s</b>lage.<br>• <b>-(e)n-</b> after feminines in -e and after weak masculines: Straße<b>n</b>bahn, Sonne<b>n</b>energie, Student<b>en</b>ausweis.<br>• <b>-es-</b> after a few monosyllables: Tag<b>es</b>ordnung, Land<b>es</b>grenze.<br>• <b>nothing</b> otherwise: Arbeitsplatz has -s- because of <i>Arbeit</i>, but Fahrplan, Hausbau, Zeitpunkt join bare. And the <b>gender of the whole compound is the gender of the last element</b>, always.',
        fa:'<b>عنصر واسط</b> میان اجزای واژهٔ مرکب تصادفی نیست: <b>-s-</b> پس از پسوندهای -ung، -heit، -keit، -schaft، -tum، -ion؛ <b>-(e)n-</b> پس از مؤنث‌های ‎-e و مذکرهای ضعیف؛ <b>-es-</b> پس از چند تک‌هجایی؛ وگرنه هیچ. و <b>جنس واژهٔ مرکب همان جنس جزء آخر است</b>، همیشه.'}},
  {type:'steps',items:[
   {en:'Read the compound <b>from the right</b>: the last element is the head — it decides what the thing <i>is</i> and which gender it has.',fa:'واژهٔ مرکب را <b>از راست</b> بخوان: جزء آخر هستهٔ آن است و تعیین می‌کند آن <i>چه</i> است و چه جنسی دارد.'},
   {en:'Cut off any -s-, -es-, -n- that sits between two parts; it carries no meaning.',fa:'هر -s-، -es- یا -n- میان دو جزء را حذف کن؛ معنایی ندارد.'},
   {en:'Split at the suffixes you know: Arbeit|s|zeit|erfassung → Erfassung (recording) of Arbeitszeit (working time).',fa:'در پسوندهای شناخته جدا کن: Arbeit|s|zeit|erfassung.'},
   {en:'Translate right to left and keep the left parts as modifiers: <b>Nachhaltigkeitsbericht</b> = a report (Bericht) about sustainability (Nachhaltigkeit) → das.',fa:'از راست به چپ ترجمه کن و اجزای چپ را وصف نگه دار.'},
   {en:'If one part is still unknown, strip its prefix and suffix and look at the stem — <i>Entwertung</i> = ent- + Wert + -ung = the process of making worthless.',fa:'اگر جزئی ناشناخته ماند، پیشوند و پسوندش را بردار و به ریشه نگاه کن.'}]},
  {type:'examples',items:[
   {de:'die Arbeitszeiterfassung',en:'recording of working time (die, from Erfassung)',say:'die Arbeitszeiterfassung'},
   {de:'der Nachhaltigkeitsbericht',en:'sustainability report (der, from Bericht)',say:'der Nachhaltigkeitsbericht'},
   {de:'die Zahlungsaufforderung',en:'request for payment (die, from Aufforderung)',say:'die Zahlungsaufforderung'},
   {de:'das Genehmigungsverfahren',en:'approval procedure (das, from Verfahren)',say:'das Genehmigungsverfahren'},
   {de:'die Versorgungssicherheit',en:'security of supply (die, from Sicherheit)',say:'die Versorgungssicherheit'},
   {de:'die Mietpreisbremse',en:'rent price brake (die, from Bremse)',say:'die Mietpreisbremse'}]},
  {type:'warn',md:{en:'Decoding is safe; <b>inventing</b> is not. Two traps. <b>1.</b> <i>-bar</i> comes only from <b>transitive</b> verbs: <i>lesbar, machbar, vermeidbar</i> — but not <s>gehbar</s> (the verb takes no object); you need <i>begehbar</i>, with <i>be-</i> making it transitive. <b>2.</b> Not every logically possible derivation exists: Germans say <i>Erklärung</i>, not <s>Erklärbarkeit</s>, and <i>Nutzung</i> and <i>Nutzen</i> are different words. When you are unsure, use the verb — a correct clause always beats an invented noun.',
        fa:'رمزگشایی بی‌خطر است؛ <b>ساختن</b> خطرناک. <b>۱.</b> پسوند <i>-bar</i> فقط از فعل‌های <b>متعدی</b> می‌آید: lesbar، machbar؛ اما <s>gehbar</s> نه — باید begehbar. <b>۲.</b> هر مشتقِ منطقاً ممکن وجود ندارد. در تردید، از فعل استفاده کن: جمله‌واره‌ای درست همیشه بهتر از اسمی ساختگی است.'}},
  {type:'quiz',q:{en:'„die Wirtschaftlichkeitsprüfung“ — what gender and what is it?',fa:'«die Wirtschaftlichkeitsprüfung» — چه جنسی دارد و چیست؟'},
   a:'die — an examination of cost-effectiveness',
   o:['das — an examination of the economy','der — an economic examiner','die — an economically examined thing'],
   ex:{en:'The head is the last element <i>Prüfung</i>: <i>-ung</i> is always <b>die</b>, and the compound means the Prüfung of Wirtschaftlichkeit. The -s- is the Fugenelement after -keit.',
       fa:'هسته، جزء آخر <i>Prüfung</i> است: <i>-ung</i> همیشه <b>die</b> است، و کل واژه یعنی بررسی مقرون‌به‌صرفه‌بودن. ‎-s- عنصر واسط پس از ‎-keit است.'}}
 ]},

{id:'negation-skopus',ic:'🚫',lv:6,sk:'Sentences',
 title:{en:'What exactly does „nicht“ negate?',fa:'«nicht» دقیقاً چه چیزی را نفی می‌کند؟'},
 sub:{en:'Scope, position and the carriers of negation',fa:'دامنه، جایگاه و حاملان نفی'},
 blocks:[
  {type:'text',md:{en:'German has no „do not“ and no stress pattern to fall back on: the <b>position</b> of <i>nicht</i> is the only thing that tells the reader what is being denied. Move the word one slot and the sentence means something else. This is the quietest source of misunderstanding in advanced writing, because nothing looks wrong.',
        fa:'آلمانی نه «do not» دارد و نه می‌تواند به الگوی تکیه تکیه کند: <b>جایگاه</b> <i>nicht</i> تنها چیزی است که به خواننده می‌گوید چه چیزی انکار می‌شود. یک جایگاه جابه‌جا کن و معنای جمله عوض می‌شود.'}},
  {type:'rule',md:{en:'Two kinds of negation.<br>• <b>Satznegation</b> (the whole statement is denied): <i>nicht</i> stands at the <b>end of the Mittelfeld</b>, immediately before whatever closes the sentence bracket — the participle, the infinitive, the separable prefix, a predicative, or an obligatory prepositional complement. „Ich habe den Bericht <b>nicht</b> gelesen.“ „Er fährt <b>nicht</b> nach Berlin.“<br>• <b>Sondernegation</b> (one element is denied): <i>nicht</i> stands <b>directly in front of that element</b>, and a <i>sondern</i>-continuation is usually implied. „<b>Nicht</b> ich habe das behauptet.“ „Ich habe <b>nicht</b> den Bericht gelesen, sondern die Zusammenfassung.“',
        fa:'دو نوع نفی: <b>نفی جمله</b> — <i>nicht</i> در <b>پایان میدان میانی</b>، بی‌درنگ پیش از عنصر پایان‌بخش جمله می‌ایستد. <b>نفی عنصر</b> — <i>nicht</i> <b>مستقیماً پیش از همان عنصر</b> می‌ایستد و معمولاً ادامه‌ای با sondern را در خود دارد.'}},
  {type:'table',head:['Sentence','What is denied'],rows:[
   ['Ich habe den Antrag nicht unterschrieben.','*the whole statement: I did not sign it'],
   ['Nicht ich habe den Antrag unterschrieben.','*the subject: someone else signed'],
   ['Ich habe nicht den Antrag unterschrieben, sondern die Vollmacht.','*the object: I signed something else'],
   ['Ich habe den Antrag nicht gestern unterschrieben.','*the time: it was another day'],
   ['Der Vorstand hat die Entscheidung nicht einstimmig getroffen.','*the manner: it was not unanimous'],
   ['Er darf nicht kündigen.','*prohibition: negation inside the modal’s scope'],
   ['Er muss nicht kündigen.','*no obligation: negation outside the modal’s scope']],
   cap:{en:'same words, seven statements',fa:'همان کلمات، هفت گزاره'}},
  {type:'table',head:['Negationsträger','Negates','Example'],rows:[
   ['*kein','a noun with indefinite or zero article','Es gibt keinen Grund.'],
   ['*nie / niemals','time','Das wurde nie geprüft.'],
   ['*niemand','person','Niemand hat widersprochen.'],
   ['*nichts','thing','Daraus folgt nichts.'],
   ['*nirgends / nirgendwo','place','Der Hinweis findet sich nirgends.'],
   ['*keineswegs','emphatic sentence negation','Das ist keineswegs belanglos.'],
   ['*keinesfalls','emphatic prohibition','Die Frist darf keinesfalls verstreichen.'],
   ['*weder … noch','two elements at once','weder zweckmäßig noch zulässig'],
   ['*kaum','near-negation','Das ist kaum zu rechtfertigen.'],
   ['*mitnichten','emphatic denial, elevated','Davon kann mitnichten die Rede sein.']],
   cap:{en:'one negation word per clause is enough in standard German',fa:'در آلمانی معیار یک واژهٔ نفی در هر جمله کافی است'}},
  {type:'rule',md:{en:'<b>kein</b> or <b>nicht</b> with a noun? Use <i>kein</i> when the noun has an indefinite article or none at all: „Ich habe <b>keine</b> Zeit“, „Das ist <b>kein</b> Argument“. Use <i>nicht</i> when the noun has a definite article, a possessive or a demonstrative: „Ich habe <b>nicht</b> die Zeit, das zu prüfen“. Exception worth memorising: in fixed verb-noun phrases the noun stays bare and takes <i>nicht</i> — „Er spielt <b>nicht</b> Klavier“, „Sie ist <b>nicht</b> Vorsitzende“ (contrasting the office), while „Sie ist <b>keine</b> Vorsitzende“ denies the category.',
        fa:'<i>kein</i> برای اسمی که حرف تعریف نامعین دارد یا بی‌حرف تعریف است؛ <i>nicht</i> برای اسمی با حرف تعریف معین، ملکی یا اشاره. استثنا: در ترکیب‌های ثابت فعل‌ونامی، اسم بی‌حرف تعریف می‌ماند و <i>nicht</i> می‌گیرد.'}},
  {type:'examples',items:[
   {de:'Der Einwand ist keineswegs unbegründet.',en:'The objection is by no means unfounded.',say:'Der Einwand ist keineswegs unbegründet.'},
   {de:'Es wurde weder protokolliert noch mitgeteilt.',en:'It was neither recorded nor communicated.',say:'Es wurde weder protokolliert noch mitgeteilt.'},
   {de:'Nicht der Inhalt ist umstritten, sondern das Verfahren.',en:'It is not the content that is disputed but the procedure.',say:'Nicht der Inhalt ist umstritten, sondern das Verfahren.'},
   {de:'Die Mehrheit hat dem Vorschlag nicht zugestimmt.',en:'The majority did not approve the proposal.',say:'Die Mehrheit hat dem Vorschlag nicht zugestimmt.'},
   {de:'Dass die Frist nicht eingehalten wurde, blieb ohne Folgen.',en:'The fact that the deadline was missed had no consequences.',say:'Dass die Frist nicht eingehalten wurde, blieb ohne Folgen.'},
   {de:'Eine Lösung ist nicht ausgeschlossen, aber unwahrscheinlich.',en:'A solution is not ruled out, but unlikely.',say:'Eine Lösung ist nicht ausgeschlossen, aber unwahrscheinlich.'}]},
  {type:'text',md:{en:'In subordinate clauses nothing changes except that the verb cluster has moved to the end — so <i>nicht</i> sits immediately before it: „…, weil der Antrag <b>nicht</b> rechtzeitig eingegangen ist“, „…, obwohl sie den Hinweis <b>nicht</b> übersehen haben kann“. With a modal, remember that the negation lands <b>inside</b> the modal’s scope with <i>dürfen</i> („darf nicht“ = forbidden) and <b>outside</b> it with <i>müssen</i> („muss nicht“ = not required) — two scopes, one word order.',
        fa:'در جمله‌وارهٔ پیرو چیزی تغییر نمی‌کند جز اینکه خوشهٔ فعلی به پایان رفته است، پس <i>nicht</i> بی‌درنگ پیش از آن می‌ایستد. با فعل وجهی: dürfen → نفی <b>درون</b> دامنه (نهی)، müssen → نفی <b>بیرون</b> دامنه (عدم الزام).'}},
  {type:'warn',md:{en:'Three traps. <b>1.</b> Standard German does <b>not</b> double its negation for emphasis: <s>„Ich habe nichts nicht verstanden“</s>, <s>„Er hat keinem nichts gesagt“</s>. One carrier per clause. <b>2.</b> But <i>nicht un-</i> is a deliberate figure, not a mistake: „Der Vorwurf ist <b>nicht unberechtigt</b>“ means it is partly justified — careful understatement, very common in formal German. <b>3.</b> After a negation the contrast is <i>sondern</i>, never <i>aber</i>: „Nicht morgen, <b>sondern</b> übermorgen.“',
        fa:'سه تله: <b>۱.</b> آلمانی معیار برای تأکید نفی را دوبار نمی‌آورد؛ یک حامل در هر جمله. <b>۲.</b> اما <i>nicht un-</i> صنعتی آگاهانه است، نه خطا: «nicht unberechtigt» یعنی تا حدی موجه — کم‌گویی احتیاط‌آمیز. <b>۳.</b> پس از نفی، تضاد با <i>sondern</i> است، نه <i>aber</i>.'}},
  {type:'quiz',q:{en:'You want to say: the procedure, not the content, is the problem.',fa:'می‌خواهی بگویی: مشکل روش است، نه محتوا.'},
   a:'Nicht der Inhalt ist problematisch, sondern das Verfahren.',
   o:['Der Inhalt ist nicht problematisch, aber das Verfahren.','Der Inhalt ist problematisch nicht, sondern das Verfahren.','Nicht der Inhalt ist problematisch, aber das Verfahren.'],
   ex:{en:'Constituent negation puts <i>nicht</i> directly before the denied element and continues with <b>sondern</b>. <i>aber</i> cannot pick up a negation, and <i>nicht</i> never follows the predicative adjective.',
       fa:'نفی عنصر، <i>nicht</i> را مستقیماً پیش از عنصرِ انکارشده می‌گذارد و با <b>sondern</b> ادامه می‌دهد. <i>aber</i> نمی‌تواند نفی را ادامه دهد.'}}
 ]},

{id:'genitiv-c1',ic:'📜',lv:6,sk:'Cases',
 title:{en:'The Genitiv of formal German',fa:'گنیتیو در آلمانی رسمی'},
 sub:{en:'Attribute, preposition, object, adverbial',fa:'وصف، حرف اضافه، مفعول، قید'},
 blocks:[
  {type:'text',md:{en:'Spoken German is quietly abandoning the genitive: „der Wagen <b>von meinem Bruder</b>“, „<b>wegen dem</b> Wetter“. Written German is doing the opposite — the whole formal register runs on it. At C1 the genitive is less a case to survive than a register signal to deploy on purpose.',
        fa:'آلمانی گفتاری بی‌صدا گنیتیو را رها می‌کند؛ آلمانی نوشتاری خلاف آن عمل می‌کند — سراسر سطح رسمی بر آن استوار است. در C1 گنیتیو کمتر حالتی برای جان‌به‌دربردن و بیشتر نشانهٔ سطح زبان است که آگاهانه به کار می‌بری.'}},
  {type:'table',head:['Form','Use','Example'],rows:[
   ['*Genitivattribut','possession, relation, part-whole','der Bericht des Ausschusses'],
   ['*von + Dativ','obligatory when no form shows the case','der Preis von Gold, die Hälfte von uns'],
   ['*Genitivpräposition','formal adverbial relations','angesichts der Lage'],
   ['*Genitivobjekt','a handful of verbs and adjectives','Es bedarf einer Erklärung.'],
   ['*feste Wendung','frozen adverbials','meines Erachtens, eines Tages']],
   cap:{en:'four jobs, one ending set',fa:'چهار کار، یک مجموعه پایانه'}},
  {type:'table',head:['Preposition','+Gen means','Example'],rows:[
   ['*angesichts','in view of','angesichts der Datenlage'],
   ['*aufgrund','on the basis of','aufgrund eines Formfehlers'],
   ['*hinsichtlich','with regard to','hinsichtlich der Fristen'],
   ['*infolge','as a consequence of','infolge der Verzögerung'],
   ['*anlässlich','on the occasion of','anlässlich der Eröffnung'],
   ['*mangels','for lack of','mangels Beweise / mangels an Beweisen'],
   ['*mittels','by means of','mittels eines Gutachtens'],
   ['*seitens','on the part of','seitens der Behörde'],
   ['*zugunsten / zulasten','in favour of / at the expense of','zugunsten der Mieter'],
   ['*kraft','by virtue of','kraft seines Amtes'],
   ['*zwecks','for the purpose of','zwecks Überprüfung'],
   ['*unbeschadet','without prejudice to','unbeschadet weiterer Ansprüche']],
   cap:{en:'kraft, zwecks and unbeschadet are legal; the others are ordinary formal German',fa:'kraft، zwecks و unbeschadet حقوقی‌اند؛ بقیه آلمانی رسمی معمولی‌اند'}},
  {type:'rule',md:{en:'A small group of verbs still governs the genitive, and they are all formal: <b>bedürfen</b> („Es bedarf <b>keiner</b> weiteren Begründung“), <b>gedenken</b>, <b>sich bedienen</b>, <b>sich annehmen</b>, <b>sich enthalten</b>, <b>sich rühmen</b>, <b>entbehren</b>, and the two-object verbs of accusation: <b>jemanden einer Sache beschuldigen / bezichtigen / verdächtigen / überführen</b>. Adjectives too: <b>sich einer Sache bewusst / sicher / gewiss sein</b>, <b>einer Sache fähig / würdig / mächtig / verdächtig</b>, <b>eingedenk</b>.',
        fa:'گروهی کوچک از فعل‌ها هنوز گنیتیو می‌گیرند و همه رسمی‌اند: bedürfen، gedenken، sich bedienen، sich enthalten، و فعل‌های اتهام: jemanden einer Sache beschuldigen. صفت‌ها هم: sich einer Sache bewusst sein، einer Sache fähig/würdig sein.'}},
  {type:'examples',items:[
   {de:'Der Vorwurf bedarf einer sorgfältigen Prüfung.',en:'The accusation requires careful examination.',say:'Der Vorwurf bedarf einer sorgfältigen Prüfung.'},
   {de:'Man beschuldigte die Firma der Steuerhinterziehung.',en:'The company was accused of tax evasion.',say:'Man beschuldigte die Firma der Steuerhinterziehung.'},
   {de:'Ich bin mir der Tragweite dieser Entscheidung bewusst.',en:'I am aware of the significance of this decision.',say:'Ich bin mir der Tragweite dieser Entscheidung bewusst.'},
   {de:'Angesichts der Datenlage ist Zurückhaltung geboten.',en:'In view of the data, restraint is called for.',say:'Angesichts der Datenlage ist Zurückhaltung geboten.'},
   {de:'Meines Erachtens greift diese Begründung zu kurz.',en:'In my view this justification falls short.',say:'Meines Erachtens greift diese Begründung zu kurz.'},
   {de:'Der Ausschuss enthielt sich der Stimme.',en:'The committee abstained from voting.',say:'Der Ausschuss enthielt sich der Stimme.'}]},
  {type:'table',head:['Fixed genitive adverbial','Means'],rows:[
   ['eines Tages','one day'],
   ['dieser Tage','these days, shortly'],
   ['meines Erachtens / meines Wissens','in my view / as far as I know'],
   ['letzten Endes','in the end, ultimately'],
   ['schweren Herzens','with a heavy heart'],
   ['allen Ernstes','in all seriousness'],
   ['guten Mutes','in good spirits'],
   ['stehenden Fußes','on the spot, at once'],
   ['um Himmels willen','for heaven’s sake'],
   ['von Rechts wegen','by rights, legally speaking']],
   cap:{en:'learn them whole; the endings are frozen',fa:'این‌ها را دست‌نخورده یاد بگیر؛ پایانه‌هایشان منجمدند'}},
  {type:'warn',md:{en:'Four traps. <b>1.</b> The ending on the noun: masculine and neuter singular need <i>-s</i> or <i>-es</i> („des Antrag<b>s</b>“, „des Kind<b>es</b>“, „des Beschluss<b>es</b>“) — feminine and plural add nothing („der Frist“, „der Anträge“). <b>2.</b> N-Deklination survives here: „des Student<b>en</b>“, „des Name<b>ns</b>“, „des Herz<b>ens</b>“. <b>3.</b> <i>wegen dem Wetter</i> and <i>trotz dem Regen</i> are spoken forms; in writing it is <b>wegen des Wetters, trotz des Regens</b>. <b>4.</b> Do not stack: <s>„die Begründung der Entscheidung des Ausschusses des Landtags“</s>. Two genitives is the ceiling; break the third with a preposition or a relative clause.',
        fa:'چهار تله: <b>۱.</b> مذکر و خنثای مفرد ‎-s یا ‎-es می‌گیرند؛ مؤنث و جمع هیچ. <b>۲.</b> صرف ضعیف اینجا زنده است: des Studenten، des Namens. <b>۳.</b> wegen dem و trotz dem گفتاری‌اند؛ در نوشتار گنیتیو. <b>۴.</b> روی هم نچین — دو گنیتیو سقف است.'}},
  {type:'quiz',q:{en:'„Der Beschluss erfolgte ___ ausdrücklichen Widerspruchs des Betriebsrats.“',fa:'«Der Beschluss erfolgte ___ ausdrücklichen Widerspruchs des Betriebsrats.»'},
   a:'ungeachtet des',o:['ungeachtet dem','entgegen des','trotz dem'],
   ex:{en:'<i>ungeachtet</i> takes the <b>Genitiv</b>: <b>des</b> ausdrücklichen Widerspruchs. <i>entgegen</i> takes the Dativ, and <i>trotz dem</i> is spoken usage.',
       fa:'<i>ungeachtet</i> <b>گنیتیو</b> می‌گیرد. <i>entgegen</i> داتیو می‌گیرد و <i>trotz dem</i> کاربرد گفتاری است.'}}
 ]},

{id:'thema-rhema',ic:'🧵',lv:6,sk:'Style',
 title:{en:'Given before new',fa:'شناخته پیش از نو'},
 sub:{en:'Thema–Rhema: why a correct paragraph can feel wrong',fa:'موضوع–خبر: چرا بندی درست، غلط حس می‌شود'},
 blocks:[
  {type:'text',md:{en:'You can write a paragraph in which every sentence is correct and the whole thing still reads like a staircase with missing steps. Almost always the cause is information structure: German wants <b>known information early</b> and <b>new information late</b>. The Vorfeld — the slot before the finite verb — is the hook that attaches the sentence to the one before it; the end of the sentence is where the news goes.',
        fa:'می‌توان بندی نوشت که هر جمله‌اش درست باشد و با این حال مانند پله‌ای با پله‌های گم‌شده خوانده شود. علت تقریباً همیشه ساختار اطلاعات است: آلمانی اطلاعات <b>شناخته</b> را زود و اطلاعات <b>نو</b> را دیر می‌خواهد. جایگاه آغازین قلاب اتصال به جملهٔ پیشین است؛ پایان جمله جای خبر.'}},
  {type:'rule',md:{en:'<b>Thema</b> = what the sentence is about, already in the reader’s head. <b>Rhema</b> = what you are adding. Default order: Thema … Rhema. German word order is free enough to obey this almost always, so if a sentence resists, the problem is usually the <b>voice</b> or the <b>subject</b> you chose, not the word order itself.',
        fa:'<b>موضوع</b> = آنچه جمله درباره‌اش است و از پیش در ذهن خواننده است. <b>خبر</b> = آنچه می‌افزایی. ترتیب پیش‌فرض: موضوع … خبر. اگر جمله‌ای مقاومت کرد، مشکل معمولاً جهتِ فعل یا فاعلی است که برگزیده‌ای، نه خودِ ترتیب کلمات.'}},
  {type:'contrast',cols:[
   {t:'Feels wrong',md:{en:'„Die Kommission legte im Mai einen Bericht vor. <b>Erhebliche Mängel bei der Vergabe</b> stellte der Bericht fest. <b>Eine Neuausschreibung</b> fordert der Verband nun.“<br><br>Every sentence starts with news. The reader has to carry three unconnected openings and build the thread themselves.',
       fa:'هر جمله با خبر آغاز می‌شود. خواننده باید سه آغازِ بی‌ارتباط را حمل کند و رشته را خودش بسازد.'}},
   {t:'Feels right',md:{en:'„Die Kommission legte im Mai einen Bericht vor. <b>Darin</b> stellt sie erhebliche Mängel bei der Vergabe fest. <b>Der Verband</b> fordert deshalb eine Neuausschreibung.“<br><br>Each Vorfeld points backwards (<i>darin, deshalb</i>) and the new element lands at the end of its sentence.',
       fa:'هر جایگاه آغازین به عقب اشاره می‌کند (darin، deshalb) و عنصر نو در پایان جملهٔ خود می‌نشیند.'}}]},
  {type:'table',head:['Tool','What it does','Example'],rows:[
   ['*Passiv','deletes the agent so the known object can be subject','Der Bericht wurde im Mai vorgelegt.'],
   ['*Pronominaladverb','puts the previous sentence into one word','darin, dabei, hierfür, demgegenüber'],
   ['*Adverbial im Vorfeld','a time or place link instead of the subject','Im Mai legte die Kommission …'],
   ['*dies / das / letzterer','picks up a whole clause','Dies wirft die Frage auf, ob …'],
   ['*es-Vorfeld','holds the slot when everything is new','Es wurden drei Varianten geprüft.'],
   ['*Linksversetzung','spoken emphasis, avoid in writing','Der Bericht, der ist eindeutig.']],
   cap:{en:'all six serve one purpose: putting the known part first',fa:'هر شش ابزار یک هدف دارند: اول آوردن بخش شناخته'}},
  {type:'steps',items:[
   {en:'Mark the <b>first three words</b> of every sentence in your paragraph.',fa:'<b>سه کلمهٔ اول</b> هر جمله را علامت بزن.'},
   {en:'Ask of each: does this already exist in the reader’s head? If more than one opening is brand new, the paragraph will feel disjointed.',fa:'از هر کدام بپرس: این از پیش در ذهن خواننده هست؟ اگر بیش از یک آغاز تازه باشد، بند گسیخته حس می‌شود.'},
   {en:'Now mark the <b>last three words</b>. Each should be the point of that sentence — if the news is in the middle, rebuild.',fa:'سه کلمهٔ آخر را علامت بزن؛ باید نکتهٔ همان جمله باشند.'},
   {en:'Repair a new opening by promoting it to the object of a passive, or by replacing it with <i>dies / darin / dabei / deshalb</i>.',fa:'آغاز نو را با مجهول‌کردن یا با dies/darin/dabei/deshalb اصلاح کن.'},
   {en:'Read the first words alone, in order. They should form a readable chain — that chain <b>is</b> the cohesion of your text.',fa:'کلمات اول را به‌تنهایی و به ترتیب بخوان؛ باید زنجیری خواندنی بسازند — همان زنجیر، پیوستگی متن است.'}]},
  {type:'examples',items:[
   {de:'Der Entwurf liegt seit Montag vor. Dagegen hat der Betriebsrat Einwände erhoben.',en:'The draft has been available since Monday. The works council has raised objections to it.',say:'Der Entwurf liegt seit Montag vor. Dagegen hat der Betriebsrat Einwände erhoben.'},
   {de:'Zwei Varianten wurden geprüft. Für die zweite spricht vor allem der Preis.',en:'Two variants were examined. The second is favoured above all by the price.',say:'Zwei Varianten wurden geprüft. Für die zweite spricht vor allem der Preis.'},
   {de:'Die Frist wurde versäumt. Darauf beruft sich die Gegenseite.',en:'The deadline was missed. The other side is relying on that.',say:'Die Frist wurde versäumt. Darauf beruft sich die Gegenseite.'},
   {de:'Es wurden keine Unterlagen übermittelt. Dies erschwert die Bewertung erheblich.',en:'No documents were submitted. This makes the assessment considerably harder.',say:'Es wurden keine Unterlagen übermittelt. Dies erschwert die Bewertung erheblich.'},
   {de:'Über die Kosten schweigt der Bericht. Hierzu fehlt jede Angabe.',en:'The report says nothing about costs. There is no information at all on this.',say:'Über die Kosten schweigt der Bericht. Hierzu fehlt jede Angabe.'}]},
  {type:'warn',md:{en:'Two opposite failures. <b>Overloading the Vorfeld</b>: „Die aufgrund der im Mai vorgelegten Prüfungsergebnisse erforderliche Neubewertung der Vergabekriterien ist …“ — by the time the verb arrives the reader has given up; the Vorfeld should hold a <b>short</b> link, not a nominal monster. And <b>subject monotony</b>: starting nine sentences with <i>Ich</i> or with the same institution. Varying the Vorfeld is not decoration; it is how the German reader tracks what the text is about.',
        fa:'دو شکست متضاد: <b>پر کردن افراطی جایگاه آغازین</b> — تا فعل برسد خواننده تسلیم شده است؛ این جایگاه باید قلابی <b>کوتاه</b> باشد، نه هیولایی اسمی. و <b>یکنواختی فاعل</b> — آغاز نه جمله با یک واژه. تنوع جایگاه آغازین تزئین نیست؛ راهی است که خوانندهٔ آلمانی موضوع متن را دنبال می‌کند.'}},
  {type:'tip',md:{en:'The passive is not a politeness device in German, it is a word-order device. Use it exactly when the known participant happens to be the object of the verb: „Der Antrag wurde abgelehnt“ keeps <i>der Antrag</i> — already known — in first position, which the active „Die Behörde lehnte den Antrag ab“ cannot do.',
        fa:'مجهول در آلمانی ابزار ادب نیست، ابزار ترتیب کلمات است. درست وقتی به کارش ببر که مشارکِ شناخته، مفعولِ فعل باشد.'}},
  {type:'quiz',q:{en:'„Der Ausschuss hat den Bericht angefordert.“ Which sentence continues the paragraph best?',fa:'«Der Ausschuss hat den Bericht angefordert.» کدام جمله بند را بهتر ادامه می‌دهد؟'},
   a:'Vorgelegt wurde er bis heute nicht.',
   o:['Das Ministerium hat ihn bis heute nicht vorgelegt, was den Ausschuss verärgert.','Eine Vorlage des Berichts durch das Ministerium ist bis heute nicht erfolgt.','Bis heute nicht vorgelegt hat das Ministerium den Bericht.'],
   ex:{en:'The known element is <b>der Bericht</b>, so a passive lets it stay in the Vorfeld as <i>er</i> and puts the news („nicht vorgelegt“) at the end. The first option opens with a brand-new subject, the second is heavily nominalised, the third is a forced Vorfeld.',
       fa:'عنصر شناخته <b>der Bericht</b> است، پس مجهول اجازه می‌دهد به‌صورت <i>er</i> در جایگاه آغازین بماند و خبر در پایان بنشیند.'}}
 ]},

{id:'verbaspekt',ic:'⏳',lv:6,sk:'Verbs',
 title:{en:'Aspect without an aspect system',fa:'نمود، بدون نظام نمود'},
 sub:{en:'Aktionsart, am-Progressiv, dabei sein zu',fa:'نوع کنش، صورت استمراری، dabei sein zu'},
 blocks:[
  {type:'text',md:{en:'German has no progressive form and no perfective/imperfective pair, so everything English does with „is reading“ and „has been reading“ must be carried by the <b>lexicon</b>: by a prefix, by a different verb, or by an adverb. This is why learners who translate tense for tense sound subtly off even when every form is right.',
        fa:'آلمانی نه صورت استمراری دارد و نه جفت کامل/ناکامل؛ پس هر کاری که انگلیسی با «is reading» و «has been reading» می‌کند باید با <b>واژگان</b> حمل شود: با پیشوند، با فعلی دیگر، یا با قید.'}},
  {type:'table',head:['Prefix','Aktionsart','Pair'],rows:[
   ['*an-','beginning, partial','braten → anbraten (to brown lightly)'],
   ['*auf-','sudden onset, opening','blühen → aufblühen, schreien → aufschreien'],
   ['*ver-','running out, consuming','blühen → verblühen, brauchen → verbrauchen'],
   ['*er-','reaching the result','arbeiten → erarbeiten, kämpfen → erkämpfen'],
   ['*aus-','carrying through to the end','trinken → austrinken, diskutieren → ausdiskutieren'],
   ['*durch-','completing from end to end','lesen → durchlesen, arbeiten → durcharbeiten'],
   ['*ab-','working off a quantity','arbeiten → abarbeiten, zahlen → abzahlen'],
   ['*zer-','breaking apart','fallen → zerfallen']],
   cap:{en:'the prefix is where German keeps its aspect',fa:'آلمانی نمود خود را در پیشوند نگه می‌دارد'}},
  {type:'table',head:['State','Change of state'],rows:[
   ['schlafen (to be asleep)','*einschlafen (to fall asleep)'],
   ['kennen (to know someone)','*kennenlernen (to get to know)'],
   ['wissen (to know a fact)','*erfahren (to find out)'],
   ['sitzen (to be sitting)','*sich setzen (to sit down)'],
   ['stehen (to be standing)','*aufstehen (to stand up)'],
   ['liegen (to lie)','*sich legen (to lie down)'],
   ['haben (to have)','*bekommen (to get)'],
   ['verstehen (to understand)','*begreifen (to grasp, at a point in time)']],
   cap:{en:'German distinguishes state and change lexically, English often does not',fa:'آلمانی حالت و تغییرِ حالت را واژگانی جدا می‌کند؛ انگلیسی اغلب نه'}},
  {type:'rule',md:{en:'Four ways to say „is just now doing it“, in rising formality:<br>• <b>gerade</b> + Präsens — the standard, safe everywhere: „Sie <b>prüft gerade</b> die Unterlagen.“<br>• <b>am + nominalisierter Infinitiv</b> („am Überlegen sein“) — colloquial, strongest in the Rhineland, fine in speech, out of place in an essay.<br>• <b>dabei sein, etwas zu tun</b> — neutral and fully written: „Die Kommission <b>ist dabei</b>, die Kriterien zu überarbeiten.“<br>• <b>beim + nominalisierter Infinitiv</b> — for simultaneity: „<b>Beim Lesen</b> des Gutachtens fiel mir auf, dass …“',
        fa:'چهار راه برای گفتن «همین حالا دارد انجام می‌دهد»، به ترتیب رسمیت: <b>gerade</b> + حال (معیار)؛ <b>am + مصدر اسم‌شده</b> (گفتاری)؛ <b>dabei sein, zu …</b> (بی‌طرف و نوشتاری)؛ <b>beim + مصدر اسم‌شده</b> (هم‌زمانی).'}},
  {type:'examples',items:[
   {de:'Die Kommission ist dabei, die Kriterien zu überarbeiten.',en:'The commission is in the process of revising the criteria.',say:'Die Kommission ist dabei, die Kriterien zu überarbeiten.'},
   {de:'Ich habe das Gutachten über Nacht durchgelesen.',en:'I read the whole report overnight.',say:'Ich habe das Gutachten über Nacht durchgelesen.'},
   {de:'Wir haben das Thema inzwischen ausdiskutiert.',en:'We have now discussed the topic through to the end.',say:'Wir haben das Thema inzwischen ausdiskutiert.'},
   {de:'Das Interesse der Öffentlichkeit ist längst verflogen.',en:'Public interest has long since evaporated.',say:'Das Interesse der Öffentlichkeit ist längst verflogen.'},
   {de:'Erst im Gespräch habe ich von der Entscheidung erfahren.',en:'I only found out about the decision in the conversation.',say:'Erst im Gespräch habe ich von der Entscheidung erfahren.'},
   {de:'Beim Durchsehen der Zahlen fiel die Abweichung auf.',en:'When going through the figures, the discrepancy stood out.',say:'Beim Durchsehen der Zahlen fiel die Abweichung auf.'}]},
  {type:'text',md:{en:'Duration up to now is the other half of the problem. English uses the perfect („I have been working here for three years“); German uses the <b>present</b> with <i>seit</i>: „Ich <b>arbeite</b> seit drei Jahren hier.“ A German perfect here („Ich habe hier drei Jahre gearbeitet“) says the job is <b>over</b>. The same logic with <i>schon</i>, <i>bisher</i> and <i>bis heute</i>: present tense as long as the situation still holds.',
        fa:'نیمهٔ دیگر مسئله، تداوم تا کنون است. انگلیسی از ماضی نقلی استفاده می‌کند؛ آلمانی از <b>حال</b> با <i>seit</i>: «Ich arbeite seit drei Jahren hier.» ماضیِ آلمانی در اینجا یعنی کار <b>تمام شده</b> است.'}},
  {type:'warn',md:{en:'Three interference errors. <b>1.</b> <s>„Ich bin arbeitend“</s> does not exist — German has no progressive participle as a predicate. <b>2.</b> <i>am</i>-Progressiv in formal writing („Die Behörde ist am Prüfen“) marks the text as spoken; use <i>prüft gerade</i> or <i>ist dabei, zu prüfen</i>. <b>3.</b> Mapping „for three years“ onto the perfect: „Ich habe seit drei Jahren hier gearbeitet“ is wrong unless you have stopped. And beware the prefix that changes more than aspect: <i>verlesen</i> is not „to read to the end“ but „to read out“ — or, reflexively, „to misread“.',
        fa:'سه خطای تداخلی: <b>۱.</b> <s>«Ich bin arbeitend»</s> وجود ندارد. <b>۲.</b> صورت am در نوشتار رسمی، متن را گفتاری نشان می‌دهد. <b>۳.</b> «for three years» را به ماضی نقلی نبر؛ با <i>seit</i> زمان حال لازم است.'}},
  {type:'quiz',q:{en:'„Wir ___ seit zwei Jahren an diesem Verfahren“ — and we still are.',fa:'«Wir ___ seit zwei Jahren an diesem Verfahren» — و همچنان ادامه دارد.'},
   a:'arbeiten',o:['haben gearbeitet','sind am Arbeiten','arbeiteten'],
   ex:{en:'A situation that still holds takes the <b>Präsens</b> with <i>seit</i>. The perfect would say the work is finished, and the <i>am</i>-form is colloquial and adds nothing here.',
       fa:'وضعیتی که همچنان برجاست با <i>seit</i> زمان <b>حال</b> می‌گیرد. ماضی نقلی می‌گفت کار تمام شده است.'}}
 ]},

{id:'ellipse',ic:'✂️',lv:6,sk:'Style',
 title:{en:'What German leaves out',fa:'آنچه آلمانی حذف می‌کند'},
 sub:{en:'Ellipsis, Ausklammerung and headline style',fa:'حذف، بیرون‌گذاری و سبک تیتر'},
 blocks:[
  {type:'text',md:{en:'Advanced German is as much about omission as about construction. In coordination you may drop everything the two halves share; at the end of the sentence you may push heavy material out of the bracket; and in headlines and notices a whole grammar of its own takes over, with no articles and often no verb. Each of these is <b>licensed</b> omission — leaving out the wrong thing is simply an error.',
        fa:'آلمانی پیشرفته به‌همان‌اندازه که دربارهٔ ساختن است، دربارهٔ حذف است. در همپایگی می‌توان هر چیزِ مشترک را انداخت؛ در پایان جمله می‌توان بار سنگین را بیرون از کمانهٔ فعل گذاشت؛ و در تیتر و اطلاعیه دستور زبانی ویژه حاکم می‌شود. اما حذفِ چیز نادرست، خطاست.'}},
  {type:'rule',md:{en:'<b>Coordination ellipsis</b>: an element may be dropped in the second half only if it would have had <b>exactly the same grammatical form</b> there. „Er hat den Antrag geprüft und [den Antrag] genehmigt“ works, because <i>den Antrag</i> is accusative both times. But <s>„Ich habe und werde das nie behaupten“</s> fails: the first half needs the participle <i>behauptet</i>, the second the infinitive <i>behaupten</i> — different forms, no ellipsis. Write „Ich habe das nie behauptet und werde es auch nie behaupten.“',
        fa:'<b>حذف در همپایگی</b>: عنصری را می‌توان در نیمهٔ دوم انداخت تنها اگر در آنجا <b>دقیقاً همان شکل دستوری</b> را می‌داشت. از این رو <s>«Ich habe und werde das nie behaupten»</s> نادرست است: نیمهٔ اول اسم مفعول می‌خواهد و نیمهٔ دوم مصدر.'}},
  {type:'table',head:['Full','Elliptical','Licensed?'],rows:[
   ['Er prüfte den Antrag und er genehmigte den Antrag.','*Er prüfte und genehmigte den Antrag.','yes — same case, same form'],
   ['Sie war müde und sie war enttäuscht.','*Sie war müde und enttäuscht.','yes'],
   ['Ich habe es nie behauptet und ich werde es nie behaupten.','Ich habe und werde es nie behaupten.','*no — participle ≠ infinitive'],
   ['Der Bericht ist fertig, und die Anlagen sind fertig.','*Der Bericht ist fertig, die Anlagen auch.','yes — with auch'],
   ['Er wollte zustimmen, aber er konnte nicht zustimmen.','*Er wollte zustimmen, konnte es aber nicht.','yes — with the pronoun es'],
   ['Wir haben mit ihm gesprochen und wir haben ihm geschrieben.','Wir haben mit ihm gesprochen und geschrieben.','*no — different government: mit + Dativ / Dativ object']],
   cap:{en:'the test is always: would the dropped element have had an identical form?',fa:'آزمون همیشه این است: آیا عنصر حذف‌شده همان شکل را می‌داشت؟'}},
  {type:'text',md:{en:'<b>Ausklammerung</b> is the opposite move: instead of squeezing everything between the two parts of the verb, you let the heavy element fall out behind the closing bracket, into the <b>Nachfeld</b>. „Wir haben lange gesprochen <b>über die Folgen des Beschlusses</b>“ instead of „Wir haben lange über die Folgen des Beschlusses gesprochen.“ It is standard and unremarkable with comparisons („Es war teurer, <b>als wir dachten</b>“), relative clauses and infinitive clauses; with plain prepositional phrases it is journalistic and spoken, and in exam writing it is better avoided.',
        fa:'<b>بیرون‌گذاری</b> حرکت معکوس است: عنصر سنگین را پس از کمانهٔ بستهٔ فعل، در <b>میدان پسین</b> رها می‌کنی. با مقایسه‌ها، جمله‌وارهٔ وصفی و مصدری کاملاً معیار است؛ با گروه‌های اضافهٔ ساده، روزنامه‌ای و گفتاری است و در نوشتار آزمون بهتر است پرهیز شود.'}},
  {type:'examples',items:[
   {de:'Das Ergebnis fiel schlechter aus, als der Vorstand erwartet hatte.',en:'The result turned out worse than the board had expected.',say:'Das Ergebnis fiel schlechter aus, als der Vorstand erwartet hatte.'},
   {de:'Man hat sich darauf verständigt, die Frist zu verlängern.',en:'An agreement was reached to extend the deadline.',say:'Man hat sich darauf verständigt, die Frist zu verlängern.'},
   {de:'Er hat alles unterschrieben, was ihm vorgelegt wurde.',en:'He signed everything that was put in front of him.',say:'Er hat alles unterschrieben, was ihm vorgelegt wurde.'},
   {de:'Geprüft wurde nur die Form, nicht der Inhalt.',en:'Only the form was examined, not the content.',say:'Geprüft wurde nur die Form, nicht der Inhalt.'},
   {de:'Sie wollte widersprechen, traute sich aber nicht.',en:'She wanted to object but did not dare.',say:'Sie wollte widersprechen, traute sich aber nicht.'}]},
  {type:'table',head:['Headline / notice','Full sentence'],rows:[
   ['Verhandlungen gescheitert','Die Verhandlungen sind gescheitert.'],
   ['Regierung vor schwieriger Entscheidung','Die Regierung steht vor einer schwierigen Entscheidung.'],
   ['Zutritt nur für Befugte','Der Zutritt ist nur für Befugte erlaubt.'],
   ['Bilanz: enttäuschend','Die Bilanz ist enttäuschend.'],
   ['Antrag abgelehnt — Begründung folgt','Der Antrag wurde abgelehnt; die Begründung folgt.'],
   ['Kein Durchgang während der Bauarbeiten','Während der Bauarbeiten ist kein Durchgang möglich.']],
   cap:{en:'articles and the finite verb go first; the participle survives',fa:'نخست حرف تعریف و فعل صرف‌شده می‌روند؛ اسم مفعول می‌ماند'}},
  {type:'warn',md:{en:'Headline grammar is a <b>register</b>, not a shortcut. Dropping articles inside a normal text („Antrag wurde geprüft“) reads as a telegram or as foreign, not as concise. Equally, do not carry the colon style into prose — one „Fazit: unklar“ per text is a stylistic device, three is a list. And the most frequent real error here is the coordination of unequal verb forms: <s>„Das Problem wurde erkannt und wird gelöst werden müssen“</s> drops nothing but stacks three auxiliaries; split the sentence instead.',
        fa:'دستور تیتر یک <b>سطح زبانی</b> است، نه میان‌بُر. انداختن حرف تعریف در متن عادی، تلگرافی یا بیگانه خوانده می‌شود، نه موجز. و رایج‌ترین خطای واقعی، همپایه‌کردن شکل‌های نابرابر فعل است؛ جمله را بشکن.'}},
  {type:'tip',md:{en:'A reliable test for any ellipsis: write the full version, then delete, then read the short version aloud <b>as if you had never seen the long one</b>. If you can still reconstruct the missing word in exactly one way, the ellipsis is safe.',
        fa:'آزمونی مطمئن: نسخهٔ کامل را بنویس، حذف کن، و نسخهٔ کوتاه را بلند بخوان چنان‌که نسخهٔ بلند را هرگز ندیده‌ای. اگر واژهٔ افتاده را فقط به یک شکل می‌توان بازساخت، حذف بی‌خطر است.'}},
  {type:'quiz',q:{en:'Which coordination is correct?',fa:'کدام همپایگی درست است؟'},
   a:'Ich habe es nie behauptet und werde es nie behaupten.',
   o:['Ich habe und werde es nie behaupten.','Ich habe es nie behauptet und nie behaupten werde.','Ich habe und werde es nie behauptet.'],
   ex:{en:'The participle <i>behauptet</i> and the infinitive <i>behaupten</i> are different forms, so neither may be shared. Each half keeps its own verb form; only the object <i>es</i> is repeated by a pronoun.',
       fa:'اسم مفعول <i>behauptet</i> و مصدر <i>behaupten</i> دو شکل متفاوت‌اند، پس هیچ‌کدام مشترک نمی‌شوند؛ هر نیمه فعل خود را نگه می‌دارد.'}}
 ]},

{id:'praepositionalgefuege',ic:'🔩',lv:6,sk:'Prepositions',
 title:{en:'Fixed prepositional phrases',fa:'گروه‌های اضافهٔ ثابت'},
 sub:{en:'in Bezug auf · im Zuge · anhand · kraft · zwecks',fa:'ابزار فشرده‌سازی در سطح رسمی'},
 blocks:[
  {type:'text',md:{en:'Formal German has a stock of multi-word prepositions — a noun frozen inside a prepositional phrase — and they are the main tool for replacing a whole clause with four words. They are lexicalised: the article is fixed, the case is fixed, and you cannot vary them. <i>in Bezug auf</i> is correct; <s>im Bezug auf</s> is one of the most frequent spelling errors in German business correspondence, made by natives too.',
        fa:'آلمانی رسمی ذخیره‌ای از حروف اضافهٔ چندکلمه‌ای دارد — اسمی منجمد در میان یک گروه اضافی — و ابزار اصلی جانشین‌کردن یک جمله‌واره با چهار کلمه‌اند. این‌ها واژگانی شده‌اند: حرف تعریف و حالت ثابت است. <i>in Bezug auf</i> درست است؛ <s>im Bezug auf</s> از رایج‌ترین غلط‌های املایی است.'}},
  {type:'table',head:['Phrase','Case','Means','Replaces'],rows:[
   ['*in Bezug auf','+ Akkusativ','with regard to','was … betrifft'],
   ['*im Hinblick auf','+ Akkusativ','in view of, with a view to','weil man … bedenkt'],
   ['*mit Blick auf','+ Akkusativ','with an eye to','wenn man … ansieht'],
   ['*unter Berücksichtigung','+ Genitiv','taking into account','wenn man … berücksichtigt'],
   ['*mit Rücksicht auf','+ Akkusativ','out of consideration for','weil man … schonen will'],
   ['*im Zuge','+ Genitiv','in the course of','während / als … lief'],
   ['*im Rahmen','+ Genitiv','within the framework of','soweit … es vorsieht'],
   ['*anhand','+ Genitiv','on the basis of (data, documents)','indem man … auswertet'],
   ['*kraft','+ Genitiv','by virtue of (legal authority)','weil … dazu befugt ist'],
   ['*zwecks','+ Genitiv','for the purpose of','um … zu'],
   ['*nach Maßgabe','+ Genitiv','in accordance with','wie … es bestimmt'],
   ['*im Falle','+ Genitiv','in the event of','wenn … eintritt']],
   cap:{en:'learn the case with the phrase — it is not predictable',fa:'حالت را همراه عبارت یاد بگیر — قابل پیش‌بینی نیست'}},
  {type:'steps',items:[
   {en:'Identify the relation your clause expresses: reference, condition, purpose, time, basis, authority.',fa:'رابطه‌ای را که جمله‌واره‌ات بیان می‌کند مشخص کن: ارجاع، شرط، هدف، زمان، مبنا، اختیار.'},
   {en:'Pick the phrase from the table and note whether it ends in <i>auf</i> (then Akkusativ) or in a bare noun (then Genitiv).',fa:'عبارت را برگزین و ببین به <i>auf</i> ختم می‌شود (آکوزاتیو) یا به اسم تنها (گنیتیو).'},
   {en:'Nominalise the content of the clause: „wenn alle Umstände berücksichtigt werden“ → „aller Umstände“.',fa:'محتوای جمله‌واره را اسمی کن.'},
   {en:'Put the phrase in the Vorfeld if it links back to the previous sentence; otherwise keep it in the Mittelfeld.',fa:'اگر به جملهٔ پیشین پیوند می‌دهد، در جایگاه آغازین بگذار؛ وگرنه در میدان میانی.'},
   {en:'Read the result: if two such phrases now sit in one sentence, delete one. They do not stack.',fa:'نتیجه را بخوان: اگر دو عبارت از این دست در یک جمله نشسته‌اند، یکی را حذف کن.'}]},
  {type:'examples',items:[
   {de:'In Bezug auf die Fristen bestehen weiterhin Unklarheiten.',en:'With regard to the deadlines, uncertainties remain.',say:'In Bezug auf die Fristen bestehen weiterhin Unklarheiten.'},
   {de:'Im Hinblick auf die kommende Prüfung wurden die Unterlagen vervollständigt.',en:'In view of the upcoming audit, the documents were completed.',say:'Im Hinblick auf die kommende Prüfung wurden die Unterlagen vervollständigt.'},
   {de:'Unter Berücksichtigung aller Einwände wurde der Entwurf überarbeitet.',en:'Taking all objections into account, the draft was revised.',say:'Unter Berücksichtigung aller Einwände wurde der Entwurf überarbeitet.'},
   {de:'Im Zuge der Umstrukturierung wurden zwei Abteilungen zusammengelegt.',en:'In the course of the restructuring, two departments were merged.',say:'Im Zuge der Umstrukturierung wurden zwei Abteilungen zusammengelegt.'},
   {de:'Anhand der vorliegenden Daten lässt sich das nicht entscheiden.',en:'On the basis of the available data this cannot be decided.',say:'Anhand der vorliegenden Daten lässt sich das nicht entscheiden.'},
   {de:'Kraft seines Amtes kann der Vorsitzende die Sitzung unterbrechen.',en:'By virtue of his office the chair may suspend the session.',say:'Kraft seines Amtes kann der Vorsitzende die Sitzung unterbrechen.'}]},
  {type:'contrast',cols:[
   {t:'anhand vs aufgrund',md:{en:'<b>anhand</b> + Gen = using something as <b>evidence or material</b>: „anhand der Rechnungen“, „anhand eines Beispiels“.<br><br><b>aufgrund</b> + Gen = because of, a <b>cause</b>: „aufgrund der Verzögerung“.<br><br>So: „Anhand der Zahlen zeigt sich, dass …“ but „Aufgrund der Zahlen wurde der Plan geändert.“ Never use <i>anhand</i> with a person as the material.',
       fa:'<b>anhand</b> یعنی با استفاده از چیزی به‌عنوان <b>شاهد یا مادّه</b>؛ <b>aufgrund</b> یعنی به <b>علتِ</b> چیزی. anhand را با شخص به کار نبر.'}},
   {t:'zwecks vs um … zu',md:{en:'<b>zwecks</b> + Gen is pure officialese and bare of articles: „zwecks Überprüfung der Angaben“.<br><br><b>um … zu</b> is the normal, readable purpose clause: „um die Angaben zu überprüfen“.<br><br>In a letter to a customer the second is better. Use <i>zwecks</i> only when you are deliberately writing in administrative voice.',
       fa:'<b>zwecks</b> خالصاً اداری و بی‌حرف تعریف است؛ <b>um … zu</b> جمله‌وارهٔ هدفِ عادی و خواندنی. در نامه به مشتری دومی بهتر است.'}}]},
  {type:'warn',md:{en:'Three traps. <b>1.</b> Spelling: <b>in Bezug auf</b>, never <s>im Bezug auf</s>; <b>im Hinblick auf</b>, never <s>in Hinblick</s>. <b>2.</b> Stacking: „unter Berücksichtigung der im Rahmen des Verfahrens im Hinblick auf die Fristen vorgelegten Unterlagen“ is a real sentence type in German administration and it is unreadable — one such phrase per sentence. <b>3.</b> Register mismatch: <i>kraft</i>, <i>zwecks</i>, <i>nach Maßgabe</i> and <i>unbeschadet</i> belong to law and administration only. In an essay they sound like fancy dress; there, <i>aufgrund</i>, <i>anhand</i> and <i>im Hinblick auf</i> are the natural level.',
        fa:'سه تله: <b>۱.</b> املا — in Bezug auf، نه im Bezug auf. <b>۲.</b> روی هم چیدن: در هر جمله فقط یکی از این عبارت‌ها. <b>۳.</b> ناهم‌سطحی — kraft، zwecks و nach Maßgabe تنها به حقوق و اداره تعلق دارند؛ در مقاله مانند لباس مبدل‌اند.'}},
  {type:'quiz',q:{en:'„___ der eingereichten Belege konnte der Betrag nachvollzogen werden.“',fa:'«___ der eingereichten Belege konnte der Betrag nachvollzogen werden.»'},
   a:'Anhand',o:['Im Bezug auf','Zwecks','Kraft'],
   ex:{en:'The receipts are the <b>material</b> from which the amount was reconstructed → <b>anhand</b> + Genitiv. <i>im Bezug auf</i> is misspelled, <i>zwecks</i> would state a purpose and <i>kraft</i> an authority.',
       fa:'اسناد، <b>مادّهٔ</b> بازسازی مبلغ‌اند → <b>anhand</b> + گنیتیو. <i>im Bezug auf</i> غلط املایی است.'}}
 ]},

/* ================= C2 ================= */

{id:'stilebenen',ic:'🎩',lv:7,sk:'Style',
 title:{en:'Five levels of style',fa:'پنج سطح سبک'},
 sub:{en:'Diagnose a register, then hold it',fa:'سطح زبان را تشخیص بده، بعد نگه‌اش دار'},
 blocks:[
  {type:'text',md:{en:'German dictionaries mark words for Stilebene, and the marks are not advisory. A C2 writer can read a paragraph and name its level within two sentences — from the connectors, the particle count and the nominalisation density, long before looking at individual words. The skill matters because a register, once chosen, must be <b>held</b>: the damage of mixing levels is greater than the damage of staying plain.',
        fa:'فرهنگ‌های آلمانی واژه‌ها را به سطح سبک نشانه‌گذاری می‌کنند و این نشانه‌ها توصیه نیستند. نویسندهٔ C2 می‌تواند سطح یک بند را در دو جمله نام ببرد — از حروف ربط، شمار ادات و تراکم اسم‌سازی. اهمیتش در این است که سطحِ برگزیده باید <b>نگه داشته شود</b>: زیان قاطی‌کردن سطوح بیشتر از زیان ساده ماندن است.'}},
  {type:'table',head:['vulgär','salopp','umgangssprachlich','neutral','gehoben'],rows:[
   ['abkratzen','draufgehen','sterben','sterben','*versterben / entschlafen'],
   ['fressen','reinhauen','essen','essen','*speisen / dinieren'],
   ['Fresse','Visage','Gesicht','Gesicht','*Antlitz'],
   ['Kohle','Kies','Geld','Geld / Mittel','*Finanzmittel'],
   ['schuften','ackern','arbeiten','arbeiten','*tätig sein / wirken'],
   ['Bock haben','Lust haben','Lust haben','wollen','*gewillt sein'],
   ['labern','schwatzen','reden','sprechen','*sich äußern / erörtern'],
   ['abhauen','abzischen','weggehen','sich entfernen','*sich zurückziehen']],
   cap:{en:'the middle two columns are safe almost everywhere; the outer two are decisions',fa:'دو ستون میانی تقریباً همه‌جا بی‌خطرند؛ دو ستون کناری انتخاب‌اند'}},
  {type:'rule',md:{en:'Register is carried by <b>structure</b> before vocabulary. Three measurements are enough:<br>• <b>Particles</b> (<i>halt, eben, ja, doch, mal, wohl</i>): many = spoken; zero = written-formal. A Gutachten has none.<br>• <b>Connector class</b>: <i>und, aber, dann</i> = low; <i>deshalb, trotzdem</i> = neutral; <i>mithin, gleichwohl, indes, insofern</i> = high.<br>• <b>Nominalisation density</b>: nouns from verbs per sentence. 0–1 = spoken or literary, 2 = formal prose, 3+ = administration.',
        fa:'سطح زبان پیش از واژگان با <b>ساختار</b> حمل می‌شود. سه سنجه کافی است: <b>ادات</b> (halt، eben، ja، doch) — زیاد = گفتاری، صفر = نوشتاری رسمی؛ <b>گروه حرف ربط</b>؛ و <b>تراکم اسم‌سازی</b> در هر جمله.'}},
  {type:'steps',items:[
   {en:'Read two sentences aloud and count the particles. One or more → the text is spoken or near-spoken.',fa:'دو جمله را بلند بخوان و ادات را بشمار. یکی یا بیشتر → متن گفتاری است.'},
   {en:'Find the connectors. If you meet <i>gleichwohl, mithin, insofern als</i>, you are in the top register and every later word must match.',fa:'حروف ربط را پیدا کن. اگر gleichwohl، mithin یا insofern als دیدی، در بالاترین سطحی و هر واژهٔ بعدی باید هم‌سطح باشد.'},
   {en:'Count nouns ending in -ung, -heit, -keit, -tion per sentence. Two or more → formal written.',fa:'اسم‌های پایان‌یافته به ‎-ung، ‎-heit، ‎-keit و ‎-tion را در هر جمله بشمار. دو یا بیشتر → نوشتاری رسمی.'},
   {en:'Check the pronouns: <i>man</i> and the passive mean institutional, <i>ich</i> means essay or letter, <i>wir</i> means corporate or academic.',fa:'ضمیرها را بسنج: man و مجهول = نهادی، ich = مقاله یا نامه، wir = شرکتی یا دانشگاهی.'},
   {en:'Name the level in one word, then scan the text for every item that does not belong to it — those are your edits.',fa:'سطح را با یک واژه نام ببر، بعد هر عنصری را که به آن تعلق ندارد بیاب — این‌ها ویرایش‌های تو هستند.'}]},
  {type:'examples',items:[
   {de:'Wir müssen da echt mal was machen, sonst geht das schief.',en:'Spoken: three colloquial markers in one clause.',say:'Wir müssen da echt mal was machen, sonst geht das schief.'},
   {de:'Wir sollten dort bald etwas unternehmen, sonst scheitert das Vorhaben.',en:'Neutral written: same content, no particles.',say:'Wir sollten dort bald etwas unternehmen, sonst scheitert das Vorhaben.'},
   {de:'Ohne zügiges Eingreifen dürfte das Vorhaben scheitern.',en:'Formal: nominalised, hedged with „dürfte“.',say:'Ohne zügiges Eingreifen dürfte das Vorhaben scheitern.'},
   {de:'Es ist unverzüglich einzugreifen; andernfalls ist das Vorhaben gefährdet.',en:'Administrative: sein + zu, impersonal, no agent.',say:'Es ist unverzüglich einzugreifen; andernfalls ist das Vorhaben gefährdet.'},
   {de:'Dem Vorhaben ist, so steht zu befürchten, kein Erfolg beschieden.',en:'Elevated, literary: inserted clause, „beschieden sein“.',say:'Dem Vorhaben ist, so steht zu befürchten, kein Erfolg beschieden.'}]},
  {type:'contrast',cols:[
   {t:'The cost of a slip downwards',md:{en:'One colloquial word in a formal text is read as <b>carelessness</b> or as a loss of control: „Hinsichtlich der Vorwürfe haben wir keinen Bock auf weitere Diskussionen.“<br><br>The reader does not think „informal“; the reader thinks the writer does not know the difference. That is why a plain, consistent text scores higher than an ambitious mixed one.',
       fa:'یک واژهٔ خودمانی در متنی رسمی به‌عنوان <b>بی‌دقتی</b> یا از دست دادن مهار خوانده می‌شود. خواننده نمی‌اندیشد «غیررسمی»؛ می‌اندیشد نویسنده تفاوت را نمی‌داند.'}},
   {t:'The cost of a slip upwards',md:{en:'A gehoben word in a neutral text sounds affected: „Ich übersende Ihnen mein Antlitz“ for a passport photo, „Wir dinieren um zwölf“ in an office.<br><br>Elevated vocabulary needs an elevated frame: a eulogy, a literary essay, a formal speech. Outside it, <i>versterben</i> and <i>Antlitz</i> are comedy.',
       fa:'واژهٔ والا در متنی بی‌طرف، متکلف به گوش می‌رسد. واژگان والا قالبی والا می‌خواهد: مرثیه، مقالهٔ ادبی، سخنرانی رسمی.'}}]},
  {type:'warn',md:{en:'The C2 failure is not using the wrong word — it is <b>not noticing the frame</b> you yourself built. Three guards: (1) write the first and last sentence in the same register, then check the middle against them; (2) treat every idiom and every particle as register-marked until proven otherwise; (3) if you cannot name the level of a word, do not use it in an exam — synonyms are never free, and a dictionary entry without a Stilebene mark is not a licence.',
        fa:'شکست C2 نه به‌کاربردن واژهٔ نادرست است، بلکه <b>ندیدنِ قالبی</b> است که خودت ساخته‌ای. سه نگهبان: جملهٔ اول و آخر را هم‌سطح بنویس و میانه را با آن‌ها بسنج؛ هر اصطلاح و ادات را سطح‌دار بدان؛ و اگر نمی‌توانی سطح واژه‌ای را نام ببری، در آزمون به کارش نبر.'}},
  {type:'quiz',q:{en:'Which sentence holds one register throughout?',fa:'کدام جمله یک سطح را تا پایان نگه می‌دارد؟'},
   a:'Hinsichtlich der erhobenen Vorwürfe sehen wir von einer weiteren Stellungnahme ab.',
   o:['Hinsichtlich der Vorwürfe haben wir keinen Bock auf weitere Diskussionen.','Was die Vorwürfe betrifft, sehen wir von einer weiteren Stellungnahme ab, ehrlich gesagt.','Bezüglich der Vorwürfe wollen wir da jetzt mal nichts weiter zu sagen.'],
   ex:{en:'Only the first keeps the formal level in every element: <i>hinsichtlich</i>, the participial attribute <i>erhobenen</i>, and the idiom <i>von etwas absehen</i>. The others pair a formal opening with particles or a colloquial idiom.',
       fa:'تنها گزینهٔ اول سطح رسمی را در هر عنصر نگه می‌دارد. بقیه آغازی رسمی را با ادات یا اصطلاحی خودمانی جفت می‌کنند.'}}
 ]},

{id:'idiomatische-verbgefuege',ic:'🧿',lv:7,sk:'Idioms',
 title:{en:'Which verb goes with which noun',fa:'کدام فعل با کدام اسم'},
 sub:{en:'Kritik üben · Maßnahmen ergreifen · Bilanz ziehen',fa:'دقت هم‌نشینی در ترکیب‌های فعل‌ونامی'},
 blocks:[
  {type:'text',md:{en:'At C2 the grammar no longer gives you away — the collocations do. German has hundreds of noun-plus-verb units in which the noun carries the meaning and the verb is almost empty, chosen by convention alone. Get the verb wrong and the sentence is still comprehensible, still grammatical, and unmistakably foreign.',
        fa:'در C2 دستور زبان دیگر تو را لو نمی‌دهد — هم‌نشینی‌ها لو می‌دهند. آلمانی صدها ترکیب اسم‌وفعل دارد که در آن‌ها اسم معنا را حمل می‌کند و فعل تقریباً خالی است و تنها با عرف انتخاب می‌شود. فعل را که اشتباه بگیری، جمله همچنان مفهوم و دستوری است و بی‌گفت‌وگو بیگانه.'}},
  {type:'table',head:['Noun','Verb','Preposition it governs'],rows:[
   ['Kritik','*üben','an + Dativ'],
   ['Maßnahmen','*ergreifen / treffen','gegen + Akkusativ'],
   ['Rücksicht','*nehmen','auf + Akkusativ'],
   ['Anklage','*erheben','gegen + Akkusativ'],
   ['Bilanz','*ziehen','—'],
   ['Stellung','*nehmen','zu + Dativ'],
   ['Antrag','*stellen','auf + Akkusativ'],
   ['Entscheidung','*treffen / fällen','über + Akkusativ'],
   ['Beschluss','*fassen','über + Akkusativ'],
   ['Widerspruch','*einlegen','gegen + Akkusativ'],
   ['Anspruch','*erheben','auf + Akkusativ'],
   ['Wert','*legen','auf + Akkusativ'],
   ['Abstand','*nehmen','von + Dativ'],
   ['Folge','*leisten','+ Dativ object'],
   ['Rechnung','*tragen','+ Dativ object'],
   ['Einfluss','*ausüben / nehmen','auf + Akkusativ'],
   ['Beitrag','*leisten','zu + Dativ'],
   ['Bedenken','*äußern / anmelden','gegen + Akkusativ'],
   ['Konsequenzen','*ziehen','aus + Dativ'],
   ['Druck','*ausüben','auf + Akkusativ']],
   cap:{en:'learn the triple: noun + verb + preposition. Two out of three is still an error',fa:'سه‌گانه را یاد بگیر: اسم + فعل + حرف اضافه. دو از سه هم خطاست'}},
  {type:'rule',md:{en:'Why not <i>machen</i>? Because <i>machen</i> means to <b>produce something concrete</b>. In these units nothing is produced: the noun names an abstract act and the verb only says what kind of act it is — <i>üben</i> = carry out repeatedly, <i>ergreifen</i> = seize and act, <i>erheben</i> = raise formally, <i>ziehen</i> = draw out of material, <i>leisten</i> = render as a duty, <i>tragen</i> = bear. The verb is not decoration; it is the aspect of the noun.',
        fa:'چرا <i>machen</i> نه؟ چون machen یعنی <b>تولید چیزی عینی</b>. در این ترکیب‌ها چیزی تولید نمی‌شود: اسم کنشی انتزاعی را نام می‌برد و فعل تنها نوع کنش را می‌گوید — üben، ergreifen، erheben، ziehen، leisten، tragen. فعل تزئین نیست؛ نمودِ اسم است.'}},
  {type:'table',head:['Wrong','Right','Note'],rows:[
   ['*Kritik machen','Kritik üben','or simply: etwas kritisieren'],
   ['*eine Entscheidung machen','eine Entscheidung treffen','fällen = solemn, final'],
   ['*Maßnahmen machen','Maßnahmen ergreifen','treffen is equally good'],
   ['*einen Beschluss machen','einen Beschluss fassen','Protokoll language'],
   ['*Rücksicht machen','Rücksicht nehmen','auf + Akkusativ'],
   ['*Sinn machen','Sinn ergeben / sinnvoll sein','„Sinn machen“ is widespread but still criticised'],
   ['einen Fehler machen','einen Fehler machen','*machen is correct here'],
   ['Fortschritte machen','Fortschritte machen','*and here'],
   ['sich Sorgen machen','sich Sorgen machen','*and here'],
   ['Mut machen','Mut machen','*and here']],
   cap:{en:'machen is not banned — it is simply not a default',fa:'machen ممنوع نیست — فقط گزینهٔ پیش‌فرض نیست'}},
  {type:'examples',items:[
   {de:'Der Verband übt scharfe Kritik an dem Entwurf.',en:'The association sharply criticises the draft.',say:'Der Verband übt scharfe Kritik an dem Entwurf.'},
   {de:'Die Behörde hat Maßnahmen gegen die Verzögerungen ergriffen.',en:'The authority has taken measures against the delays.',say:'Die Behörde hat Maßnahmen gegen die Verzögerungen ergriffen.'},
   {de:'Nach fünf Jahren lässt sich eine erste Bilanz ziehen.',en:'After five years an initial assessment can be made.',say:'Nach fünf Jahren lässt sich eine erste Bilanz ziehen.'},
   {de:'Zu diesem Punkt möchte ich keine Stellung nehmen.',en:'I do not wish to comment on this point.',say:'Zu diesem Punkt möchte ich keine Stellung nehmen.'},
   {de:'Dem Einwand ist bei der Überarbeitung Rechnung zu tragen.',en:'The objection must be taken into account in the revision.',say:'Dem Einwand ist bei der Überarbeitung Rechnung zu tragen.'},
   {de:'Von einer Veröffentlichung hat die Redaktion Abstand genommen.',en:'The editorial team refrained from publishing.',say:'Von einer Veröffentlichung hat die Redaktion Abstand genommen.'}]},
  {type:'text',md:{en:'The same noun can be combined with different light verbs to change the <b>aspect</b>, and this is where C2 precision lives: „Die Regelung <b>findet Anwendung</b>“ (it applies, a state) — „Die Regelung <b>kommt zur Anwendung</b>“ (it comes to be applied, an event) — „Die Regelung wird <b>in Anwendung gebracht</b>“ (somebody applies it, heavy officialese). Same for <i>in Kraft treten / in Kraft setzen</i> and <i>zur Abstimmung kommen / zur Abstimmung stellen</i>: the verb decides whether there is an agent.',
        fa:'یک اسم می‌تواند با فعل‌های سبک گوناگون ترکیب شود و <b>نمود</b> را تغییر دهد — و دقت C2 همین‌جاست: findet Anwendung (حالت) · kommt zur Anwendung (رویداد) · wird in Anwendung gebracht (با عامل، کاملاً اداری). همین برای in Kraft treten / in Kraft setzen.'}},
  {type:'warn',md:{en:'Three traps. <b>1.</b> Half-learning: „Kritik <b>an</b> dem Entwurf“, not <s>über</s>; „Rücksicht <b>auf</b>“, not <s>für</s>; „Stellung <b>zu</b>“, not <s>über</s>. The preposition is part of the unit. <b>2.</b> Article: these units often have <b>no</b> article — „Stellung nehmen“, „Abstand nehmen“, „Folge leisten“, „Rechnung tragen“ — and inserting one („eine Stellung nehmen“) breaks them. <b>3.</b> Density: a whole paragraph of Funktionsverbgefüge turns an argument into a form to be filled in. Use one, then say the next thing with a plain verb.',
        fa:'سه تله: <b>۱.</b> نیم‌آموزی — Kritik <b>an</b>، Rücksicht <b>auf</b>، Stellung <b>zu</b>؛ حرف اضافه بخشی از ترکیب است. <b>۲.</b> حرف تعریف — این ترکیب‌ها اغلب <b>بی</b>حرف تعریف‌اند و افزودن آن می‌شکندشان. <b>۳.</b> تراکم — بندی پر از این ترکیب‌ها، استدلال را به فرمی اداری بدل می‌کند.'}},
  {type:'quiz',q:{en:'Which is idiomatic?',fa:'کدام اصطلاحی و طبیعی است؟'},
   a:'Der Ausschuss hat erhebliche Bedenken gegen das Verfahren angemeldet.',
   o:['Der Ausschuss hat erhebliche Bedenken über das Verfahren gemacht.','Der Ausschuss hat erhebliche Bedenken für das Verfahren genommen.','Der Ausschuss hat eine erhebliche Bedenken gegen das Verfahren geübt.'],
   ex:{en:'<b>Bedenken anmelden</b> (or <i>äußern, erheben</i>) <b>gegen</b> + Akkusativ. <i>machen</i> and <i>nehmen</i> do not combine with <i>Bedenken</i>, <i>üben</i> belongs to <i>Kritik</i>, and <i>Bedenken</i> is plural, so „eine“ is impossible.',
       fa:'<b>Bedenken anmelden</b> (یا äußern، erheben) + <b>gegen</b> با آکوزاتیو. üben به Kritik تعلق دارد و Bedenken جمع است، پس «eine» ناممکن است.'}}
 ]},

{id:'rhetorik',ic:'🏛️',lv:7,sk:'Style',
 title:{en:'Rhetorical structures on purpose',fa:'ساختارهای بلاغی، آگاهانه'},
 sub:{en:'Parallelismus · Antithese · Klimax · Praeteritio',fa:'تقارن · تضاد · اوج‌گیری · نادیده‌گویی'},
 blocks:[
  {type:'text',md:{en:'A C2 text does not merely avoid errors; it has <b>shape</b>. The figures below are not literary ornament — they are the standard moves of German commentary and essay writing, and each one does a specific job to a reader: it compresses, it contrasts, it withholds, or it lands a point. Used deliberately they read as authority; used by accident they read as noise.',
        fa:'متن C2 تنها از خطا پرهیز نمی‌کند؛ <b>فرم</b> دارد. صنایع زیر تزئین ادبی نیستند — حرکت‌های استاندارد سرمقاله و مقالهٔ آلمانی‌اند و هر یک کاری مشخص با خواننده می‌کند: فشرده می‌کند، تضاد می‌سازد، نگه می‌دارد، یا نکته را فرود می‌آورد.'}},
  {type:'table',head:['Figure','What it does','German example'],rows:[
   ['*Parallelismus','identical structure makes two claims equal','Wer plant, verliert Zeit; wer nicht plant, verliert alles.'],
   ['*Antithese','sets two poles against each other','Gefordert wird Transparenz, geliefert wird eine Pressemitteilung.'],
   ['*Klimax','three steps, rising weight','Es fehlt an Geld, an Personal, an jedem Konzept.'],
   ['*Trikolon','three parallel items close a thought','Schnell, nachvollziehbar, überprüfbar — so sollte das Verfahren sein.'],
   ['*rhetorische Frage','asserts by asking','Wer sollte das kontrollieren, wenn nicht die Aufsicht selbst?'],
   ['*Praeteritio','mentions by refusing to mention','Von den Kosten will ich gar nicht erst sprechen.'],
   ['*Konzession + Wende','concede, then reverse','Zugegeben, der Ansatz ist neu. Nur: neu ist nicht dasselbe wie tragfähig.'],
   ['*Doppelpunkt-Pointe','colon, then the short verdict','Die Bilanz nach drei Jahren: ein Verfahren ohne Ergebnis.'],
   ['*Litotes','understatement by negation','Das Ergebnis ist nicht ohne Brisanz.'],
   ['*Anapher','repeated opening, builds pressure','Niemand hat gewarnt. Niemand hat widersprochen. Niemand war zuständig.']],
   cap:{en:'ten moves; two per text is a style, five is a pamphlet',fa:'ده حرکت؛ دو تا در هر متن سبک است، پنج تا اعلامیه'}},
  {type:'rule',md:{en:'The most German of these is the <b>Konzession mit Wende</b>, and its engine is a short sentence after a long one. Build it in three beats: (1) grant the opponent’s strongest point in full — „Zugegeben: der Einwand trifft einen wirklichen Schwachpunkt.“ (2) Mark the turn with a one-word connector and a colon — „<b>Nur:</b>“, „<b>Allerdings:</b>“, „<b>Indes:</b>“ (3) Answer in a sentence of no more than ten words. The brevity is the argument.',
        fa:'آلمانی‌ترینِ این‌ها <b>امتیازدادن با چرخش</b> است و موتورش جملهٔ کوتاه پس از جملهٔ بلند است. سه ضرب: نخست قوی‌ترین نکتهٔ مخالف را کامل بپذیر؛ سپس چرخش را با یک واژه و دونقطه نشان بده («Nur:»، «Allerdings:»)؛ سپس در جمله‌ای حداکثر ده‌کلمه‌ای پاسخ بده. همان کوتاهی، استدلال است.'}},
  {type:'steps',items:[
   {en:'State the objection in its best version, with no „aber“ anywhere near it.',fa:'ایراد را در بهترین نسخه‌اش بیان کن، بدون هیچ «aber» در نزدیکی‌اش.'},
   {en:'Strengthen it once: „Man könnte sogar hinzufügen, dass …“',fa:'یک بار تقویتش کن: «Man könnte sogar hinzufügen, dass …»'},
   {en:'Turn with a single marker: „Nur:“ / „Allerdings:“ / „Und doch:“',fa:'با یک نشانگر بچرخ: «Nur:» / «Allerdings:» / «Und doch:»'},
   {en:'Answer short. If your answer needs three clauses, the objection has not been answered.',fa:'کوتاه پاسخ بده. اگر پاسخت سه جمله‌واره می‌خواهد، ایراد پاسخ نگرفته است.'},
   {en:'Close with the consequence, not with a summary: „Damit verschiebt sich die Frage: nicht ob, sondern wie.“',fa:'با پیامد ببند، نه با خلاصه.'}]},
  {type:'examples',items:[
   {de:'Gefordert wird Transparenz, geliefert wird eine Pressemitteilung.',en:'Transparency is demanded; a press release is delivered.',say:'Gefordert wird Transparenz, geliefert wird eine Pressemitteilung.'},
   {de:'Es fehlt an Geld, an Personal, an jedem tragfähigen Konzept.',en:'There is a lack of money, of staff, of any viable concept.',say:'Es fehlt an Geld, an Personal, an jedem tragfähigen Konzept.'},
   {de:'Zugegeben: der Einwand trifft einen wirklichen Schwachpunkt. Nur: er trifft nicht den entscheidenden.',en:'Granted, the objection hits a real weak point. Only: not the decisive one.',say:'Zugegeben: der Einwand trifft einen wirklichen Schwachpunkt. Nur: er trifft nicht den entscheidenden.'},
   {de:'Von den Folgekosten will ich gar nicht erst sprechen.',en:'I will not even start on the follow-up costs.',say:'Von den Folgekosten will ich gar nicht erst sprechen.'},
   {de:'Die Bilanz nach drei Jahren: ein Verfahren ohne Ergebnis.',en:'The record after three years: a procedure without a result.',say:'Die Bilanz nach drei Jahren: ein Verfahren ohne Ergebnis.'},
   {de:'Wer soll das prüfen, wenn nicht die Aufsicht selbst?',en:'Who is to examine this, if not the supervisory body itself?',say:'Wer soll das prüfen, wenn nicht die Aufsicht selbst?'}]},
  {type:'contrast',cols:[
   {t:'Kommentar: figures welcome',md:{en:'Antithese, Klimax, rhetorical question and the colon-pointe are the native equipment of the German Kommentar. The reader expects a position and a voice.<br><br>„Drei Jahre, zwei Gutachten, keine Entscheidung: das Verfahren ist das Ergebnis.“',
       fa:'تضاد، اوج‌گیری، پرسش بلاغی و نکتهٔ پس از دونقطه تجهیزات بومی سرمقالهٔ آلمانی‌اند. خواننده موضع و صدا می‌خواهد.'}},
   {t:'Bericht / Gutachten: figures = bias',md:{en:'In a report every figure reads as an attempt to steer the reader, and that discredits the text.<br><br>„Das Verfahren wurde dreimal verlängert; eine Entscheidung liegt nicht vor.“ Same facts, no rhetoric, full credibility.',
       fa:'در گزارش، هر صنعت بلاغی تلاشی برای هدایت خواننده خوانده می‌شود و اعتبار متن را می‌برد. همان واقعیت‌ها، بدون بلاغت، با اعتبار کامل.'}}]},
  {type:'warn',md:{en:'The C2 trap is <b>density</b>. Three figures in one paragraph stop being argument and start being performance — the reader hears the technique instead of the point, and in German this is read as pamphleteering (<i>Pathos</i>, said with a frown). Two further limits: a rhetorical question in a Gutachten or Protokoll is a category error, and an Anapher needs <b>three</b> members, never two or four. If you cannot say what a figure is doing for the reader, delete it.',
        fa:'تلهٔ C2 <b>تراکم</b> است. سه صنعت در یک بند، استدلال‌بودن را رها می‌کند و نمایش می‌شود — خواننده فن را می‌شنود، نه نکته را. دو محدودیت دیگر: پرسش بلاغی در نظر کارشناسی یا صورت‌جلسه خطای مقوله است، و آنافورا <b>سه</b> عضو می‌خواهد، نه دو و نه چهار.'}},
  {type:'quiz',q:{en:'Which continuation completes a concession-with-reversal?',fa:'کدام ادامه، «امتیاز با چرخش» را کامل می‌کند؟'},
   a:'Nur: tragfähig ist er damit noch nicht.',
   o:['Aber ich finde den Ansatz trotzdem nicht so gut, weil er neu ist.','Deshalb ist der Ansatz tragfähig und sollte weiterverfolgt werden.','Zugegeben, der Ansatz ist außerdem auch noch sehr neu.'],
   ex:{en:'The reversal must be <b>short</b>, must start with a single marker and must concede nothing further. The first distractor is long and hedged, the second agrees instead of turning, the third repeats the concession.',
       fa:'چرخش باید <b>کوتاه</b> باشد، با یک نشانگر آغاز شود و امتیاز تازه‌ای ندهد.'}}
 ]},

{id:'ambiguitaet',ic:'🔬',lv:7,sk:'Style',
 title:{en:'Ambiguity and the repairs',fa:'ابهام و راه‌های رفع آن'},
 sub:{en:'Attachment, scope, reference — and how to fix each',fa:'وابستگی، دامنه، ارجاع — و رفع هر یک'},
 blocks:[
  {type:'text',md:{en:'The last thing to learn is not a form but a habit: reading your own sentence as a stranger would. Advanced German sentences are long, and long sentences offer the reader more than one way to hang the parts together. The writer always knows which reading is meant — which is exactly why the writer is the last person to notice the other one.',
        fa:'آخرین چیزی که آموخته می‌شود صورت نیست، عادت است: خواندن جملهٔ خود چنان‌که بیگانه‌ای می‌خواند. جمله‌های پیشرفتهٔ آلمانی بلندند و جملهٔ بلند بیش از یک راه برای به‌هم‌آویختن اجزا پیش می‌گذارد. نویسنده همیشه می‌داند کدام خوانش مقصود است — و درست از این رو آخرین کسی است که خوانش دیگر را می‌بیند.'}},
  {type:'table',head:['Type','Ambiguous','Repair'],rows:[
   ['*Relativsatz-Bezug','der Bericht des Ausschusses, der im Mai vorgelegt wurde','der im Mai vorgelegte Bericht des Ausschusses'],
   ['*Präpositionalgruppe','Er beobachtete den Mann mit dem Fernglas.','Mit dem Fernglas beobachtete er den Mann.'],
   ['*Skopus der Negation','Alle Anträge wurden nicht geprüft.','Nicht alle Anträge wurden geprüft.'],
   ['*Stellung von „nur“','Der Vorstand hat nur die Kosten geprüft.','Nur der Vorstand hat die Kosten geprüft.'],
   ['*Pronomenbezug','Der Vorstand informierte den Betriebsrat, nachdem er den Bericht erhalten hatte.','…, nachdem der Betriebsrat den Bericht erhalten hatte.'],
   ['*Genitiv: wer handelt?','die Kritik des Ministers','die Kritik am Minister / die vom Minister geäußerte Kritik'],
   ['*Koordination','alte Männer und Frauen','alte Männer und alte Frauen / Frauen und alte Männer'],
   ['*Komposita-Bezug','Verkaufsleiterbesprechung','Besprechung der Verkaufsleiter']],
   cap:{en:'eight structures, eight repairs — all of them restructuring, not explaining',fa:'هشت ساختار، هشت راه رفع — همه بازسازی، نه توضیح'}},
  {type:'rule',md:{en:'German has two disambiguating resources English lacks, and a C2 writer uses them on purpose.<br>• <b>Agreement</b>: a relative pronoun shows gender and number, so „das Gutachten der Kommission, <b>das</b> im Mai vorgelegt wurde“ is unambiguous while „der Bericht des Ausschusses, <b>der</b> …“ is not. If agreement does not decide, restructure.<br>• <b>Explicit pointers</b>: <i>dieser</i> (the nearer), <i>jener</i> (the further), <i>letzterer / ersterer</i>, <i>derjenige, der …</i>. „Der Vorstand informierte den Betriebsrat; <b>Letzterer</b> hatte den Bericht schon erhalten.“',
        fa:'آلمانی دو ابزار رفع ابهام دارد که انگلیسی ندارد: <b>مطابقت</b> — ضمیر وصفی جنس و شمار را نشان می‌دهد؛ و <b>اشاره‌گرهای صریح</b> — dieser (نزدیک‌تر)، jener (دورتر)، letzterer/ersterer، derjenige. اگر مطابقت تصمیم نگرفت، جمله را بازبساز.'}},
  {type:'examples',items:[
   {de:'Nicht alle Einwände wurden geprüft.',en:'Not all objections were examined. (some were)',say:'Nicht alle Einwände wurden geprüft.'},
   {de:'Keiner der Einwände wurde geprüft.',en:'None of the objections was examined.',say:'Keiner der Einwände wurde geprüft.'},
   {de:'Mit dem Fernglas beobachtete er den Mann.',en:'He watched the man with the binoculars. (he had them)',say:'Mit dem Fernglas beobachtete er den Mann.'},
   {de:'Das im Mai vorgelegte Gutachten der Kommission ist eindeutig.',en:'The commission’s report, submitted in May, is unambiguous.',say:'Das im Mai vorgelegte Gutachten der Kommission ist eindeutig.'},
   {de:'Die Kritik am Minister hält sich in Grenzen.',en:'Criticism of the minister is limited. (he is the target)',say:'Die Kritik am Minister hält sich in Grenzen.'},
   {de:'Der Vorstand informierte den Betriebsrat; Letzterer hatte den Bericht bereits erhalten.',en:'The board informed the works council; the latter had already received the report.',say:'Der Vorstand informierte den Betriebsrat; Letzterer hatte den Bericht bereits erhalten.'}]},
  {type:'text',md:{en:'The genitive case is the quietest trap of the set. „die Kritik <b>des Ministers</b>“ can be a <b>subjective</b> genitive (he criticises) or an <b>objective</b> one (he is criticised), and no ending distinguishes them. The repairs are fixed: for the objective reading use the verb’s own preposition („die Kritik <b>am</b> Minister“, „die Unterstützung <b>für</b> den Antrag“), for the subjective one name the agent („die <b>vom Minister geäußerte</b> Kritik“, „die Kritik, die der Minister vorgebracht hat“). The same applies to <i>die Beobachtung der Prüfer</i>, <i>die Wahl des Vorsitzenden</i>, <i>die Entlassung des Abteilungsleiters</i>.',
        fa:'گنیتیو، خاموش‌ترین تلهٔ این مجموعه است: «die Kritik des Ministers» می‌تواند گنیتیو <b>فاعلی</b> (او نقد می‌کند) یا <b>مفعولی</b> (او نقد می‌شود) باشد و هیچ پایانه‌ای آن‌ها را جدا نمی‌کند. راه رفع: برای خوانش مفعولی از حرف اضافهٔ خود فعل استفاده کن؛ برای خوانش فاعلی عامل را نام ببر.'}},
  {type:'steps',items:[
   {en:'Read each sentence and ask: can any modifier attach to a second head? If yes, move it or convert it into a participial attribute.',fa:'از هر جمله بپرس: آیا وصفی می‌تواند به هستهٔ دومی بچسبد؟ اگر آری، جابه‌جا یا به وصف وصفی تبدیلش کن.'},
   {en:'Circle every pronoun. If two nouns of the same gender precede it, replace it with the noun, with <i>dieser</i> or with <i>Letzterer</i>.',fa:'هر ضمیر را دور بگیر. اگر دو اسم هم‌جنس پیش از آن آمده، آن را با اسم یا با dieser / Letzterer عوض کن.'},
   {en:'Find every <i>nicht</i>, <i>nur</i>, <i>alle</i>, <i>auch</i>: check that each sits directly in front of what it is meant to cover.',fa:'هر nicht، nur، alle و auch را بیاب و بسنج که مستقیماً پیش از آنچه باید دربرگیرد نشسته است.'},
   {en:'Check every genitive attribute for the subjective/objective question and repair with a preposition where needed.',fa:'هر متمم گنیتیو را از نظر فاعلی/مفعولی بسنج و در صورت نیاز با حرف اضافه رفعش کن.'},
   {en:'Finally read the sentence against your intention <b>once more, out loud</b>. Only the spoken version reveals a reading your eye has been skipping.',fa:'در پایان جمله را <b>یک بار دیگر، بلند</b> بخوان. تنها نسخهٔ گفتاری خوانشی را آشکار می‌کند که چشم از آن می‌پرد.'}]},
  {type:'warn',md:{en:'Two opposite dangers. Under-repairing is the usual one, but <b>over-repairing</b> ruins a text too: a sentence in which every pronoun has been replaced by its full noun („Der Betriebsrat teilte dem Vorstand mit, dass der Betriebsrat die Unterlagen des Vorstands erhalten habe“) is unambiguous and unreadable. And avoid the administrative repair <i>derselbe / desselben</i> as a pronoun — „Wir erhielten die Unterlagen und prüften dieselben“ is old officialese, not precision. Repair by <b>restructuring</b>, not by repetition.',
        fa:'دو خطر متضاد: کم‌رفع‌کردن خطر معمول است، اما <b>بیش‌رفع‌کردن</b> هم متن را خراب می‌کند: جمله‌ای که هر ضمیرش با اسم کاملش عوض شده، بی‌ابهام و ناخواندنی است. و از رفعِ اداری با <i>derselbe</i> به‌عنوان ضمیر بپرهیز. رفع، با <b>بازسازی</b> است نه با تکرار.'}},
  {type:'quiz',q:{en:'Which version unambiguously says that some objections were examined?',fa:'کدام نسخه بی‌ابهام می‌گوید که بخشی از ایرادها بررسی شد؟'},
   a:'Nicht alle Einwände wurden geprüft.',
   o:['Alle Einwände wurden nicht geprüft.','Keiner der Einwände wurde geprüft.','Die Einwände wurden alle nicht geprüft.'],
   ex:{en:'Putting <i>nicht</i> in front of <i>alle</i> negates the quantifier only. „Alle … nicht geprüft“ is read as the total negation, and <i>keiner</i> states it outright.',
       fa:'گذاشتن <i>nicht</i> پیش از <i>alle</i> تنها کمیت‌سنج را نفی می‌کند. «Alle … nicht geprüft» نفی کامل خوانده می‌شود.'}}
 ]},

{id:'korrektur',ic:'✅',lv:7,sk:'Style',
 title:{en:'The C2 self-editing pass',fa:'بازخوانی و ویرایش در سطح C2'},
 sub:{en:'The five error classes that survive this long',fa:'پنج دستهٔ خطا که تا این‌جا زنده می‌مانند'},
 blocks:[
  {type:'text',md:{en:'By C2 your errors are no longer distributed randomly: they cluster in five places, and they are the same five for almost every advanced learner. Knowing the list turns proofreading from a vague re-reading into five targeted passes, each of which you can do in a minute.',
        fa:'در C2 خطاهای تو دیگر تصادفی پخش نیستند: در پنج نقطه خوشه می‌بندند و برای تقریباً هر زبان‌آموز پیشرفته همان پنج نقطه‌اند. دانستن این فهرست، بازخوانی را از خواندنی مبهم به پنج گذرِ هدفمند بدل می‌کند.'}},
  {type:'table',head:['Class','Typical slip','Correct'],rows:[
   ['*Rektion','bestehen auf den Vorschlag','bestehen auf dem Vorschlag (Dativ)'],
   ['*Rektion','sich beteiligen bei dem Verfahren','sich beteiligen an dem Verfahren'],
   ['*Rektion','zweifeln über die Angaben','zweifeln an den Angaben'],
   ['*Artikel in fester Wendung','im Bezug auf die Frist','in Bezug auf die Frist'],
   ['*Artikel in fester Wendung','in der Regel — im Grunde — am Ende','all three fixed; no variation'],
   ['*Konjunktiv-Konsistenz','Er sagte, er sei krank und hatte Fieber.','…, er sei krank und habe Fieber.'],
   ['*Pronomenbezug','Der Antrag des Vorstands, der abgelehnt wurde','Der abgelehnte Antrag des Vorstands'],
   ['*Registerbruch','Die Behörde hat das echt verschlafen.','Die Behörde hat die Frist versäumt.'],
   ['*Zeitenfolge','Nachdem er den Bericht liest, entschied er.','Nachdem er den Bericht gelesen hatte, entschied er.'],
   ['*Komma','Er versprach den Bericht zu prüfen','Er versprach, den Bericht zu prüfen.']],
   cap:{en:'five classes, ten shapes — all of them invisible when you read for meaning',fa:'پنج دسته، ده شکل — همه هنگام خواندن برای معنا نامرئی‌اند'}},
  {type:'rule',md:{en:'The <b>Rektion</b> pass is the most profitable minute you will spend. Circle every preposition that is demanded by a verb or an adjective rather than by meaning, and check it against what you learned, not against English: <i>bestehen auf</i> + Dativ (insist) vs <i>bestehen aus</i> + Dativ (consist of) vs <i>bestehen in</i> + Dativ (consist in) · <i>teilnehmen an</i> + Dativ · <i>hinweisen auf</i> + Akkusativ · <i>zweifeln an</i> + Dativ · <i>sich beziehen auf</i> + Akkusativ · <i>interessiert an</i> + Dativ · <i>verantwortlich für</i> + Akkusativ · <i>zuständig für</i> + Akkusativ · <i>beteiligt an</i> + Dativ.',
        fa:'گذرِ <b>حاکمیت فعل</b> سودمندترین دقیقه‌ای است که صرف می‌کنی. هر حرف اضافه‌ای را که فعل یا صفت طلب می‌کند دور بگیر و با آموخته‌ات بسنج، نه با انگلیسی: bestehen auf/aus/in، teilnehmen an، hinweisen auf، zweifeln an، sich beziehen auf.'}},
  {type:'steps',items:[
   {en:'<b>Pass 1 — brackets.</b> In every subordinate clause check that the finite verb is last and that the verb cluster is in the right order („…, dass er es <b>hätte wissen müssen</b>“).',fa:'<b>گذر ۱ — کمانهٔ فعلی.</b> در هر جمله‌وارهٔ پیرو بسنج که فعل صرف‌شده پایانی است و ترتیب خوشهٔ فعلی درست است.'},
   {en:'<b>Pass 2 — Rektion.</b> Circle every governed preposition and every case it takes. Do not rely on your ear here; your ear was trained in English.',fa:'<b>گذر ۲ — حاکمیت.</b> هر حرف اضافهٔ حاکم‌شده و حالتش را دور بگیر. اینجا به گوشت تکیه نکن.'},
   {en:'<b>Pass 3 — pronouns.</b> Every <i>er, sie, es, dieser, dessen</i> must have exactly one possible antecedent. Where there are two, name the noun or use <i>Letzterer</i>.',fa:'<b>گذر ۳ — ضمیرها.</b> هر ضمیر باید تنها یک مرجع ممکن داشته باشد.'},
   {en:'<b>Pass 4 — Konjunktiv.</b> In reported speech, check that a whole passage stays in Konjunktiv I (switching to Indikativ halfway means you now vouch for the claim).',fa:'<b>گذر ۴ — التزامی.</b> در نقل قول بسنج که سراسر بند در التزامی I بماند؛ بازگشت به اخباری یعنی تو ضامن ادعا شده‌ای.'},
   {en:'<b>Pass 5 — register and density.</b> Count nominalisations per sentence and hunt for the single word that belongs to another level. Delete it, do not soften it.',fa:'<b>گذر ۵ — سطح و تراکم.</b> اسم‌سازی‌ها را بشمار و آن یک واژه را که به سطحی دیگر تعلق دارد بیاب و حذف کن.'},
   {en:'<b>Pass 6 — backwards.</b> Read the text sentence by sentence from the end. This breaks the flow that hides your errors from you.',fa:'<b>گذر ۶ — معکوس.</b> متن را جمله‌به‌جمله از آخر به اول بخوان تا جریانی که خطاها را پنهان می‌کند شکسته شود.'}]},
  {type:'examples',items:[
   {de:'Er besteht auf einer schriftlichen Zusage.',en:'He insists on a written commitment. (auf + Dativ)',say:'Er besteht auf einer schriftlichen Zusage.'},
   {de:'Das Gutachten besteht aus drei Teilen.',en:'The report consists of three parts.',say:'Das Gutachten besteht aus drei Teilen.'},
   {de:'Das Problem besteht in der fehlenden Zuständigkeit.',en:'The problem consists in the missing responsibility.',say:'Das Problem besteht in der fehlenden Zuständigkeit.'},
   {de:'Der Sprecher erklärte, man habe die Frist eingehalten und werde die Unterlagen nachreichen.',en:'The spokesman said the deadline had been met and the documents would be submitted later.',say:'Der Sprecher erklärte, man habe die Frist eingehalten und werde die Unterlagen nachreichen.'},
   {de:'Nachdem der Ausschuss den Bericht geprüft hatte, fasste er einen Beschluss.',en:'After the committee had examined the report, it passed a resolution.',say:'Nachdem der Ausschuss den Bericht geprüft hatte, fasste er einen Beschluss.'},
   {de:'Ich beziehe mich auf Ihr Schreiben vom 3. März.',en:'I refer to your letter of 3 March.',say:'Ich beziehe mich auf Ihr Schreiben vom dritten März.'}]},
  {type:'contrast',cols:[
   {t:'Reading for meaning',md:{en:'Your eye runs at normal speed, your brain supplies what you intended, and every structure you wrote looks right because you built it.<br><br>This pass finds <b>content</b> problems: a missing step in the argument, a claim without evidence. It finds almost no language errors at all.',
       fa:'چشم با سرعت عادی می‌دود و مغز آنچه را قصد کرده‌ای تأمین می‌کند. این گذر مسائل <b>محتوایی</b> را می‌یابد، نه خطاهای زبانی.'}},
   {t:'Reading for form',md:{en:'You read slowly, backwards, one structure type at a time, and you do not care what the text says.<br><br>This pass finds <b>language</b> errors — and it only works if you have a list. Without a list you are re-reading, not proofreading.',
       fa:'آهسته، معکوس و هر بار یک نوع ساختار می‌خوانی و به معنای متن کاری نداری. این گذر خطاهای <b>زبانی</b> را می‌یابد — و تنها با داشتن فهرست کار می‌کند.'}}]},
  {type:'warn',md:{en:'Beware the <b>self-correction illusion</b>: when you re-read your own text you do not read what is on the page, you re-run the intention you had when writing it. Break that loop mechanically — print it, change the font, read it aloud, read it from the last sentence to the first. And beware the second danger: every correction you make reopens the sentence. After changing a word, re-check the whole clause — case, bracket, agreement. More C2 errors are introduced during editing than survive from the first draft.',
        fa:'از <b>توهم خودویرایش</b> بپرهیز: وقتی متن خودت را بازمی‌خوانی، آنچه روی کاغذ است را نمی‌خوانی، بلکه قصدِ هنگام نوشتن را بازپخش می‌کنی. این حلقه را مکانیکی بشکن: چاپش کن، قلم را عوض کن، بلند بخوان، از آخر به اول بخوان. و خطر دوم: هر اصلاح، جمله را دوباره باز می‌کند — پس از تغییر یک واژه، کل جمله‌واره را بازبسنج.'}},
  {type:'quiz',q:{en:'Which sentence survives the Rektion pass?',fa:'کدام جمله از گذرِ حاکمیت فعل سالم بیرون می‌آید؟'},
   a:'Die Gegenseite besteht auf einer Fristverlängerung.',
   o:['Die Gegenseite besteht auf eine Fristverlängerung.','Die Gegenseite besteht über eine Fristverlängerung.','Die Gegenseite besteht an einer Fristverlängerung.'],
   ex:{en:'<i>bestehen auf</i> in the sense „insist“ takes the <b>Dativ</b> — a state, not a movement. With the Akkusativ it is simply wrong, and <i>über</i> and <i>an</i> are not in this verb’s government at all.',
       fa:'<i>bestehen auf</i> در معنای «پافشاری» <b>داتیو</b> می‌گیرد — حالت، نه حرکت. über و an در حاکمیت این فعل نیستند.'}}
 ]},

{id:'textsorten',ic:'📑',lv:7,sk:'Style',
 title:{en:'Text types and their signatures',fa:'گونه‌های متن و امضای دستوری آن‌ها'},
 sub:{en:'Kommentar · Bericht · Protokoll · Gutachten · Essay',fa:'سرمقاله · گزارش · صورت‌جلسه · نظر کارشناسی · مقاله'},
 blocks:[
  {type:'text',md:{en:'Every German text type has a grammatical fingerprint: a tense, a voice, a person and a connector profile. A trained reader diagnoses the type from the first two sentences and then reads everything that follows as belonging to it — which is why writing a Bericht in the grammar of a Kommentar fails even when every sentence is excellent.',
        fa:'هر گونهٔ متن آلمانی اثر انگشتی دستوری دارد: یک زمان، یک جهت فعل، یک شخص و یک نمای حروف ربط. خوانندهٔ آزموده گونه را از دو جملهٔ اول تشخیص می‌دهد — و از این رو نوشتن گزارش با دستورِ سرمقاله شکست می‌خورد، حتی اگر هر جمله درخشان باشد.'}},
  {type:'table',head:['Textsorte','Tense','Voice / person','Signature'],rows:[
   ['*Kommentar','Präsens','aktiv · ich/wir allowed','evaluating adverbs, rhetorical question, colon-pointe'],
   ['*Bericht','Präteritum / Perfekt','aktiv + passiv · 3rd person','temporal connectors, no evaluation, sources named'],
   ['*Protokoll','Präsens or Präteritum','passiv / man · never ich','„Es wird beschlossen, dass …“ · Konjunktiv I for statements'],
   ['*Gutachten','Präsens','passiv · impersonal','„Es ist festzustellen, dass …“ · sein + zu + Inf · conditionals'],
   ['*Essay','Präsens','aktiv · ich allowed','figures allowed, open ending, first person argument'],
   ['*Bewerbung','Präsens + Perfekt','aktiv · ich','concrete verbs, no hedging, no „man“']],
   cap:{en:'tense + voice + person is the signature; the connectors confirm it',fa:'زمان + جهت فعل + شخص همان امضا است؛ حروف ربط تأییدش می‌کنند'}},
  {type:'examples',items:[
   {de:'Kommentar: Drei Jahre, zwei Gutachten, keine Entscheidung — das Verfahren ist selbst das Ergebnis.',en:'Commentary: evaluative, present tense, rhetorical shape.',say:'Drei Jahre, zwei Gutachten, keine Entscheidung — das Verfahren ist selbst das Ergebnis.'},
   {de:'Bericht: Der Ausschuss beschloss am Dienstag, das Verfahren zu verlängern. Eine Begründung wurde nicht mitgeteilt.',en:'Report: past tense, third person, no judgement.',say:'Der Ausschuss beschloss am Dienstag, das Verfahren zu verlängern. Eine Begründung wurde nicht mitgeteilt.'},
   {de:'Protokoll: Frau Berg erklärt, die Unterlagen seien vollständig. Es wird beschlossen, die Prüfung fortzusetzen.',en:'Minutes: present tense, Konjunktiv I for reported statements, no first person.',say:'Frau Berg erklärt, die Unterlagen seien vollständig. Es wird beschlossen, die Prüfung fortzusetzen.'},
   {de:'Gutachten: Es ist festzustellen, dass die Vorgaben nur teilweise eingehalten wurden. Eine Nachbesserung ist erforderlich.',en:'Expert opinion: impersonal, sein + zu, passive.',say:'Es ist festzustellen, dass die Vorgaben nur teilweise eingehalten wurden. Eine Nachbesserung ist erforderlich.'},
   {de:'Essay: Ich halte die Frage für falsch gestellt — und zwar aus einem einfachen Grund.',en:'Essay: first person, present, open argument.',say:'Ich halte die Frage für falsch gestellt — und zwar aus einem einfachen Grund.'},
   {de:'Bewerbung: In meiner jetzigen Position verantworte ich die Planung von drei Standorten.',en:'Application: first person, present, concrete and unhedged.',say:'In meiner jetzigen Position verantworte ich die Planung von drei Standorten.'}]},
  {type:'rule',md:{en:'In a <b>Protokoll</b> the Konjunktiv I is not decoration but a legal device: „Herr Lang erklärt, die Frist <b>sei</b> eingehalten worden“ records his claim <b>without the minutes endorsing it</b>. Write <i>ist</i> instead and the protocol has certified the statement as fact. The decisions themselves take the passive present: „<b>Es wird beschlossen</b>, die Sitzung zu unterbrechen.“',
        fa:'در <b>صورت‌جلسه</b> التزامی I تزئین نیست، ابزاری حقوقی است: ادعای گوینده را ثبت می‌کند <b>بدون آنکه صورت‌جلسه آن را تأیید کند</b>. اگر <i>ist</i> بنویسی، صورت‌جلسه آن گفته را به‌عنوان واقعیت گواهی کرده است.'}},
  {type:'contrast',cols:[
   {t:'Bericht on the facts',md:{en:'„Die Kommission legte den Bericht im Mai vor. Zwei der drei Empfehlungen wurden bis September umgesetzt; zur dritten liegt keine Entscheidung vor.“<br><br>Past tense, passive where the agent is irrelevant, numbers, no adjective of judgement. The reader forms their own view.',
       fa:'زمان گذشته، مجهول در جایی که عامل بی‌اهمیت است، عدد، و هیچ صفت ارزش‌داورانه. خواننده خودش داوری می‌کند.'}},
   {t:'Kommentar on the same facts',md:{en:'„Zwei von drei Empfehlungen, vier Monate Zeit — und bei der wichtigsten herrscht Schweigen. Wer so umsetzt, wollte nie umsetzen.“<br><br>Present tense, ellipsis, Antithese, a verdict. Both texts are good; put either one in the other’s place and both fail.',
       fa:'زمان حال، حذف، تضاد، و یک حکم. هر دو متن خوب‌اند؛ هر یک را به جای دیگری بگذار، هر دو شکست می‌خورند.'}}]},
  {type:'warn',md:{en:'The classic exam failure is writing a Kommentar when a Bericht was asked for, and the giveaway is always the same: evaluating adverbs (<i>erschreckend, erfreulicherweise, bedauerlicherweise, völlig unverständlich</i>) and the present tense. Two more: <i>man</i> in a Bewerbung („Man bringt Erfahrung mit“ — no, „Ich bringe … mit“), and Konjunktiv II hedging in a Bewerbung („Ich würde gern …“ reads as unsure; write „Ich möchte …“ or simply „Ich bewerbe mich …“). Before you write the first sentence, name the type, then name its tense, voice and person.',
        fa:'شکست کلاسیک در آزمون، نوشتن سرمقاله به جای گزارش است و نشانه‌اش همیشه یکی است: قیدهای ارزش‌داورانه و زمان حال. دو مورد دیگر: <i>man</i> در درخواست کار، و تعدیل با التزامی II در درخواست کار («Ich würde gern…» ناامن خوانده می‌شود). پیش از جملهٔ اول، گونه و سپس زمان، جهت فعل و شخص آن را نام ببر.'}},
  {type:'quiz',q:{en:'Which sentence belongs in a Protokoll?',fa:'کدام جمله به یک صورت‌جلسه تعلق دارد؟'},
   a:'Herr Lang erklärt, die Frist sei eingehalten worden.',
   o:['Herr Lang erklärt, dass die Frist ganz klar eingehalten wurde.','Ich fand die Erklärung von Herrn Lang nicht überzeugend.','Man fragt sich, ob Herr Lang die Frist überhaupt kannte.'],
   ex:{en:'Minutes record statements in <b>Konjunktiv I</b> without endorsing them, in the third person and without evaluation. The Indikativ would certify the claim, and the other two add a judgement and a rhetorical question.',
       fa:'صورت‌جلسه گفته‌ها را در <b>التزامی I</b> و بدون تأیید ثبت می‌کند، در شخص سوم و بدون داوری.'}}
 ]}

];

/* ============ DRILLS ============ */
window.DRILL_C1=[

/* --- nominalstil-c1 --- */
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Wegen ___ Preise musste das Unternehmen die Tarife anheben.',a:'der gestiegenen',o:['die gestiegenen','den gestiegenen','der gestiegene'],ex:'wegen + Genitiv; in the plural the adjective after „der“ takes the weak ending -en.',tr:'Because of the increased prices the company had to raise its rates.',say:'Wegen der gestiegenen Preise musste das Unternehmen die Tarife anheben.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'___ Prüfung der Unterlagen wurde dem Antrag entsprochen.',a:'Nach',o:['Nachdem','Seitdem','Bevor'],ex:'A nominal phrase needs a preposition, not a conjunction: „nach Prüfung“ = „nachdem geprüft worden war“.',tr:'After examination of the documents the application was granted.',say:'Nach Prüfung der Unterlagen wurde dem Antrag entsprochen.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Zur ___ der Verwaltungskosten wurden zwei Abteilungen zusammengelegt.',a:'Senkung',o:['Senken','gesenkt','Sinkung'],ex:'„zur“ = zu + der, so a feminine noun must follow: die Senkung. Transitive senken → Senkung.',tr:'In order to reduce administrative costs two departments were merged.',say:'Zur Senkung der Verwaltungskosten wurden zwei Abteilungen zusammengelegt.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Bei ___ Eingang des Widerspruchs verlängert sich die Frist.',a:'rechtzeitigem',o:['rechtzeitigen','rechtzeitiger','rechtzeitige'],ex:'bei + Dativ, masculine, no article → strong ending -em. The adverb „rechtzeitig“ became an adjective.',tr:'If the objection arrives in time, the deadline is extended.',say:'Bei rechtzeitigem Eingang des Widerspruchs verlängert sich die Frist.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Die Entscheidung des Vorstands ___ die Verlagerung der Produktion steht noch aus.',a:'über',o:['von','für','an'],ex:'The second relation hangs on a preposition, not on a second genitive: eine Entscheidung über + Akkusativ.',tr:'The board’s decision on relocating production is still pending.',say:'Die Entscheidung des Vorstands über die Verlagerung der Produktion steht noch aus.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'___ des Gesetzes müssen alle Verträge angepasst werden.',a:'Vor Inkrafttreten',o:['Vor Inkraft treten','Bevor Inkrafttreten','Vor das Inkrafttreten'],ex:'The nominalised infinitive is one word, and after „vor“ it stands without an article in this fixed phrase.',tr:'Before the law comes into force, all contracts must be adapted.',say:'Vor Inkrafttreten des Gesetzes müssen alle Verträge angepasst werden.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Trotz ___ Mahnungen blieb die Zahlung aus.',a:'mehrfacher',o:['mehrfache','mehrfachen','mehrfachem'],ex:'trotz + Genitiv, plural, no article → strong ending -er: mehrfacher Mahnungen.',tr:'Despite repeated reminders the payment did not arrive.',say:'Trotz mehrfacher Mahnungen blieb die Zahlung aus.'},
{gid:'nominalstil-c1',lv:6,sk:'Style',s:'Nachdem die Prüfung abgeschlossen worden ___, wurde über den Antrag entschieden.',a:'war',o:['ist','hatte','wurde'],ex:'Unpacking a nominal phrase into a „nachdem“-clause brings the Zeitenfolge with it: passive Plusquamperfekt = abgeschlossen worden war.',tr:'After the examination had been completed, the application was decided on.',say:'Nachdem die Prüfung abgeschlossen worden war, wurde über den Antrag entschieden.'},

/* --- konnektoren-c1 --- */
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Der Vorschlag überzeugt, ___ er kaum Kosten verursacht.',a:'zumal',o:['trotzdem','gleichwohl','mithin'],ex:'<i>zumal</i> adds a further, stronger reason and sends the verb to the end. The other three are adverbs and would need verb-second.',tr:'The proposal is convincing, especially since it causes hardly any costs.',say:'Der Vorschlag überzeugt, zumal er kaum Kosten verursacht.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'___ keine Einwände bestehen, gilt der Beschluss als gefasst.',a:'Sofern',o:['Sofern dass','Insofern','Ungeachtet'],ex:'<i>sofern</i> is a Subjunktion on its own — no „dass“ — and expresses a reservation: provided that.',tr:'Provided there are no objections, the resolution is deemed adopted.',say:'Sofern keine Einwände bestehen, gilt der Beschluss als gefasst.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Die Frist ist abgelaufen; der Anspruch ist ___ verjährt.',a:'mithin',o:['indem','sofern','zumal'],ex:'<i>mithin</i> marks a logical consequence („it follows that“) and stands as an adverb inside the clause.',tr:'The deadline has expired; the claim is therefore time-barred.',say:'Die Frist ist abgelaufen; der Anspruch ist mithin verjährt.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'___ aller Bedenken wurde der Entwurf verabschiedet.',a:'Ungeachtet',o:['Ungeachtet dass','Gleichwohl','Indes'],ex:'Here <i>ungeachtet</i> is a preposition with the Genitiv: ungeachtet aller Bedenken.',tr:'Notwithstanding all reservations the draft was passed.',say:'Ungeachtet aller Bedenken wurde der Entwurf verabschiedet.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Er beherrscht kein Russisch, ___ Japanisch.',a:'geschweige denn',o:['sondern auch','zumal','insofern als'],ex:'<i>geschweige denn</i> needs a preceding negation and adds the harder case, with the verb left out.',tr:'He does not know Russian, let alone Japanese.',say:'Er beherrscht kein Russisch, geschweige denn Japanisch.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Die Kritik trifft zu, ___ sie allein die Kosten betrifft.',a:'insofern als',o:['insofern dass','sofern als','soweit als'],ex:'The fixed academic form is <b>insofern als</b> (also written „insofern, als“): valid only to this extent.',tr:'The criticism is valid in so far as it concerns the costs alone.',say:'Die Kritik trifft zu, insofern als sie allein die Kosten betrifft.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Die Nachfrage brach ein; die Preise blieben ___ stabil.',a:'indes',o:['obwohl','sofern','ungeachtet'],ex:'<i>indes</i> is a high-register adverb meaning „however“; it sits inside the clause and changes no word order.',tr:'Demand collapsed; prices, however, remained stable.',say:'Die Nachfrage brach ein; die Preise blieben indes stabil.'},
{gid:'konnektoren-c1',lv:6,sk:'Connectors',s:'Nichtsdestotrotz ___ die Behörde an ihrer Auffassung fest.',a:'hält',o:['halten','festhält','hielte'],ex:'The adverb fills the Vorfeld, so the finite verb is second and the separable prefix „fest“ closes the bracket.',tr:'Nonetheless the authority sticks to its view.',say:'Nichtsdestotrotz hält die Behörde an ihrer Auffassung fest.'},

/* --- passiv-alternativen-c1 --- */
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Die Frist ___ sich nicht verlängern.',a:'lässt',o:['wird','ist','kann'],ex:'sich lassen + Infinitiv expresses possibility: the deadline cannot be extended.',tr:'The deadline cannot be extended.',say:'Die Frist lässt sich nicht verlängern.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Der Antrag ___ bis zum 30. April schriftlich einzureichen.',a:'ist',o:['wird','hat','lässt'],ex:'sein + zu + Infinitiv states the obligation: the application must be submitted.',tr:'The application must be submitted in writing by 30 April.',say:'Der Antrag ist bis zum dreißigsten April schriftlich einzureichen.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'___ geht davon aus, dass die Zahlen revidiert werden müssen.',a:'Man',o:['Es','Sich','Einer'],ex:'<i>man</i> + active is the neutral substitute for the passive when the agent is unknown but human.',tr:'It is assumed that the figures will have to be revised.',say:'Man geht davon aus, dass die Zahlen revidiert werden müssen.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Die betroffenen Haushalte ___ die Mehrkosten erstattet.',a:'bekommen',o:['werden','haben','lassen'],ex:'The bekommen-Passiv promotes the Dativ participant to subject: the households get the costs reimbursed.',tr:'The affected households get the extra costs reimbursed.',say:'Die betroffenen Haushalte bekommen die Mehrkosten erstattet.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Die neue Regelung ___ erst ab Januar Anwendung.',a:'findet',o:['macht','nimmt','hat'],ex:'The Funktionsverbgefüge is „Anwendung finden“ = to apply. „machen“ and „nehmen“ do not combine with Anwendung.',tr:'The new rule only applies from January onwards.',say:'Die neue Regelung findet erst ab Januar Anwendung.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Der Befund ist ohne weiteres ___.',a:'nachvollziehbar',o:['nachvollziehlich','nachvollziehend','nachvollzogen bar'],ex:'-bar on a transitive verb makes possibility into a property: nachvollziehen → nachvollziehbar.',tr:'The finding is easily comprehensible.',say:'Der Befund ist ohne weiteres nachvollziehbar.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Die Unterlagen ___ unverzüglich nachzureichen; eine Fristverlängerung ist ausgeschlossen.',a:'sind',o:['lassen sich','werden','haben'],ex:'„unverzüglich“ and the second clause force the obligation reading, so only sein + zu + Infinitiv fits; „lassen sich“ would claim it is merely easy.',tr:'The documents must be submitted without delay; an extension is ruled out.',say:'Die Unterlagen sind unverzüglich nachzureichen; eine Fristverlängerung ist ausgeschlossen.'},
{gid:'passiv-alternativen-c1',lv:6,sk:'Passive',s:'Es ___ darauf hingewiesen, dass die Angaben unvollständig sind.',a:'wird',o:['ist','hat','lässt'],ex:'Here the real werden-passive is right: „es“ only holds the Vorfeld, and hinweisen auf keeps its preposition in „darauf“.',tr:'Attention is drawn to the fact that the information is incomplete.',say:'Es wird darauf hingewiesen, dass die Angaben unvollständig sind.'},

/* --- modalitaet --- */
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Die Verzögerung ___ auf einen Formfehler zurückzuführen sein.',a:'dürfte',o:['darf','muss nicht','will'],ex:'<i>dürfte</i> is the polite, probable inference: it is presumably due to a procedural error. It is never permission in this use.',tr:'The delay is probably due to a procedural error.',say:'Die Verzögerung dürfte auf einen Formfehler zurückzuführen sein.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Der Bericht ___ bereits im Mai vorgelegen haben.',a:'soll',o:['will','darf','mag nicht'],ex:'<i>soll</i> + Infinitiv Perfekt reports what others claim, with the speaker taking no responsibility.',tr:'The report is said to have been available as early as May.',say:'Der Bericht soll bereits im Mai vorgelegen haben.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Der Antragsteller ___ davon nichts gewusst haben.',a:'will',o:['soll','möchte','dürfte'],ex:'<i>will</i> marks a claim the subject makes about himself, with audible doubt from the speaker.',tr:'The applicant claims to have known nothing about it.',say:'Der Antragsteller will davon nichts gewusst haben.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Das ___ auf den ersten Blick überzeugen, hält aber der Prüfung nicht stand.',a:'mag',o:['darf','will','soll'],ex:'<i>mag</i> concedes a possibility before the objection — the classic „that may be so, but …“ move.',tr:'That may be convincing at first sight but does not stand up to scrutiny.',say:'Das mag auf den ersten Blick überzeugen, hält aber der Prüfung nicht stand.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Er ___ den Brief erhalten haben, denn er zitiert daraus.',a:'muss',o:['darf','soll','mag'],ex:'Evidence that admits no other explanation → <i>muss</i> as a near-certain inference, not as an obligation.',tr:'He must have received the letter, since he quotes from it.',say:'Er muss den Brief erhalten haben, denn er zitiert daraus.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Er ___ nicht kommen — es ist ihm ausdrücklich untersagt.',a:'darf',o:['muss','braucht','mag'],ex:'Prohibition is „darf nicht“. „muss nicht“ would mean he is not obliged to come.',tr:'He is not allowed to come — it is expressly forbidden.',say:'Er darf nicht kommen — es ist ihm ausdrücklich untersagt.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Der Sprecher erklärte, die Zahlen ___ korrekt.',a:'seien',o:['sind','seid','werden'],ex:'Konjunktiv I in reported speech is a modality marker: these are his words, not the writer’s claim.',tr:'The spokesman said the figures were correct.',say:'Der Sprecher erklärte, die Zahlen seien korrekt.'},
{gid:'modalitaet',lv:6,sk:'Verbs',s:'Sie kann das nicht ___ haben, die Mitteilung kam erst später.',a:'gewusst',o:['wissen','zu wissen','gewisst'],ex:'A subjective modal about the past takes the Infinitiv Perfekt: Partizip II + haben → „gewusst haben“.',tr:'She cannot have known that; the notification only came later.',say:'Sie kann das nicht gewusst haben, die Mitteilung kam erst später.'},

/* --- partizipialsaetze --- */
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'In Berlin ___, rief er sofort an.',a:'angekommen',o:['ankommend','angekommt','zu kommen'],ex:'Partizip II of ankommen for a completed prior event; the shared subject „er“ is left out.',tr:'Having arrived in Berlin, he called immediately.',say:'In Berlin angekommen, rief er sofort an.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'Von allen Seiten ___, zog der Minister den Entwurf zurück.',a:'kritisiert',o:['kritisierend','zu kritisieren','kritisiert worden'],ex:'Partizip II also carries the passive reading: he was the one being criticised. „worden“ is never used in the participial clause.',tr:'Criticised from all sides, the minister withdrew the draft.',say:'Von allen Seiten kritisiert, zog der Minister den Entwurf zurück.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'___ mit dem Vorjahr, fiel das Ergebnis schwach aus.',a:'Verglichen',o:['Vergleichend','Vergleich','Zu vergleichen'],ex:'„verglichen mit + Dativ“ is a lexicalised participle; the active „vergleichend“ would need somebody doing the comparing.',tr:'Compared with the previous year, the result was weak.',say:'Verglichen mit dem Vorjahr, fiel das Ergebnis schwach aus.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'___ an den Zielen des Programms, ist das Ergebnis enttäuschend.',a:'Gemessen',o:['Messend','Gemessene','Zu messen'],ex:'„gemessen an + Dativ“ = measured against; another frozen participle that no longer obeys the subject rule.',tr:'Measured against the aims of the programme, the result is disappointing.',say:'Gemessen an den Zielen des Programms, ist das Ergebnis enttäuschend.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'Ein Glas Wasser in der Hand ___, trat er ans Mikrofon.',a:'haltend',o:['gehalten','halten','zu halten'],ex:'Simultaneous and active → Partizip I. Partizip II would make him the one being held.',tr:'Holding a glass of water, he stepped up to the microphone.',say:'Ein Glas Wasser in der Hand haltend, trat er ans Mikrofon.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'___ genommen handelt es sich um zwei getrennte Verfahren.',a:'Streng',o:['Strenge','Strengem','Strengen'],ex:'„streng genommen“ (strictly speaking) is fixed and uninflected, like „genau genommen“ and „grob gerechnet“.',tr:'Strictly speaking, these are two separate proceedings.',say:'Streng genommen handelt es sich um zwei getrennte Verfahren.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'Auf die Vorwürfe angesprochen, ___ der Sprecher auf das laufende Verfahren.',a:'verwies',o:['wurde verwiesen','verweisend','verwiesen'],ex:'The participle’s implied subject must be the main clause subject, so the main clause needs an active verb with „der Sprecher“ as subject.',tr:'Asked about the accusations, the spokesman referred to the ongoing proceedings.',say:'Auf die Vorwürfe angesprochen, verwies der Sprecher auf das laufende Verfahren.'},
{gid:'partizipialsaetze',lv:6,sk:'Clauses',s:'___ von den vorliegenden Zahlen, erscheint eine Korrektur unvermeidlich.',a:'Ausgehend',o:['Ausgegangen','Ausgang','Auszugehen'],ex:'„ausgehend von + Dativ“ is the fixed form; note that the Vorfeld participle keeps the finite verb in second position.',tr:'Starting from the available figures, a correction seems unavoidable.',say:'Ausgehend von den vorliegenden Zahlen, erscheint eine Korrektur unvermeidlich.'},

/* --- wortbildung --- */
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'___ Wirtschaftlichkeitsprüfung dauerte drei Monate.',a:'Die',o:['Der','Das','Dem'],ex:'The head is the last element, Prüfung; nouns in -ung are always feminine, whatever the compound contains.',tr:'The cost-effectiveness audit lasted three months.',say:'Die Wirtschaftlichkeitsprüfung dauerte drei Monate.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Die Zahlung___frist endet am Monatsende.',a:'s',o:['es','n','en'],ex:'After the suffix -ung the Fugenelement is -s-: Zahlungsfrist, Prüfungsordnung, Wohnungssuche.',tr:'The payment deadline ends at the end of the month.',say:'Die Zahlungsfrist endet am Monatsende.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Die Straße___bahn hält direkt vor dem Gebäude.',a:'n',o:['s','es','en'],ex:'Feminines ending in -e take -n- as the joint: Straßenbahn, Sonnenenergie, Kirchenfenster.',tr:'The tram stops right in front of the building.',say:'Die Straßenbahn hält direkt vor dem Gebäude.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Auf der Tag___ordnung stehen fünf Punkte.',a:'es',o:['s','n','e'],ex:'A few monosyllables take -es-: Tagesordnung, Tageslicht, Landesgrenze.',tr:'There are five items on the agenda.',say:'Auf der Tagesordnung stehen fünf Punkte.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'___ Nachhaltigkeitsbericht erscheint im Frühjahr.',a:'Der',o:['Die','Das','Den'],ex:'The head is Bericht, which is masculine; the first element only modifies it.',tr:'The sustainability report will appear in spring.',say:'Der Nachhaltigkeitsbericht erscheint im Frühjahr.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Der Vorgang ist ohne weiteres ___ — man kann ihn Schritt für Schritt verfolgen.',a:'nachvollziehbar',o:['nachvollziehlich','nachvollziehsam','nachvollzogen'],ex:'-bar attaches to transitive verbs and means „can be done“; nachvollziehen takes an object, so nachvollziehbar is well formed.',tr:'The process is easily comprehensible — you can follow it step by step.',say:'Der Vorgang ist ohne weiteres nachvollziehbar — man kann ihn Schritt für Schritt verfolgen.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Der Uferweg ist bei Hochwasser nicht ___.',a:'begehbar',o:['gehbar','gehlich','begehlich'],ex:'gehen takes no object, so there is no *gehbar; the prefix be- makes it transitive (einen Weg begehen) and only then -bar can attach.',tr:'The riverside path is not passable when the water is high.',say:'Der Uferweg ist bei Hochwasser nicht begehbar.'},
{gid:'wortbildung',lv:6,sk:'Vocabulary',s:'Wir haben den Antrag anhand ___ Genehmigungsverfahrens geprüft.',a:'des',o:['der','dem','das'],ex:'Head = das Verfahren, so the compound is neuter, and anhand takes the Genitiv: des Genehmigungsverfahrens.',tr:'We examined the application on the basis of the approval procedure.',say:'Wir haben den Antrag anhand des Genehmigungsverfahrens geprüft.'},

/* --- negation-skopus --- */
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Es gibt ___ Grund, die Frist zu verlängern.',a:'keinen',o:['nicht','nicht einen','keinem'],ex:'A noun with no article is negated with <i>kein</i>; „Grund“ is a masculine accusative object → keinen.',tr:'There is no reason to extend the deadline.',say:'Es gibt keinen Grund, die Frist zu verlängern.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'___ der Inhalt ist umstritten, sondern das Verfahren.',a:'Nicht',o:['Kein','Keiner','Nichts'],ex:'Constituent negation puts <i>nicht</i> directly before the denied element; with a definite article „kein“ is impossible.',tr:'It is not the content that is disputed but the procedure.',say:'Nicht der Inhalt ist umstritten, sondern das Verfahren.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Das Verfahren ist weder zweckmäßig ___ zulässig.',a:'noch',o:['oder','nicht','auch nicht'],ex:'weder … noch negates two elements at once; it already contains the negation, so nothing more may be added.',tr:'The procedure is neither expedient nor permissible.',say:'Das Verfahren ist weder zweckmäßig noch zulässig.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Der Hinweis findet sich ___ in den Unterlagen.',a:'nirgends',o:['niemand','nichts','nie'],ex:'Place is negated by <i>nirgends</i> (or nirgendwo); <i>nie</i> would negate the time, <i>niemand</i> a person.',tr:'The note is nowhere to be found in the documents.',say:'Der Hinweis findet sich nirgends in den Unterlagen.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Er ___ nicht kündigen — es ist ihm vertraglich untersagt.',a:'darf',o:['muss','braucht','will'],ex:'With <i>dürfen</i> the negation falls inside the modal’s scope: prohibition. „muss nicht“ would mean he is not required to.',tr:'He is not allowed to resign — it is contractually forbidden.',say:'Er darf nicht kündigen — es ist ihm vertraglich untersagt.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Nicht morgen, ___ übermorgen beginnt die Prüfung.',a:'sondern',o:['aber','doch','jedoch'],ex:'After a negation the contrast is always <i>sondern</i>; <i>aber</i> cannot pick up a negated element.',tr:'The audit begins not tomorrow but the day after.',say:'Nicht morgen, sondern übermorgen beginnt die Prüfung.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Der Vorwurf ist nicht ___ — er trifft einen wirklichen Schwachpunkt.',a:'unberechtigt',o:['berechtigt','rechtlos','unrechtmäßig'],ex:'„nicht un-“ is deliberate litotes: not unjustified = partly justified. „nicht berechtigt“ would say the opposite.',tr:'The accusation is not unjustified — it hits a real weak point.',say:'Der Vorwurf ist nicht unberechtigt — er trifft einen wirklichen Schwachpunkt.'},
{gid:'negation-skopus',lv:6,sk:'Sentences',s:'Es blieb ohne Folgen, dass die Frist nicht eingehalten ___.',a:'wurde',o:['wurden','worden','ist worden'],ex:'In the dass-clause the verb cluster closes the sentence and <i>nicht</i> stands immediately before it; „die Frist“ is singular → wurde.',tr:'The fact that the deadline was not met had no consequences.',say:'Es blieb ohne Folgen, dass die Frist nicht eingehalten wurde.'},

/* --- genitiv-c1 --- */
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Der Vorwurf bedarf ___ sorgfältigen Prüfung.',a:'einer',o:['eine','einen','einem'],ex:'<i>bedürfen</i> governs the Genitiv: einer sorgfältigen Prüfung.',tr:'The accusation requires careful examination.',say:'Der Vorwurf bedarf einer sorgfältigen Prüfung.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Man beschuldigte die Firma ___ Steuerhinterziehung.',a:'der',o:['die','mit der','für die'],ex:'jemanden einer Sache beschuldigen: accusative person, genitive thing.',tr:'The company was accused of tax evasion.',say:'Man beschuldigte die Firma der Steuerhinterziehung.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Ich bin mir ___ Tragweite dieser Entscheidung bewusst.',a:'der',o:['die','über die','von der'],ex:'sich einer Sache bewusst sein takes the Genitiv — no preposition, unlike English „aware of“.',tr:'I am aware of the significance of this decision.',say:'Ich bin mir der Tragweite dieser Entscheidung bewusst.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'___ der Datenlage ist Zurückhaltung geboten.',a:'Angesichts',o:['Angesicht','Gegenüber','Entgegen'],ex:'<i>angesichts</i> + Genitiv = in view of. „gegenüber“ and „entgegen“ take the Dativ.',tr:'In view of the data, restraint is called for.',say:'Angesichts der Datenlage ist Zurückhaltung geboten.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Der Ausschuss enthielt sich ___ Stimme.',a:'der',o:['die','von der','mit der'],ex:'sich der Stimme enthalten — a fixed genitive object, the formal way to say „abstain“.',tr:'The committee abstained from voting.',say:'Der Ausschuss enthielt sich der Stimme.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Trotz ___ Regens fand die Veranstaltung statt.',a:'des',o:['dem','den','der'],ex:'In writing <i>trotz</i> takes the Genitiv: des Regens. „trotz dem Regen“ is spoken usage only.',tr:'Despite the rain the event took place.',say:'Trotz des Regens fand die Veranstaltung statt.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'Die Angabe ___ Namens ist unvollständig.',a:'des',o:['dem','der','den'],ex:'„der Name“ follows the n-declension: Genitiv Singular des Namens, with -ns.',tr:'The statement of the name is incomplete.',say:'Die Angabe des Namens ist unvollständig.'},
{gid:'genitiv-c1',lv:6,sk:'Cases',s:'___ Erachtens greift diese Begründung zu kurz.',a:'Meines',o:['Mein','Meinem','Meiner'],ex:'„meines Erachtens“ is a frozen genitive adverbial, like „meines Wissens“ and „letzten Endes“.',tr:'In my view this justification falls short.',say:'Meines Erachtens greift diese Begründung zu kurz.'},

/* --- thema-rhema --- */
{gid:'thema-rhema',lv:6,sk:'Style',s:'Der Entwurf liegt seit Montag vor. ___ hat der Betriebsrat Einwände erhoben.',a:'Dagegen',o:['Dafür','Darüber','Davon'],ex:'Einwände erheben <b>gegen</b> etwas → the pronominal adverb „dagegen“, which also links the sentence back.',tr:'The draft has been available since Monday. The works council has raised objections to it.',say:'Der Entwurf liegt seit Montag vor. Dagegen hat der Betriebsrat Einwände erhoben.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Die Frist wurde versäumt. ___ beruft sich die Gegenseite.',a:'Darauf',o:['Dafür','Damit','Dazu'],ex:'sich berufen <b>auf</b> + Akkusativ → darauf. Putting it in the Vorfeld keeps the known information first.',tr:'The deadline was missed. The other side is relying on that.',say:'Die Frist wurde versäumt. Darauf beruft sich die Gegenseite.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Es wurden keine Unterlagen übermittelt. ___ erschwert die Bewertung erheblich.',a:'Dies',o:['Diesen','Dessen','Deren'],ex:'<i>dies</i> takes up a whole preceding clause as the subject of the next sentence — the cheapest cohesion device German has.',tr:'No documents were submitted. This makes the assessment considerably harder.',say:'Es wurden keine Unterlagen übermittelt. Dies erschwert die Bewertung erheblich.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Zwei Varianten wurden geprüft. ___ die zweite spricht vor allem der Preis.',a:'Für',o:['Über','An','Zu'],ex:'sprechen <b>für</b> etwas = to speak in favour of; the known element („die zweite“) stays early, the new one („der Preis“) lands at the end.',tr:'Two variants were examined. The second is favoured above all by the price.',say:'Für die zweite spricht vor allem der Preis.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Der Ausschuss hat den Bericht angefordert. ___ wurde er bis heute nicht.',a:'Vorgelegt',o:['Vorlegen','Vorlage','Vorzulegen'],ex:'The participle in the Vorfeld plus the passive lets the known „Bericht“ stay as „er“ and pushes the news to the end.',tr:'The committee requested the report. To this day it has not been submitted.',say:'Vorgelegt wurde er bis heute nicht.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Der Antrag war seit Mai bekannt. Abgelehnt ___ er erst im September.',a:'wurde',o:['war','ist','hat'],ex:'Präteritum passive: wurde + Partizip II. The participle in the Vorfeld signals the contrast with the known fact.',tr:'The application had been known since May. It was only rejected in September.',say:'Abgelehnt wurde er erst im September.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'___ wurden drei Varianten geprüft; die dritte erwies sich als die günstigste.',a:'Es',o:['Das','Dies','Man'],ex:'When everything in the sentence is new, the placeholder „es“ fills the Vorfeld and the news follows. „man“ would require an active verb.',tr:'Three variants were examined; the third turned out to be the cheapest.',say:'Es wurden drei Varianten geprüft; die dritte erwies sich als die günstigste.'},
{gid:'thema-rhema',lv:6,sk:'Style',s:'Der Bericht wurde im Mai angefordert, aber bis heute nicht ___.',a:'vorgelegt',o:['vorlegen','vorgelegen','vorzulegen'],ex:'The second half shares subject and auxiliary, so only the Partizip II is repeated — and the negation stands directly before it.',tr:'The report was requested in May but has not been submitted to this day.',say:'Der Bericht wurde im Mai angefordert, aber bis heute nicht vorgelegt.'},

/* --- verbaspekt --- */
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Wir ___ seit zwei Jahren an diesem Verfahren.',a:'arbeiten',o:['haben gearbeitet','sind am Arbeiten','arbeiteten'],ex:'A situation that still holds takes the Präsens with <i>seit</i>; the perfect would say the work is over.',tr:'We have been working on this procedure for two years.',say:'Wir arbeiten seit zwei Jahren an diesem Verfahren.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Die Kommission ist ___, die Kriterien zu überarbeiten.',a:'dabei',o:['daran','am','gerade am'],ex:'„dabei sein, etwas zu tun“ is the neutral written progressive; the am-form belongs to speech.',tr:'The commission is in the process of revising the criteria.',say:'Die Kommission ist dabei, die Kriterien zu überarbeiten.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Ich habe das Gutachten über Nacht ___.',a:'durchgelesen',o:['gelesen durch','durchlesen','verlesen'],ex:'The prefix durch- adds the aspect „from end to end“; as a separable prefix it takes -ge- in the middle: durchgelesen.',tr:'I read the whole report overnight.',say:'Ich habe das Gutachten über Nacht durchgelesen.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Erst im Gespräch habe ich von der Entscheidung ___.',a:'erfahren',o:['gewusst','gekannt','erkannt'],ex:'<i>wissen</i> is the state, <i>erfahren</i> the change of state (to find out) — German splits lexically what English leaves to context.',tr:'I only found out about the decision in the conversation.',say:'Erst im Gespräch habe ich von der Entscheidung erfahren.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Nach dem langen Flug bin ich sofort ___.',a:'eingeschlafen',o:['geschlafen','schlafend','einschlafen'],ex:'schlafen = to be asleep (state), einschlafen = to fall asleep (change of state), with sein as its auxiliary.',tr:'After the long flight I fell asleep immediately.',say:'Nach dem langen Flug bin ich sofort eingeschlafen.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'___ Durchsehen der Zahlen fiel die Abweichung auf.',a:'Beim',o:['Am','Im','Zum'],ex:'bei + nominalised infinitive expresses simultaneity: while going through the figures.',tr:'When going through the figures, the discrepancy stood out.',say:'Beim Durchsehen der Zahlen fiel die Abweichung auf.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'Wir haben das Thema inzwischen ___ — weitere Sitzungen sind nicht nötig.',a:'ausdiskutiert',o:['ausdiskutierend','diskutiert aus','ausgediskutiert'],ex:'aus- marks the action carried through to its end. The verb is inseparable in the participle: ausdiskutiert, with no -ge-.',tr:'We have now discussed the topic through to the end — further meetings are not needed.',say:'Wir haben das Thema inzwischen ausdiskutiert — weitere Sitzungen sind nicht nötig.'},
{gid:'verbaspekt',lv:6,sk:'Verbs',s:'In diesem Moment ___ sie die Unterlagen.',a:'prüft',o:['ist prüfend','ist am prüfen','prüft gerade am'],ex:'German has no progressive form: the simple Präsens plus a time adverbial does the whole job.',tr:'At this moment she is examining the documents.',say:'In diesem Moment prüft sie die Unterlagen.'},

/* --- ellipse --- */
{gid:'ellipse',lv:6,sk:'Style',s:'Ich habe es nie behauptet und ___ es nie behaupten.',a:'werde',o:['wird','werde ich','habe'],ex:'The subject is shared, so it is dropped — but each half keeps its own verb form: Partizip in the first, Infinitiv in the second.',tr:'I have never claimed it and never will claim it.',say:'Ich habe es nie behauptet und werde es nie behaupten.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Sie wollte widersprechen, ___ sich aber nicht.',a:'traute',o:['getraut','traut','hat getraut'],ex:'Coordination drops the shared subject; the tense must match the first half, so Präteritum traute.',tr:'She wanted to object but did not dare.',say:'Sie wollte widersprechen, traute sich aber nicht.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Das Ergebnis fiel schlechter aus, ___ der Vorstand erwartet hatte.',a:'als',o:['wie','als wenn','dass'],ex:'After a comparative the comparison is introduced by <i>als</i> and sits in the Nachfeld, behind the closed bracket.',tr:'The result turned out worse than the board had expected.',say:'Das Ergebnis fiel schlechter aus, als der Vorstand erwartet hatte.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Er hat alles unterschrieben, ___ ihm vorgelegt wurde.',a:'was',o:['das','welches','dass'],ex:'After the indefinite <i>alles</i> the relative pronoun is <b>was</b>; the clause stands in the Nachfeld.',tr:'He signed everything that was put in front of him.',say:'Er hat alles unterschrieben, was ihm vorgelegt wurde.'},
{gid:'ellipse',lv:6,sk:'Style',s:'___ wurde nur die Form, nicht der Inhalt.',a:'Geprüft',o:['Prüfen','Prüfung','Zu prüfen'],ex:'The participle moves into the Vorfeld and the second predicate is left out entirely — „nicht der Inhalt“ carries it.',tr:'Only the form was examined, not the content.',say:'Geprüft wurde nur die Form, nicht der Inhalt.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Aushang im Treppenhaus: „___ nur für Befugte.“',a:'Zutritt',o:['Der Zutritt','Zutreten','Zutritte'],ex:'Notice style drops both the article and the finite verb: „Zutritt nur für Befugte“ = Der Zutritt ist nur für Befugte erlaubt.',tr:'Notice in the stairwell: „Access for authorised persons only.“',say:'Zutritt nur für Befugte.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Wir haben mit ihm gesprochen und ___ geschrieben.',a:'ihm',o:['mit ihm','ihn','mit ihn'],ex:'No ellipsis is licensed here: sprechen takes „mit + Dativ“, schreiben a bare Dativ object. Different forms, so the pronoun must be repeated.',tr:'We have spoken to him and written to him.',say:'Wir haben mit ihm gesprochen und ihm geschrieben.'},
{gid:'ellipse',lv:6,sk:'Style',s:'Das Problem wurde erkannt; gelöst ___ es bis heute nicht.',a:'wurde',o:['ist','hat','worden'],ex:'Splitting the overloaded coordination gives each clause its own auxiliary; the participle in the Vorfeld marks the contrast.',tr:'The problem was recognised; it has not been solved to this day.',say:'Das Problem wurde erkannt; gelöst wurde es bis heute nicht.'},

/* --- praepositionalgefuege --- */
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'___ Bezug auf die Fristen bestehen weiterhin Unklarheiten.',a:'In',o:['Im','Mit','Unter'],ex:'The phrase is fixed as <b>in Bezug auf</b> + Akkusativ. „im Bezug auf“ is the most common spelling error in German business letters.',tr:'With regard to the deadlines, uncertainties remain.',say:'In Bezug auf die Fristen bestehen weiterhin Unklarheiten.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'___ Hinblick auf die kommende Prüfung wurden die Unterlagen vervollständigt.',a:'Im',o:['In','Mit','Unter'],ex:'Mirror image of the last one: <b>im Hinblick auf</b> keeps the article, „in Hinblick“ does not exist.',tr:'In view of the upcoming audit the documents were completed.',say:'Im Hinblick auf die kommende Prüfung wurden die Unterlagen vervollständigt.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'Unter Berücksichtigung ___ Einwände wurde der Entwurf überarbeitet.',a:'aller',o:['alle','allen','allem'],ex:'unter Berücksichtigung + Genitiv; „all-“ in the genitive plural is aller.',tr:'Taking all objections into account, the draft was revised.',say:'Unter Berücksichtigung aller Einwände wurde der Entwurf überarbeitet.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'___ der Umstrukturierung wurden zwei Abteilungen zusammengelegt.',a:'Im Zuge',o:['Im Zug','In Zuge','Am Zuge'],ex:'<b>im Zuge</b> + Genitiv = in the course of. The noun keeps its dative -e, and „im Zug“ means on the train.',tr:'In the course of the restructuring two departments were merged.',say:'Im Zuge der Umstrukturierung wurden zwei Abteilungen zusammengelegt.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'___ der vorliegenden Daten lässt sich das nicht entscheiden.',a:'Anhand',o:['Kraft','Zwecks','Mangels'],ex:'All four take the Genitiv, but only <i>anhand</i> means „using as evidence“. <i>mangels</i> would contradict „vorliegend“, <i>kraft</i> needs an authority, <i>zwecks</i> a purpose.',tr:'On the basis of the available data this cannot be decided.',say:'Anhand der vorliegenden Daten lässt sich das nicht entscheiden.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'___ seines Amtes kann der Vorsitzende die Sitzung unterbrechen.',a:'Kraft',o:['Anhand','Zwecks','Mangels'],ex:'<i>kraft</i> + Genitiv = by virtue of a formal authority. This is legal register and has nothing to do with physical strength.',tr:'By virtue of his office the chair may suspend the session.',say:'Kraft seines Amtes kann der Vorsitzende die Sitzung unterbrechen.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'Die Zahlung wird ___ Überprüfung der Angaben zurückgestellt.',a:'zwecks',o:['anhand','kraft','mangels'],ex:'Purpose in administrative register → <i>zwecks</i> + Genitiv, typically with no article. In a customer letter you would write „um die Angaben zu überprüfen“.',tr:'The payment is being withheld for the purpose of checking the information.',say:'Die Zahlung wird zwecks Überprüfung der Angaben zurückgestellt.'},
{gid:'praepositionalgefuege',lv:6,sk:'Prepositions',s:'Im Falle ___ Widerspruchs verlängert sich die Frist.',a:'eines',o:['einem','ein','einer'],ex:'im Falle + Genitiv; der Widerspruch is masculine, so eines Widerspruchs, with the -s on the noun too.',tr:'In the event of an objection the deadline is extended.',say:'Im Falle eines Widerspruchs verlängert sich die Frist.'},

/* --- stilebenen --- */
{gid:'stilebenen',lv:7,sk:'Style',s:'In einem Beschwerdebrief: „Wir haben Ihre Mitteilung vom 3. Mai ___.“',a:'erhalten',o:['gekriegt','abbekommen','eingesackt'],ex:'<i>erhalten</i> is the formal register; <i>kriegen</i> and its relatives are colloquial and out of place in a letter of complaint.',tr:'In a letter of complaint: „We have received your notification of 3 May.“',say:'Wir haben Ihre Mitteilung vom dritten Mai erhalten.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'In einem Nachruf: „Der Gründer ist im Jahr 2019 ___.“',a:'verstorben',o:['abgekratzt','draufgegangen','weggestorben'],ex:'An obituary needs the gehobene Ebene: <i>versterben</i> (or <i>entschlafen</i>). The distractors are derb or salopp and would be an insult here.',tr:'In an obituary: „The founder passed away in 2019.“',say:'Der Gründer ist im Jahr zweitausendneunzehn verstorben.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'Salopp im Gespräch: „Er hat jahrelang in der Werkstatt ___.“',a:'geschuftet',o:['gewirkt','firmiert','residiert'],ex:'<i>schuften</i> is the salopp word for hard physical work; <i>wirken</i> is gehoben and would sound comic about a workshop.',tr:'Casually, in conversation: „He slogged away in the workshop for years.“',say:'Er hat jahrelang in der Werkstatt geschuftet.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'Neutral statt „labern“: „Die Beteiligten haben über zwei Stunden ___.“',a:'gesprochen',o:['gelabert','geschwatzt','sich ergangen'],ex:'The neutral level is <i>sprechen</i>; <i>labern</i> and <i>schwatzen</i> carry contempt, and „sich ergehen“ needs an object phrase.',tr:'Neutral instead of „labern“: „Those involved talked for more than two hours.“',say:'Die Beteiligten haben über zwei Stunden gesprochen.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'Amtlich: „Die Gebühr ist bis zum Monatsende zu ___.“',a:'entrichten',o:['berappen','abdrücken','rausrücken'],ex:'<i>entrichten</i> is the administrative verb for paying a fee; all three distractors are colloquial words for handing over money unwillingly.',tr:'Official: „The fee is to be paid by the end of the month.“',say:'Die Gebühr ist bis zum Monatsende zu entrichten.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'„Hinsichtlich der Vorwürfe haben wir keinen ___ auf weitere Diskussionen“ — hier bricht das Register.',a:'Bock',o:['Anlass','Grund','Bedarf'],ex:'The register break is the salopp „keinen Bock haben“ next to the formal „hinsichtlich“. The other three words would keep the level intact.',tr:'„Regarding the accusations we have no desire for further discussion“ — the register breaks here.',say:'Hinsichtlich der Vorwürfe haben wir keinen Bock auf weitere Diskussionen.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'Gehoben in einem literarischen Essay: „Ihr ___ blieb unbewegt.“',a:'Antlitz',o:['Visage','Fresse','Gesichtsausdruck'],ex:'<i>Antlitz</i> is the gehobene word for face; <i>Visage</i> and <i>Fresse</i> are derb, and <i>Gesichtsausdruck</i> is neutral prose, not literary.',tr:'Elevated, in a literary essay: „Her countenance remained unmoved.“',say:'Ihr Antlitz blieb unbewegt.'},
{gid:'stilebenen',lv:7,sk:'Style',s:'Formell: „Von einer weiteren Stellungnahme sehen wir ___.“',a:'ab',o:['weg','aus','davon ab'],ex:'absehen von + Dativ: the Dativ object is already in the Vorfeld, so only the separable prefix „ab“ closes the bracket.',tr:'Formally: „We refrain from commenting further.“',say:'Von einer weiteren Stellungnahme sehen wir ab.'},

/* --- idiomatische-verbgefuege --- */
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Der Verband ___ scharfe Kritik an dem Entwurf.',a:'übt',o:['macht','nimmt','zieht'],ex:'Kritik <b>üben</b> an + Dativ. „Kritik machen“ does not exist; the alternative is simply „etwas kritisieren“.',tr:'The association sharply criticises the draft.',say:'Der Verband übt scharfe Kritik an dem Entwurf.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Die Behörde hat Maßnahmen gegen die Verzögerungen ___.',a:'ergriffen',o:['gemacht','genommen','gezogen'],ex:'Maßnahmen <b>ergreifen</b> (or treffen) — the verb pictures seizing and acting.',tr:'The authority has taken measures against the delays.',say:'Die Behörde hat Maßnahmen gegen die Verzögerungen ergriffen.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Nach fünf Jahren lässt sich eine erste Bilanz ___.',a:'ziehen',o:['machen','nehmen','üben'],ex:'Bilanz <b>ziehen</b> = to draw a conclusion from the record. <i>ziehen</i> also goes with Konsequenzen and Schlüsse.',tr:'After five years an initial assessment can be made.',say:'Nach fünf Jahren lässt sich eine erste Bilanz ziehen.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Zu diesem Punkt möchte ich keine Stellung ___.',a:'nehmen',o:['machen','üben','legen'],ex:'Stellung <b>nehmen</b> zu + Dativ, and always without an article.',tr:'I do not wish to comment on this point.',say:'Zu diesem Punkt möchte ich keine Stellung nehmen.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Auf Pünktlichkeit ___ der neue Leiter großen Wert.',a:'legt',o:['macht','nimmt','trägt'],ex:'Wert <b>legen</b> auf + Akkusativ = to attach importance to something.',tr:'The new head attaches great importance to punctuality.',say:'Auf Pünktlichkeit legt der neue Leiter großen Wert.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Dem Einwand ist bei der Überarbeitung Rechnung zu ___.',a:'tragen',o:['machen','nehmen','legen'],ex:'einer Sache Rechnung <b>tragen</b> + Dativ = to take something into account. Note the dative object „dem Einwand“.',tr:'The objection must be taken into account in the revision.',say:'Dem Einwand ist bei der Überarbeitung Rechnung zu tragen.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Der Ausschuss hat erhebliche Bedenken ___ das Verfahren angemeldet.',a:'gegen',o:['über','für','an'],ex:'The preposition is part of the unit: Bedenken anmelden <b>gegen</b> + Akkusativ.',tr:'The committee has raised considerable objections to the procedure.',say:'Der Ausschuss hat erhebliche Bedenken gegen das Verfahren angemeldet.'},
{gid:'idiomatische-verbgefuege',lv:7,sk:'Idioms',s:'Die Regelung ___ erst ab Januar zur Anwendung.',a:'kommt',o:['findet','macht','nimmt'],ex:'With „zur Anwendung“ the light verb is <i>kommen</i> (an event); „Anwendung finden“ needs no „zur“ and describes a state.',tr:'The rule only comes to be applied from January.',say:'Die Regelung kommt erst ab Januar zur Anwendung.'},

/* --- rhetorik --- */
{gid:'rhetorik',lv:7,sk:'Style',s:'Antithese: „Gefordert wird Transparenz, ___ wird eine Pressemitteilung.“',a:'geliefert',o:['liefern','Lieferung','zu liefern'],ex:'The figure lives on the exact parallel: Partizip II + wird in both halves, with the two nouns as the opposed poles.',tr:'Antithesis: „Transparency is demanded; a press release is delivered.“',say:'Gefordert wird Transparenz, geliefert wird eine Pressemitteilung.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Klimax: „Es fehlt an Geld, an Personal, an ___ tragfähigen Konzept.“',a:'jedem',o:['jeden','jedes','jeder'],ex:'fehlen an + Dativ; „jedem tragfähigen Konzept“ is the third and heaviest step of the climax.',tr:'Climax: „There is a lack of money, of staff, of any viable concept.“',say:'Es fehlt an Geld, an Personal, an jedem tragfähigen Konzept.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Wende nach der Konzession: „Zugegeben, der Ansatz ist neu. ___: neu ist nicht tragfähig.“',a:'Nur',o:['Und','Also','Dazu'],ex:'The reversal is marked by a single word plus a colon — „Nur:“, „Allerdings:“, „Indes:“ — and then a short sentence.',tr:'Reversal after the concession: „Granted, the approach is new. Only: new is not the same as viable.“',say:'Zugegeben, der Ansatz ist neu. Nur: neu ist nicht tragfähig.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Praeteritio: „Von den Folgekosten will ich gar nicht ___ sprechen.“',a:'erst',o:['nur','schon','noch'],ex:'„gar nicht erst“ is the fixed Praeteritio formula: by refusing to begin, you put the point on the table.',tr:'Praeteritio: „I will not even start on the follow-up costs.“',say:'Von den Folgekosten will ich gar nicht erst sprechen.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Rhetorische Frage: „Wer soll das prüfen, ___ nicht die Aufsicht selbst?“',a:'wenn',o:['als','ob','dass'],ex:'The elliptical „wenn nicht …“ turns the question into an assertion: obviously the supervisory body.',tr:'Rhetorical question: „Who is to examine this, if not the supervisory body itself?“',say:'Wer soll das prüfen, wenn nicht die Aufsicht selbst?'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Anapher: „Niemand hat gewarnt. Niemand hat widersprochen. ___ war zuständig.“',a:'Niemand',o:['Keiner von','Nichts','Niemandem'],ex:'An Anapher repeats the identical opening, and it needs exactly three members to land.',tr:'Anaphora: „Nobody warned. Nobody objected. Nobody was responsible.“',say:'Niemand hat gewarnt. Niemand hat widersprochen. Niemand war zuständig.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Untertreibung: „Das Ergebnis ist nicht ___ Brisanz.“',a:'ohne',o:['mit','von','unter'],ex:'„nicht ohne“ is litotes: it asserts something considerable while appearing to understate it.',tr:'Understatement: „The result is not without explosive force.“',say:'Das Ergebnis ist nicht ohne Brisanz.'},
{gid:'rhetorik',lv:7,sk:'Style',s:'Doppelpunkt-Pointe: „Die Bilanz nach drei Jahren: ein Verfahren ___ Ergebnis.“',a:'ohne',o:['ohne ein','ohne das','ohne dem'],ex:'The pointe after the colon is elliptical and article-free: ohne + Akkusativ, with the bare noun „Ergebnis“.',tr:'Colon pointe: „The record after three years: a procedure without a result.“',say:'Die Bilanz nach drei Jahren: ein Verfahren ohne Ergebnis.'},

/* --- ambiguitaet --- */
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Eindeutig formuliert: „___ alle Einwände wurden geprüft“ — einige also schon.',a:'Nicht',o:['Alle','Keine','Nichts'],ex:'Putting <i>nicht</i> in front of <i>alle</i> negates the quantifier only; „Alle … nicht geprüft“ is read as total negation.',tr:'Unambiguous: „Not all objections were examined“ — so some were.',say:'Nicht alle Einwände wurden geprüft.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Eindeutig: „___ dem Fernglas beobachtete er den Mann“ — er selbst hatte es.',a:'Mit',o:['Durch','Von','Bei'],ex:'Moving the prepositional phrase into the Vorfeld takes away its second possible head („der Mann mit dem Fernglas“).',tr:'Unambiguous: „With the binoculars he watched the man“ — he had them himself.',say:'Mit dem Fernglas beobachtete er den Mann.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Eindeutig: „Das Gutachten der Kommission, ___ im Mai vorgelegt wurde, ist unmissverständlich.“',a:'das',o:['der','die','dessen'],ex:'Agreement decides the attachment: „das“ can only refer to das Gutachten, not to die Kommission.',tr:'Unambiguous: „The commission’s report, which was submitted in May, is unmistakable.“',say:'Das Gutachten der Kommission, das im Mai vorgelegt wurde, ist unmissverständlich.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Objektiver Genitiv aufgelöst: „Die Kritik ___ Minister hält sich in Grenzen.“',a:'am',o:['des','vom','über den'],ex:'„die Kritik des Ministers“ is ambiguous. The objective reading — he is the target — is repaired with the verb’s own preposition: Kritik an + Dativ.',tr:'Objective genitive resolved: „Criticism of the minister is limited.“',say:'Die Kritik am Minister hält sich in Grenzen.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Pronomenbezug geklärt: „Der Vorstand informierte den Betriebsrat; ___ hatte den Bericht bereits erhalten.“',a:'Letzterer',o:['Derselbe','Jener Erste','Dieser Letztere'],ex:'<i>Letzterer</i> points unambiguously at the second of two candidates; <i>derselbe</i> as a pronoun is old officialese, not precision.',tr:'Pronoun reference clarified: „The board informed the works council; the latter had already received the report.“',say:'Der Vorstand informierte den Betriebsrat; Letzterer hatte den Bericht bereits erhalten.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Skopus: „___ der Einwände wurde geprüft“ — kein einziger.',a:'Keiner',o:['Nicht alle','Nichts','Niemand'],ex:'Total negation of a partitive genitive is stated with <i>keiner</i>; „nicht alle“ would mean the opposite.',tr:'Scope: „None of the objections was examined“ — not a single one.',say:'Keiner der Einwände wurde geprüft.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Eindeutig: „Nur ___ Vorstand hat die Kosten geprüft“ — sonst niemand.',a:'der',o:['den','dem','des'],ex:'<i>nur</i> covers whatever follows it, so it must stand before the subject in the Nominativ to exclude everyone else.',tr:'Unambiguous: „Only the board examined the costs“ — nobody else did.',say:'Nur der Vorstand hat die Kosten geprüft.'},
{gid:'ambiguitaet',lv:7,sk:'Style',s:'Reparatur durch Partizipialattribut: „Der ___ Antrag des Vorstands wurde nicht begründet.“',a:'abgelehnte',o:['ablehnende','abgelehnt','ablehnte'],ex:'The Partizip II as an attribute removes the relative clause and with it the attachment ambiguity; after „der“ the weak ending is -e.',tr:'Repair with a participial attribute: „The board’s rejected application was not given any reasons.“',say:'Der abgelehnte Antrag des Vorstands wurde nicht begründet.'},

/* --- korrektur --- */
{gid:'korrektur',lv:7,sk:'Style',s:'Die Gegenseite besteht ___ einer Fristverlängerung.',a:'auf',o:['an','über','für'],ex:'bestehen <b>auf</b> + Dativ = to insist on. The Dativ, not the Akkusativ: this is a state, not a movement.',tr:'The other side insists on an extension of the deadline.',say:'Die Gegenseite besteht auf einer Fristverlängerung.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Das Gutachten besteht ___ drei Teilen.',a:'aus',o:['auf','in','von'],ex:'bestehen <b>aus</b> + Dativ = to consist of. Same verb, different preposition, different meaning.',tr:'The report consists of three parts.',say:'Das Gutachten besteht aus drei Teilen.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Das Problem besteht ___ der fehlenden Zuständigkeit.',a:'in',o:['aus','auf','an'],ex:'bestehen <b>in</b> + Dativ = to consist in, to lie in. Three prepositions, three readings — the classic Rektion test.',tr:'The problem lies in the absence of clear responsibility.',say:'Das Problem besteht in der fehlenden Zuständigkeit.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Ich beziehe mich ___ Ihr Schreiben vom 3. März.',a:'auf',o:['an','über','zu'],ex:'sich beziehen <b>auf</b> + Akkusativ — the standard opening of a German business letter.',tr:'I refer to your letter of 3 March.',say:'Ich beziehe mich auf Ihr Schreiben vom dritten März.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Zwölf Personen haben ___ der Sitzung teilgenommen.',a:'an',o:['in','bei','zu'],ex:'teilnehmen <b>an</b> + Dativ. English „take part in“ tempts you to „in“, which is simply wrong here.',tr:'Twelve people took part in the meeting.',say:'Zwölf Personen haben an der Sitzung teilgenommen.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Der Sprecher erklärte, man ___ die Frist eingehalten.',a:'habe',o:['hat','hätte','haben'],ex:'Reported speech stays in Konjunktiv I throughout: habe, not hat. Switching to the Indikativ would mean the writer vouches for the claim.',tr:'The spokesman said the deadline had been met.',say:'Der Sprecher erklärte, man habe die Frist eingehalten.'},
{gid:'korrektur',lv:7,sk:'Style',s:'Nachdem der Ausschuss den Bericht geprüft ___, fasste er einen Beschluss.',a:'hatte',o:['hat','hätte','habe'],ex:'<i>nachdem</i> demands a step back in time: Plusquamperfekt in the subordinate clause, Präteritum in the main clause.',tr:'After the committee had examined the report, it passed a resolution.',say:'Nachdem der Ausschuss den Bericht geprüft hatte, fasste er einen Beschluss.'},
{gid:'korrektur',lv:7,sk:'Style',s:'In ___ auf die Frist ist noch nichts entschieden.',a:'Bezug',o:['Bezüge','Anbetracht','Rücksicht'],ex:'The fixed phrase is <b>in Bezug auf</b>; „in Anbetracht“ and „mit Rücksicht auf“ carry their own case or preposition and cannot be slotted in here.',tr:'With regard to the deadline nothing has been decided yet.',say:'In Bezug auf die Frist ist noch nichts entschieden.'},

/* --- textsorten --- */
{gid:'textsorten',lv:7,sk:'Style',s:'Protokoll: „Frau Berg erklärt, die Unterlagen ___ vollständig.“',a:'seien',o:['sind','wären','seid'],ex:'Minutes record a statement in Konjunktiv I: the protocol notes the claim without certifying it as fact.',tr:'Minutes: „Ms Berg states that the documents are complete.“',say:'Frau Berg erklärt, die Unterlagen seien vollständig.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Verlaufsprotokoll im Präsens: „Es ___ beschlossen, die Prüfung fortzusetzen.“',a:'wird',o:['ist','hat','sei'],ex:'Decisions in a Verlaufsprotokoll take the present passive with the placeholder „es“: Es wird beschlossen, …',tr:'Minutes in the present tense: „It is resolved to continue the examination.“',say:'Es wird beschlossen, die Prüfung fortzusetzen.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Gutachten: „Es ist ___, dass die Vorgaben nur teilweise eingehalten wurden.“',a:'festzustellen',o:['feststellen','festgestellt','zu feststellen'],ex:'sein + zu + Infinitiv, written as one word with the separable prefix: fest-zu-stellen. This is the signature of the Gutachten.',tr:'Expert opinion: „It must be noted that the requirements were only partly met.“',say:'Es ist festzustellen, dass die Vorgaben nur teilweise eingehalten wurden.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Bericht: „Der Ausschuss ___ am Dienstag, das Verfahren zu verlängern.“',a:'beschloss',o:['beschließt','beschließe','beschlösse'],ex:'A Bericht narrates in the Präteritum. The Präsens would make it a Protokoll or a Kommentar.',tr:'Report: „On Tuesday the committee decided to extend the procedure.“',say:'Der Ausschuss beschloss am Dienstag, das Verfahren zu verlängern.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Bewerbung: „___ verantworte die Planung von drei Standorten.“',a:'Ich',o:['Man','Wir alle','Es'],ex:'An application is written in the first person singular; <i>man</i> hides exactly the person the reader wants to assess.',tr:'Application: „I am responsible for planning three sites.“',say:'Ich verantworte die Planung von drei Standorten.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Bewerbung ohne Weichmacher: „___ mich um die Stelle als Projektleiterin.“',a:'Ich bewerbe',o:['Ich würde gern bewerben','Man bewirbt','Ich möchte bewerben'],ex:'Konjunktiv II hedging reads as unsure in a Bewerbung; the plain Präsens „Ich bewerbe mich …“ is the standard formula.',tr:'Application without hedging: „I am applying for the position of project manager.“',say:'Ich bewerbe mich um die Stelle als Projektleiterin.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Kommentar: „Drei Jahre, zwei Gutachten, keine Entscheidung — das Verfahren ___ selbst das Ergebnis.“',a:'ist',o:['war','sei','wäre'],ex:'A Kommentar argues in the Präsens and in its own voice; Konjunktiv I would turn the verdict into somebody else’s claim.',tr:'Commentary: „Three years, two reports, no decision — the procedure is itself the result.“',say:'Drei Jahre, zwei Gutachten, keine Entscheidung — das Verfahren ist selbst das Ergebnis.'},
{gid:'textsorten',lv:7,sk:'Style',s:'Bericht ohne Wertung: „Eine Begründung ___ nicht mitgeteilt.“',a:'wurde',o:['wurde erschreckenderweise','ist leider','hat man bedauerlicherweise'],ex:'A Bericht states the fact in the Präteritum passive and adds no evaluating adverb — those belong to the Kommentar.',tr:'Report without evaluation: „No reasons were given.“',say:'Eine Begründung wurde nicht mitgeteilt.'}

];
